pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + (post_residual - next_item_size) as f64;
        } else {
            // dead space for next item: penalize proportionally to mismatch
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins tighter than average residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize creating large unusable fragments (post_residual too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New bin candidate: prefer opening a new bin when current open bins are mostly full
    // (i.e., this call is for the empty bin, so bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // favor new bin if existing bins are tight
        if mean_residual < item_size as f64 * 1.2 {
            score -= 80.0;
        } else {
            score += 120.0 + 50.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let rclass = post_residual % 10;
    // Residuals that are "usable" harmonic slots (multiples of common item sizes)
    let usable = (post_residual % 10 == 0) || (post_residual >= 10 && post_residual % 5 == 0);
    if !usable {
        score += 6.0 + (rclass as f64) * 0.7; // penalize dead space in odd classes
    } else {
        score -= 3.0;
    }

    // Integer division thresholds: how many "typical" items (size ~20) still fit
    let fits20 = post_residual / 20;
    score -= fits20 as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item won't fit here; penalize small leftover more
            if post_residual < 10 {
                score += 12.0; // near-wasted bin
            }
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score,
    // discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        score = 45.0 - (open_bins_count as f64) * 0.5 - mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Phase of stream: early, prefer compacting; late, allow spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Tie-break toward filling bins closer to mean residual (balance)
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in the "unusable gap" zone (1..=15)
    // are much worse than large residuals, since small items may still use big gaps.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64);
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward tight fits relative to the residual available.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: penalize opening new bins when many bins exist,
    // but allow it when few bins are open (early stream).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if this is a poor fit everywhere
        // or the item is large relative to typical residual.
        let poor_fit = fitting_bins_count == 0 || (mean_residual < item_size as f64 * 1.15);
        if poor_fit {
            score -= 60.0;
        } else {
            // Slightly discourage wasting a fresh bin when fits exist.
            score += 10.0 + 5.0 * open_bins_count as f64 * progress;
        }
    } else {
        // Placing into an existing bin is generally good: mild reward.
        score -= 5.0;
        // Last-chance bin: strongly favor using the only bin that fits,
        // otherwise this capacity is lost.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement;
    // if post_residual is small and next item is small too, dead space is less risky.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 8.0; // dead space that next item can't use either
        }
    }

    // Mild preference to balance residuals: avoid dumping into already-large-residual bins
    // when mean residual is low (keeps bins uniform).
    if bin_residual as f64 > mean_residual * 1.5 && open_bins_count > 1 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Base: prefer tight fits (small post_residual) ---
    score = post_residual as f64;

    // --- Perfect fit bonus ---
    if post_residual == 0 {
        score -= 500.0;
    }

    // --- Dead-space penalty: residual too small to hold the smallest plausible item ---
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // creates unusable sliver
    }

    // --- Lookahead: strongly reward residuals that can host the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainability bonus scaled by how snugly the next item would fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack * 0.5;
        } else {
            // Penalize if placing here strands the next item into a new bin
            score += 25.0;
        }
    }

    // --- Last-chance pressure: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // --- Many open bins: consolidate, prefer filling existing bins tighter ---
    let crowding = open_bins_count as f64;
    score += (mean_residual - post_residual as f64) * 0.4 * (1.0 + crowding / 50.0);

    // --- Time horizon: early on, be selective (leave room for big items); late, just pack ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if progress < 0.4 {
        // early: penalize large items eating fresh bins? reward placing big items in tight bins
        score += fill_ratio * 20.0 * (1.0 - progress);
    } else {
        // late: urgency to close out bins, reward high fill
        score -= fill_ratio * 40.0 * progress;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin: acceptable when no open bin fits well.
        // Slightly worse than a good existing fit, slightly better than a bad one.
        score = bin_capacity as f64 * 0.55 + item_size as f64 * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin can also host next item
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        }
        if progress > 0.7 && mean_residual < item_size as f64 {
            score -= 40.0; // late stream, existing residuals are poor anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect match — item + next item exactly fills the bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // next item still fits here; penalize leftover gap after both items
            let two_step_left = (post_residual - next_item_size) as f64;
            score += 0.35 * two_step_left;
            // reward moderately for keeping next item placeable
            score -= 25.0;
        } else {
            // next item won't fit: dead space penalty grows as post_residual shrinks
            score += 12.0 + 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer packing into bins that are already relatively full (small residual)
    score += 0.8 * (mean_residual - post_residual as f64);

    // Slight preference for filling existing bins over opening new ones
    // as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    // Penalize new-bin candidate mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Non-linear penalty for tiny unusable remnants
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space that cannot fit the next item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bins pressure: penalize bins in proportion to how many bins are open,
    // pushing toward consolidating into fewer bins unless fit is excellent.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high; only win when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.3;
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pn = pr / bin_capacity as f64;
    let t = progress;
    let coupling = pn * pn * (1.0 - t) * (1.0 - t) + pn * t * t;
    score += 20.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - t) * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * t;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (0.5 + t);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * t;

    // Encourage leaving residuals near mean (balance)
    score += 0.3 * (pr - mean_residual).abs() * t;

    // New-bin candidate: prefer only when residuals are badly fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).min(1.0);
        score = 60.0 + 40.0 * (1.0 - frag) - 30.0 * t * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space: residuals too small for any future item (min item ~1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving post_residual that fits next item, penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when open bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0)).max(0.0);
        score = 55.0 + 20.0 * progress - 0.5 * crowded;
        // If item is large relative to capacity, opening fresh bin is safer.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
        // If next item is large too, fresh bin preserves room.
        if next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild time-horizon coupling: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates far above the mean (fragmented outliers).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that are unlikely to fit typical items.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly (post_residual near zero is ideal).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a good
    // lookahead fit or current open bins have poor residuals.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is more attractive when open bins are crowded.
        score -= open_bins_count as f64 * 0.5;
        // Lookahead: if next item fits nicely in the fresh bin's residual
        // after this placement, soften the penalty.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 15.0;
        }
    }

    // Pressure from number of open bins: discourage spreading items thin.
    score += open_bins_count as f64 * 0.3;

    // Slight preference to keep residuals near the mean (balance load).
    score += ((post_residual as f64 - mean_residual) / 10.0).abs();

    // Lookahead synergy: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (1..=12) are heavily penalized since few items (>=10 originally,
    // small here) can ever use them.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    } else if post_residual > 12 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins below mean residual (filling emptier bins consolidates).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for the next item -> dead space risk.
        score += 12.0;
    }

    // New-bin candidate: only attractive when no open bin offers a tight fit
    // (i.e., all fits would leave large dead space). Penalize mildly otherwise.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 1 {
            score -= 70.0; // opening a bin is fine if nothing else fits well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // If next item fits exactly into post_residual, strongly favor this bin
        if post_residual >= next_item_size {
            score -= 50.0 + 45.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // post_residual too small for next item: penalize proportional to wasted potential
            score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below average (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize creating dead space below the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when open bins would leave large unusable residuals
