    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        // Unusable gap (below minimum item size): heavy penalty scaled by tightness.
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual >= 50 {
        // Large leftover is flexible/reusable: mild reward.
        score -= 8.0;
    }

    // Reward placing item into the tightest possible bin (waste-aware coupling).
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    // --- Open bins pressure ---
    // When many bins are open, discourage opening new bins and encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count and stream progress.
        score += 25.0 + 2.0 * pressure;
    } else {
        // Existing bin: reward scaled by pressure to consolidate.
        score -= pressure;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus for this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this bin achieves a perfect 2-item packing — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits here later; penalize leftover slack proportionally
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: dead space penalty
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are
    // "tight" bins — prefer filling them to consolidate space.
    let tightness = (mean_residual - post_residual as f64).max(0.0);
    score -= 2.5 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize the brand-new bin candidate unless the item is huge
    // relative to residual capacity of open bins (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size > 70 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for near-full outcomes overall.
    score -= 0.1 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize unusable dead space: residuals below the minimum item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        if slack == 0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't host next item: mild penalty, scaled by how close it is.
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer filling existing ones over spreading.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.5 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, allow more new bins (exploration);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = 10.0 * progress;

    // New-bin candidate handling: penalize opening a new bin, more so as the stream progresses
    // or when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += 20.0 + consolidation + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Exception: huge items fit poorly anywhere; a fresh bin gives max future flexibility.
        if item_size >= 70 {
            score -= 25.0;
        }
        // If mean residual across open bins is large, opening a bin is wasteful.
        score += 0.3 * mean_residual;
    }

    // Small global coupling: prefer bins whose residual deviates from the mean in a useful way
    // (place into below-average-residual bins to keep large residuals available).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual weighted by stream progress
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) - pr_norm * (1.0 - progress);
    score += 20.0 * coupling;

    // Penalize dead space that cannot fit any plausible next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (ni - pr).max(0.0);
        score += 0.6 * waste * (1.0 + progress);
        // Reward leaving room exactly for the lookahead item
        if pr >= ni && pr - ni < 10.0 {
            score -= 8.0 * (1.0 - pr_norm);
        }
    }

    // Last-chance bonus: only one bin fits, prefer using it over opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Nudge toward bins tighter than the mean residual (good fits)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev - 3.0 * dev;

    // New-bin candidate: neutral-ish baseline with smooth progress decay
    if bin_residual == bin_capacity {
        score = cap - 30.0 * progress + 10.0 * (1.0 - progress);
        if fitting_bins_count <= 1 && next_item_size > 0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "waste bucket" does it fall into?
    // Class by integer division into deciles of capacity.
    let class = post_residual / 10;

    // Reward placements whose post_residual lands in a low-value class
    // (very tight fits), using a harmonic-style inverse weight.
    if class <= 2 {
        score -= (3 - class) as f64 * 12.0;
    }

    // Dead space penalty: post_residual that cannot fit the next item
    // is likely wasted unless it is nearly zero.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste_ratio = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += waste_ratio * 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic residue check via modulo: post_residual divisible by small
    // integers tends to combine well with common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly unless current bins are crowded
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 1.5;
        let poor_fit = if next_item_size > 0 && next_item_size <= bin_capacity {
            0.0
        } else {
            0.0
        };
        score += 30.0 - crowded.min(25.0) + poor_fit;
        // Opening fresh is attractive when mean residual is fragmented low.
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 15.0;
        }
    }

    // Mild late-stream tightening: prefer tight fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * progress;

    // Tie-break: prefer bins with lower residual overall.
    score += bin_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for the smallest item)
    // are heavily penalized; usable residual is mildly rewarded.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Penalty curve: small gaps that are still "usable" are risky; penalize quadratically.
    let pr = post_residual as f64;
    if post_residual > 0 {
        score += 40.0 / (pr + 1.0);
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 - progress) * 0.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item cannot use the gap: penalize leaving a dead gap for it
            score += 15.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    score += (mean_residual - pr) * 0.3;

    // New-bin candidate: make opening a new bin moderately attractive only when
    // current fits are poor (large post_residual waste) or many bins already open late.
    if bin_residual == bin_capacity {
        let waste_pressure = pr / bin_capacity as f64; // for empty bin pr == capacity
        let _ = waste_pressure;
        score = bin_capacity as f64 * 0.9
            + (open_bins_count as f64) * (1.0 - progress) * 2.0
            - if fitting_bins_count == 0 { 100.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step perfect fits: post_residual == next_item_size
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 60.0;
    }

    // Reward near-miss lookahead matches (post_residual close to next_item_size)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-gap / 20.0).exp();
    }

    // Penalize leaving dead space the next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = next_item_size - post_residual;
        score += 8.0 + waste as f64 * 0.5;
    }

    // Strong reward for tight fits overall (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize bins whose residual is far below mean (already fragmented)
    score += 0.6 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize opening a new bin when stream is early
    // and mean residual across open bins is still healthy
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * (1.0 - progress);
        if mean_residual >= item_size as f64 * 2.0 {
            score += 15.0;
        }
    }

    // Small penalty proportional to open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize unusable dead space: if next item cannot fit into post_residual,
    // this bin likely becomes dead weight.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Reward leaving space exactly usable by the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else {
        // Last item: pure tight fit matters most.
        score -= 5.0 * (1.0 - tightness);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // When many bins fit the item, mildly prefer bins with smaller residuals
    // (best-fit style) to preserve larger residuals elsewhere.
    if fitting_bins_count > 1 {
        score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Time horizon coupling: early in the stream, be conservative about
    // fragmenting bins; later, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * post_residual as f64;
    score -= progress * 4.0 * (1.0 - tightness);

    // Penalize opening new bins when open-bin residual is plentiful.
    if bin_residual == bin_capacity {
        let avg_slack = mean_residual / bin_capacity as f64;
        score += 10.0 + 15.0 * avg_slack + 0.5 * open_bins_count as f64;
        // But allow a new bin if current item is huge and would leave a bad
        // remainder in any existing bin.
        if item_size >= 70 {
            score -= 12.0;
        }
    }

    // Mild preference for filling nearly-full bins to close them out.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 2.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: quadratic penalty on wasted space, softened by stream progress
    // (late in the stream, tight fits matter more; dead space is costlier).
    let mut score = r * r / cap;

    // Smooth non-linear coupling: waste penalty grows with progress^2.
    score += 40.0 * progress * progress * rn * rn;

    // Reward near-perfect fits via smooth gaussian-like term on normalized residual.
    let fit_bonus = (-8.0 * rn * rn).exp();
    score -= 25.0 * fit_bonus * (0.3 + 0.7 * progress);

    // Penalize leaving residual that cannot fit the lookahead item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (r - nx).abs() / cap;
        score += 15.0 * (1.0 - (-6.0 * gap * gap).exp()) * (1.0 - progress);
    }

    // Last-chance bin: smooth reward to avoid opening new bins when scarce.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure toward consolidation: prefer bins below mean residual.
    score += 0.3 * (r - mean_residual);

    // Slight penalty for opening new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity/10 buckets
    let class = post_residual / 10;
    let in_class = post_residual % 10;
    // Prefer residuals that sit exactly on a class boundary (clean fit classes)
    if in_class == 0 {
        score -= 8.0;
    } else {
        score += in_class as f64 * 0.15;
    }

    // Dead-space penalty: residuals too small for the smallest item (1..=10)
    if post_residual < 10 {
        score += 25.0;
    }
    // Very tight residuals that likely can't fit next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: post_residual can fit next item exactly or near-exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_post = post_residual - next_item_size;
        if nxt_post == 0 {
            score -= 20.0;
        } else if nxt_post < 10 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score -= 5.0;
        }
    }

    // Progress-aware mild pressure: as stream progresses, consolidate more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64) * 0.05;

    // Prefer bins whose residual is below mean (concentrate large gaps)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Integer-division threshold: reward leaving residuals in usable bands
    let band = post_residual / 20;
    score += band as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items in 1..=100, but small gaps are rarely reusable) are heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual also accommodates the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for lookahead: extra dead-space penalty.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    score += open_bins_count as f64 * 0.5;

    // Slightly favor bins below mean residual (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when the item leaves a huge usable gap
    // in an existing bin or no good fit exists. Penalize opening a new bin
    // moderately so tight fits still win.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the item is large, a fresh bin is more attractive.
        score -= (item_size as f64 / 100.0) * 10.0;
    }

    // Late-stream bias: consolidate more aggressively toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 1.5;
        if post_residual == next_item_size {
            score -= 40.0; // exact chain fit
        }
        // Penalize leaving space that the next item cannot use
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: minimize leftover
        score += post_residual as f64 * 0.3;
    }

    // Reward tight fits relative to current item
    score -= (bin_residual - item_size) as f64 * 0.1;

    // Compare against mean residual: prefer using bins with above-average space
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when other bins could fit
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + open_bins_count as f64 * 2.0;
        } else {
            score -= 10.0; // no alternative, new bin is fine
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness: reward filling a large fraction of the bin's current space
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Penalize leaving residual that is small but unusable (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            // next item won't fit here: mild penalty proportional to leftover
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer opening a new bin when item is small relative
    // to capacity and many bins are open with large mean residual (fragmentation risk)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let small_item = (item_size as f64 / bin_capacity as f64) < 0.5;
        if open_bins_count > 0 && mean_residual > 20.0 && small_item {
            score -= 4.0 + 6.0 * mean_residual / 100.0 + 3.0 * (1.0 - progress);
        } else {
            score += 2.0;
        }
    }

    // Global fragmentation: penalize placements that leave residual far from mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Late in stream: be greedy, minimize residual aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer small post-residual, with non-linear emphasis on tight fits.
    let mut score = post * (1.0 + 0.8 * post / cap) - 0.5 * (post * post) / cap;

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, dead space is more costly (less chance to reuse it).
    score += 12.0 * progress * (post / cap) * (post / cap) * cap * 0.05;

    // Interaction with mean residual: if this bin's post-residual deviates
    // below the mean, reward it (consolidating slack); above mean, penalize.
    score += 0.6 * (post - mean_residual) * (1.0 + progress);

    // Lookahead: reward if next item fits the post-residual, penalize if it nearly doesn't.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = post - nxt;
        if slack >= 0.0 {
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            score += 0.05 * (-slack);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin, but less when existing
    // fits are poor (post-residual high relative to capacity) or stream is early.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 30.0 - 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 8.0 * (item_size as f64 / cap);
    }

    // Mild penalty on proliferating open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 (capacity 100 => decade classes)
    let class = post_residual % 10;
    // Residues near 0 (tiny dead space like 1..3) are excellent -> reward
    let tiny_dead = class > 0 && class <= 3;
    // Residues in mid-band (4..6) are the worst dead space -> penalize
    let mid_dead = class >= 4 && class <= 6;

    if tiny_dead {
        score -= 6.0;
    }
    if mid_dead {
        score += 6.0;
    }

    // Integer division threshold: post_residual / 10 gives usable decade slots
    let slots = post_residual / 10;
    score += 2.0 * slots as f64; // more usable slots = better leftover

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: can next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable bin -> reward, scaled by how well next item uses the leftover
            let fill_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * fill_ratio;
        } else {
            // leftover cannot host next item -> penalize more if next item is large
            score += 0.08 * next_item_size as f64;
        }
    }

    // Last-chance bin: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate penalty: prefer reusing open bins unless residual is very fragmented
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if all open bins are crowded (mean residual small), a fresh bin is fine
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Stream progression: later in stream, tighten packing (penalize waste more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Many open bins: discourage spreading, reward consolidating into low-residual bins
    score += 0.05 * open_bins_count as f64;
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space for the known next item
    }

    // Mean-residual coupling: prefer bins far from the mean (extreme consolidation).
    score -= 0.5 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when current bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let pressure = 3.0 * open_bins_count as f64 + 0.3 * mean_residual;
        score = 55.0 + pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, amplified for small residuals.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect-fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item,
    // with an extra bonus for an exact second-step fit (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 180.0; // perfect chain: two items fill bin exactly
        } else if next_item_size <= post_residual {
            // Reward proportional to how much of post_residual the next item consumes.
            let chain_use = next_item_size as f64 / post_residual as f64;
            score -= 90.0 * chain_use;
        } else {
            // Next item won't fit here: penalize leaving a mid-range dead zone
            // that is too small for typical items but too big to ignore.
            if post_residual < 10 {
                score += 40.0; // tiny sliver, nearly dead space
            } else {
                score += 25.0;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average,
    // penalize bins with far more residual than the fleet mean.
    score += 0.8 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual <= 10 {
            score -= 100.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: empty bin gets a mild handicap so that any
    // decent fit into an existing bin wins, but a very poor fit (large dead
    // space, next item mismatched) lets the new bin win.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 70.0; // fresh bin can serve both current and next item
        }
    }

    // Early in the stream, allow slightly more liberal bin opening (diversity helps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * (1.0 - progress);

    // Slight penalty per open bin to discourage bin sprawl.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Penalize dead space if post-residual is small but nonzero (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only one bin fits this item; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // next item still fits here: mild reward proportional to how snugly.
        score -= 8.0 * (1.0 - (post_residual - next_item_size as u32) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item won't fit here after placement: slight penalty.
        score += 6.0;
    }

    // Prefer bins below mean residual (fill emptier bins first when residuals are high).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, opening new bins is cheap; later, conserve.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as open bins grow.
        score += 20.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
        // But if this bin would leave a perfect fit for the next item, soften.
        if next_item_size > 0 && (bin_capacity - next_item_size as u32) == item_size {
            score -= 30.0;
        }
    }

    // Reward using nearly-full bins (low residual) harder as open_bins_count grows.
    score -= 0.4 * (bin_capacity - bin_residual) as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic + cubic polynomial in normalized post-residual,
    // modulated by stream progress.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) + norm_pr * norm_pr * norm_pr * progress;
    score -= 30.0 * poly * (0.5 + progress);

    // Tight fits (small post residual) are strongly rewarded, more so late in stream.
    let tightness = (1.0 - norm_pr).powi(2);
    score -= 8.0 * tightness * (1.0 - progress);

    // Penalize leaving dead space that next item could not use (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let waste = ((pr - nx) / cap).max(0.0);
        score += 6.0 * waste * waste * (0.5 + progress);
        // Reward if next item fits exactly-ish in the post residual.
        let fit_gap = (pr - nx).abs() / cap;
        score -= 4.0 * (1.0 - fit_gap.min(1.0)) * (1.0 - norm_item);
    }

    // Last-chance bonus: smooth exponential in fitting_bins_count.
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 5.0 * scarcity * scarcity;

    // Penalize spreading across many open bins relative to mean residual (smooth).
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev * dev;

    // Mild bias toward filling existing bins more as stream progresses.
    score -= 2.0 * progress * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that future items (1..100)
    // can plausibly fill. Residuals divisible by common size classes are reusable.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize tiny dead space strongly (wasted capacity), nonlinearly.
    if post_residual > 0 {
        let dead = pr / cap_f;
        if dead < 0.10 {
            score += (0.10 - dead) * 120.0; // unusable sliver
        }
    } else {
        score -= 30.0; // perfect fill
    }

    // Harmonic class reward: post_residual in "nice" classes (multiples of 10/25/50)
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 6.0; }

    // Integer-division thresholds: residual >= next item => chain placement possible
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // extra reward if the pair nearly fills the bin
            let combined = (item_size + next_item_size) as f64;
            if combined / cap_f > 0.9 { score -= 12.0; }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong preference to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap_f;
        if fragmentation < 0.35 && open_bins_count > 2 {
            score -= 8.0; // open fresh bin
        } else {
            score += 15.0; // prefer existing bins
        }
    }

    // Tight fits are best: reward small post_residual relative to item
    let tightness = (post_residual as f64) / (item_size as f64 + 1.0);
    score -= 8.0 / (1.0 + tightness);

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Tiny sliver: almost nothing can ever use it.
            score += 45.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual < 35 {
            score += 4.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits generally (small relative waste).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover: leftover is likely dead space.
        score += 8.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual > 0 && post_residual <= 10 {
            score += 20.0; // but not if it creates a sliver
        }
    }

    // Open-bin pressure: discourage scattering across many open bins when
    // residuals are already small; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.9 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate handling: only attractive when current bins are fragmented
    // (high mean residual spread / many bins with poor fit quality).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 && open_bins_count > 0 {
            score += 30.0; // existing bins are tight, keep filling them
        } else if fragmentation > 0.6 {
            score -= 5.0 * fitting_bins_count as f64; // bins are fragmented, fresh bin ok
        } else {
            score += 10.0;
        }
        // Never open a new bin for a tiny item.
        if item_size <= 25 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect chain: this bin fits current AND next item exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Post-residual too small for next item is dead space; penalize relative to mean residual.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer tightest fit.
        score *= 2.0;
    }

    // Penalize leaving unusable slivers below the minimum item size.
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild bonus for using existing bins as stream progresses (avoid bin proliferation).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Slight preference for larger residual bins early in stream (keep flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional tightness of the fit: reward placements that leave small waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose residual exactly hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Partial reward proportional to how much of the leftover is usable next.
            let usable = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * usable * usable;
        } else if post_residual > 0 && next_item_size >= post_residual {
            // Dead space penalty when the next item cannot use the leftover.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin.
        score += 120.0;
        // If the item fills a fresh bin largely, opening is more attractive.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 80.0 * fill * fill;
        // Late in the stream, avoid spawning bins that will hold little.
        score += 60.0 * progress * (1.0 - fill);
        // If many bins already fit the item, penalize opening another.
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // If mean residual across open bins is large, prefer reusing open bins.
        score += 0.4 * mean_residual;
    } else {
        // Reuse bonus: mildly favor already-open bins over new ones.
        score -= 10.0;
        // Penalize leaving very small, hard-to-use slivers (1..5) unless exact next fit.
        if post_residual > 0 && post_residual < 6 {
            score += 12.0;
        }
        // Dynamic coupling: when open bins are mostly empty (high mean residual),
        // extra reward for consolidating into existing bins.
        score -= 0.15 * mean_residual;
    }

    // Global pressure: with many open bins, tighten preference for tight fits.
    if open_bins_count > 1 {
        score -= 2.0 * (open_bins_count as f64).ln() * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic in post_residual, weighted by stream progress
    let mut score = pr * (1.0 + 0.5 * pr_norm) * (1.0 + progress);

    // Smooth non-linear coupling: post_residual^2 * progress (penalize dead space more as stream advances)
    score += 0.8 * pr_norm * pr_norm * progress * cap;

    // Reward tight fits: subtract a smooth function of item fill ratio
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Scarcity pressure: penalize when few bins can fit relative to open bins
    if fitting_bins_count > 0 {
        score += 10.0 * (open_bins_count as f64 / fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 15.0;
    } else if next_item_size > pr as u32 && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for wasting residual
        score += 3.0 * pr_norm;
    }

    // Mean residual coupling: bins deviating from mean residual get penalized smoothly
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // New-bin candidate handling: make empty bin mildly attractive early, less later
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.6 * progress) + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible item are wasted.
    // Treat gaps below a "usability floor" as twice as bad.
    let dead_floor = 10.0f64;
    if (post_residual as f64) < dead_floor {
        score += (dead_floor - post_residual as f64) * 2.0;
    }

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving a gap that exactly blocks the lookahead item (wasted future fit).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins (penalize new-bin option).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Deviation from mean residual: prefer bins with less residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in stream, be slightly more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: next item seals this bin completely
        } else if (post_residual as u32) >= next_item_size {
            // next item still fits; smaller gap is better (tight packing chain)
            score -= (next_item_size as f64) * 0.6 - diff * 0.25;
        } else {
            // next item won't fit here: penalize dead space proportional to gap
            score += diff * 0.35;
        }
    }

    // Prefer bins that are already fairly full (low residual relative to capacity).
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Penalize creating tiny unusable fragments (below the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or mean residual is low.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 - 25.0 * crowding - 20.0 * tight;
    }

    // Slight late-stream preference to consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Lookahead: reward bins whose post-residual can still host the next item,
    // scaled by how "compatible" the leftover chain is.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 10.0 - (chain_waste / bin_capacity as f64) * 10.0;
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: mild penalty proportional to lookahead size.
        score += (next_item_size as f64 / bin_capacity as f64) * 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Crowding effect: many open bins with small mean residual => prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > 0.0 {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += (1.0 - fragmentation) * 8.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a fresh bin, but relax the penalty
    // when existing bins are highly fragmented (mean residual small) or late in stream.
    if bin_residual == bin_capacity {
        let escape_valve = (mean_residual / bin_capacity as f64).min(1.0);
        score += 18.0 - escape_valve * 14.0 + progress * 4.0;
    } else {
        // Favor keeping items in already-open bins mildly.
        score -= 3.0;
    }

    // Nonlinear residual shaping: heavily penalize leaving awkward mid-size gaps
    // that few typical items can use (dead zone around 30..60 residual).
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dead_zone = ((pr - 45.0) / 15.0).powi(2);
        score += dead_zone.max(0.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let r = post_residual as f64 / cap;
    let fit = fitting_bins_count as f64;

    // Smooth non-linear interaction: waste penalty grows with stream progress
    score += 20.0 * t * (r * r);

    // Reward tight fits more aggressively as the stream advances
    score -= 15.0 * t * (1.0 - r) * (1.0 - r);

    // Scarcity coupling: when few bins can fit the item, favor this bin
    score -= 10.0 * (1.0 - t) / (fit + 1.0);

    // Mean-residual coupling: penalize bins far from the mean residual state
    score += 0.3 * (post_residual as f64 - mean_residual).abs() * (1.0 + t);

    // Lookahead: smooth bonus if the next item fits the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - t) * (gap / cap);
        } else {
            score += 5.0 * (gap.abs() / cap) * t;
        }
    }

    // New-bin candidate: smooth polynomial disincentive, relaxable late in stream
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - t) * (1.0 - t) + 5.0 * (1.0 - t);
    }

    // Mild pressure against many open bins early on
    score += 0.5 * (open_bins_count as f64) * t * r;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled nonlinearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac; // quadratic penalty for large leftover

    // Harmonic class of post_residual: integer division tiers.
    // Residuals in [0,10) are "dead space" class -> strong penalty.
    let dead = post_residual < 10;
    if dead {
        score -= 25.0; // excellent: nearly perfect fit
    } else {
        // Tier by post_residual / 10: lower tier = better packing density.
        let tier = post_residual / 10;
        score += tier as f64 * 3.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
        // Extra harmony if post_residual is an exact harmonic multiple window of next item
        let m = post_residual % next_item_size.max(1);
        if m == 0 {
            score -= 5.0; // perfect divisible match
        } else if m < 5 {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // post_residual cannot host next item: penalize unusable residue.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Slight preference for more crowded bins (bin packing consolidation).
        score += 0.5 * fitting_bins_count as f64;
    }

    // Modulo-arithmetic harmonic class of item_size vs capacity:
    // items that divide capacity well (e.g. 10,20,25,50) prefer exact slots.
    let cap_mod = bin_capacity % item_size.max(1);
    if cap_mod == 0 && bin_residual == bin_capacity {
        score -= 4.0; // fresh bin for a perfect divisor item
    }

    // New-bin candidate adjustment: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score, penalize opening when
        // an open bin already gives small post_residual.
        if !dead && post_residual < 20 {
            score += 12.0; // discourage opening a new bin on a good fit
        }
        if open_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0; // existing bin serves lookahead; don't open new
        }
        // Early stream: opening bins is cheap and helps future flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // If mean residual is high, open bins are underused -> reuse them.
        score += 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since items are >= 1 and small gaps rarely get reused.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: prefer reusing existing bins when many are open,
    // to avoid bin proliferation.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it is early in the
    // stream or the item is huge (poor fit everywhere).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * (1.0 - progress);
        if item_size >= 70 {
            score -= 35.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0; // dead space that even the next item cannot use
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping loose bins available for larger future items.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item completion: bin fully closed after next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: good chain, but penalize leftover gap size.
            score -= 20.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item does NOT fit here: dead-space risk grows with excess.
            let excess = (next_item_size - post_residual) as f64;
            score += 0.5 * excess;
            // If post_residual becomes unusably small, penalize more.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Relative to mean residual: bins already tighter than average are better targets.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_options = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual >= next_item_size);
        if poor_options {
            score -= 25.0 + 20.0 * progress;
        } else {
            // Keep existing bins preferred over opening new ones.
            score += 50.0;
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual can still host the next item,
    // penalize bins that leave a residual just below the next item size (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space that blocks the next item
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive when
    // existing fits are poor (large post_residual) or many bins already fit fine.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 20.0 + 10.0 * (1.0 - progress);
        // If existing bins leave bad residuals, opening a fresh bin is more acceptable.
        let escape = (post_residual as f64).min(40.0);
        score += penalty - 0.2 * escape;
        // Prefer opening new bins when the mean residual of open bins is small
        // (they are nearly full anyway) — actually then we should NOT open; invert:
        if mean_residual > 30.0 {
            score -= 5.0; // open bins have room; discourage new bin less? no: encourage reuse
        } else {
            score += 5.0;
        }
        score += 2.0 * open_bins_count as f64;
    } else {
        // Mild preference for more-filled bins among open candidates.
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Penalize leaving residuals in the awkward 1..=9 range (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: penalize wasted post residual, quadratically (dead space is costly).
    let mut score = pr + 60.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling with stream progress:
    // early on, be more lenient with leftover space (bins can still be filled);
    // late, strongly prefer tight fits.
    let progress_coupling = (1.0 - progress) * (norm_pr * (1.0 - norm_pr)) * 80.0
        - progress * norm_pr * fit * 120.0;
    score += progress_coupling;

    // Reward near-perfect fits more aggressively as stream advances.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 60.0 * progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0 + 100.0 * progress;
    }

    // Lookahead: if next item fits in the post residual, reward leaving this bin usable.
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= pr;
        if next_fits {
            score -= 25.0 + 30.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
        } else {
            // Post residual too small for next item: penalize creating unusable slivers.
            score += 15.0 * norm_pr;
        }
    }

    // Mild penalty when this bin's residual deviates from mean (keep bin profile balanced),
    // scaled by number of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (open_bins_count as f64).sqrt();

    // New-bin candidate: neutral-ish score so it wins only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 200.0 - 50.0 * progress + (item_size as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot" of capacity it falls in.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // --- Class-based dead-space penalty (non-linear staircase) ---
    let class = post_residual / tenth; // 0..10 harmonic class
    let class_penalty = match class {
        0 => -60.0,                       // perfect/near-perfect fit: strongly reward
        1 => -35.0,                       // leaves room for tiny items
        2 => -18.0,
        3 => -8.0,
        4 => 0.0,
        5 => 6.0,                         // ~half-full leftover: mediocre
        6 => 10.0,
        7 => 16.0,
        8 => 24.0,
        9 => 30.0,
        _ => 34.0,                        // nearly empty bin used for this item: wasteful
    };
    score += class_penalty;

    // --- Exact fit bonus via integer divisibility of post_residual ---
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 25.0;                    // tiny sliver, but at least nearly closed
    } else if post_residual % 10 == 0 {
        score -= 12.0;                    // residual aligned to common item sizes (multiples of 10)
    }

    // --- Lookahead coupling: can next item fit into the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely: reward proportionally to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            // Extra bonus if next item exactly consumes the remainder.
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize more if we're leaving a large awkward gap.
            let gap_class = post_residual / fifth;
            score += 6.0 * gap_class as f64;
        }
    } else {
        // Last item: prefer closing bins as tightly as possible.
        score -= 15.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly:
        // i.e., no open bin gives a tight fit and mean residual is small.
        let tight_exists = open_bins_count > 0
            && (item_size >= quarter || (mean_residual - item_size as f64) < 5.0);
        if tight_exists || fitting_bins_count > 0 {
            score += 45.0; // discourage new bin when decent fits exist
        } else {
            score -= 10.0; // mildly encourage fresh bin when all fits are terrible
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // --- Mild pressure toward consolidating many open bins ---
    score += 0.4 * open_bins_count as f64;

    // --- Prefer placing into bins whose residual is closest to the item (best-fit flavor) ---
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.15 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    // Penalize unusable gaps super-linearly.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 25 {
        // Small, likely-unusable gaps (most items > 25): moderate penalty.
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 15.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // If the next item can fill this bin's post_residual exactly, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits in the leftover: mild reward, keeps chain going.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / 50.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the leftover: penalize proportionally to wasted potential.
        score += 6.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 10.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless the fit is good.
    let open_pressure = (open_bins_count as f64).sqrt() * 3.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when current item leaves a
    // terrible gap in every fitting bin, or few bins are open early in the stream.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 - 20.0;
        // Early stream: opening bins is cheap (builds a portfolio of residuals).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is rarely right.
        score += 25.0 * (fitting_bins_count as f64).min(5.0);
        // If the item would leave a near-empty bin elsewhere, new bin is attractive.
        if post_residual >= 0 {
            // item in a fresh bin leaves residual = capacity - item_size;
            // reward when that residual is small (large item) or exactly next_item_size.
            let fresh_residual = bin_capacity - item_size;
            if next_item_size > 0 && next_item_size == fresh_residual {
                score -= 60.0;
            }
            if fresh_residual <= 5 {
                score -= 45.0;
            }
        }
        // Many open bins with large mean residual: reuse instead.
        score += (mean_residual / 20.0).min(20.0);
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward post_residual matching next item size ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: big reward (perfect fit for the NEXT item)
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward proportional to closeness
            score -= (30.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // Next item won't fit: penalize dead space, worse if gap small (wasted tightness)
            score += 10.0 + 0.5 * gap;
        }
    } else {
        // Last item: pure tightness packing
        score -= 20.0;
    }

    // --- Prefer filling nearly-full bins (small residual = less waste) ---
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // --- Coupling with mean residual: favor bins tighter than average ---
    score += 0.3 * (post_residual as f64 - mean_residual);

    // --- New-bin candidate handling: neutral baseline, penalized mildly early,
    //     penalized more when many bins are open and could absorb the item ---
    if bin_residual == bin_capacity {
        let mut nb = 8.0 + 3.0 * (1.0 - progress);
        if open_bins_count > 0 {
            nb += 4.0 * (open_bins_count as f64).ln().max(0.0);
        }
        // If item is huge relative to capacity, opening fresh is more attractive
        nb -= 6.0 * (item_size as f64 / bin_capacity as f64);
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual, non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 {
        if next_item_size > 0 {
            if next_item_size > post_residual {
                score += 0.5 * (next_item_size - post_residual) as f64;
            } else if next_item_size == post_residual {
                // Perfect lookahead match: big bonus.
                score -= 40.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Last item: any residual is pure waste.
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        let waste = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing bins are crowded / fragmented and late in stream.
        score += 18.0 + 20.0 * (1.0 - waste) - 10.0 * progress - 0.5 * crowd;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with residual close to mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Favor filling bins with small residual over opening fragmentation.
    if bin_residual < 20 && bin_residual >= item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill = 1.0 - pr / cap;

    // Base: reward tight fits via non-linear polynomial in post_residual
    let mut score = pr * pr / cap + pr * (1.0 - fill);

    // Smooth stream-progress coupling: later in stream, penalize waste more strongly
    score += pr * (0.5 + progress) * (0.5 + 0.5 * fill);

    // Mean-residual coupling: if this bin's post-residual deviates from mean, prefer balance
    let dev = pr - mean_residual;
    score += 0.25 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * fill;
    }

    // Lookahead: if next item fits in post-residual, reward this placement smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 10.0 * (1.0 - slack / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty for leaving dead space
        score += 5.0 * pr / cap;
    }

    // New-bin candidate: keep it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score = cap * (0.6 + 0.4 * progress) - 15.0 * crowding * (1.0 - fill);
        // discourage opening new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 && pr <= mean_residual + 20.0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity fractions (mod logic)
    let q = (post_residual * 4) / bin_capacity; // 0..3 harmonic quartile class
    match q {
        0 => score -= 30.0,               // near-perfect fit: excellent
        1 => score -= 8.0,                // leaves small item slot
        2 => score += 4.0,                // mid residual: mediocre
        _ => {}                           // large residual: neutral
    }

    // Exact modulo classes: post_residual divisible by small ints => flexible
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 5 == 0 && post_residual % 10 != 0 { score -= 2.0; }
    } else {
        score -= 50.0; // bin exactly closed
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class match between post_residual and next item
            let nq = (next_item_size * 4) / bin_capacity;
            let pq = q;
            if nq == pq { score -= 10.0; } else { score -= 3.0; }
        } else {
            // next item cannot use this residual: penalize wasted space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets high baseline unless few bins open
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64);
        if open_bins_count == 0 { score -= 40.0; }
    }

    // Prefer filling bins with low residual relative to mean (tight packing)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zones: residuals too small for typical future items are wasted.
    // Penalize residuals in (0, 10) heavily, and residuals just below common item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 4.0;
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.7 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: penalize bins far above mean residual (poor consolidation targets).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.6;

    // New-bin candidate: attractive early or when few bins fit, unattractive when open bins are plentiful.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 5.0 + 25.0 * (1.0 - progress) + 15.0 * (1.0 - (fitting_bins_count as f64).min(5.0) / 5.0);
        score -= new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fill the bin
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // next item still fits well
        } else {
            // next item cannot use the leftover space; penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Relative to mean residual: prefer bins with less residual than average
    // (consolidate into fuller bins), unless this is a last-chance bin.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized when open bins exist
    // and mean residual is large enough to absorb the item.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0; // fresh bin perfect for the next item too
        }
    }

    // Late in the stream, prefer closing out bins (avoid stranding small residuals).
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).powf(2.0);
    score -= 40.0 * tightness;

    // Penalize post-residuals that are small but too small for likely future items
    // (dead space): mid-range leftovers are the most reusable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny slivers are dead space
    } else {
        // Reward leftovers that can accommodate the next item exactly-ish
        if next_item_size > 0 && post_residual >= next_item_size {
            let compat = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * compat;
        } else if next_item_size > 0 {
            score += 8.0; // leftover can't host next item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in stream or low residual pressure => opening fresh bin is fine.
        score = 30.0 + 40.0 * (1.0 - pressure) + 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin good for a chain of large items
        }
        if fitting_bins_count == 1 {
            score += 60.0; // never abandon the sole fitting bin
        }
    }

    // Mild preference to fill bins with below-average residual (consolidation).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    // Reward keeping number of open bins low early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping (quartic dead-space penalty)
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth coupling of dead space with stream progress: waste matters more later
    score += 8.0 * norm_pr * norm_pr * progress;

    // Fit quality: item_size relative to bin_residual, smooth sigmoid-like cubic coupling
    let fit_ratio = it / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio * (2.0 - fit_ratio).max(0.0);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward if next item can use the post-residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr as f64 {
            score -= 4.0 * (1.0 - (ns / pr.max(1.0) as f64)) * (1.0 - progress * 0.5);
        } else {
            score += 2.0 * norm_pr * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across many open bins when residuals are high
    score += 0.05 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    // Mean-residual alignment: prefer bins near the mean (keeps residuals uniform)
    score += 1.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin unless residual would be well usable
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * norm_pr * (1.0 + progress) - (fitting_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by capacity fraction (eighths).
    let item_class = (item_size * 8 + bin_capacity - 1) / bin_capacity; // ceil(item/C*8)
    let next_class = if next_item_size == 0 { 0u32 } else { (next_item_size * 8 + bin_capacity - 1) / bin_capacity };

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: post_residual below the smallest item class (~C/8) is wasted.
    if post_residual < bin_capacity / 8 {
        score += 18.0 * (bin_capacity / 8 - post_residual) as f64;
    }

    // Harmonic pairing: if next item's class divides the post_residual nicely, reward.
    let next_thresh = next_class * bin_capacity / 8;
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact division bonus: post_residual is a multiple of next_item_size class slot
        if next_thresh > 0 && (post_residual % next_thresh.max(1)) < (bin_capacity / 16).max(1) {
            score -= 8.0;
        }
        // If post_residual can hold next item exactly, strong reward
        if post_residual == next_item_size {
            score -= 15.0;
        } else {
            let leftover = post_residual - next_item_size;
            if leftover < bin_capacity / 8 {
                score += 6.0; // placing next here would create dead space -> penalize mildly
            } else {
                score -= 4.0;
            }
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to mismatch
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current residuals are poor.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        // If mean residual is large (open bins are roomy), discourage new bin.
        score += 10.0 + 25.0 * mean_frac;
        // If item is large-class and mean residual is small, new bin becomes attractive.
        if item_class >= 6 && mean_frac < 0.25 {
            score -= 15.0;
        }
    }

    // Prefer filling bins with lower residual (best-fit flavor) via mean coupling.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Modulo harmonic classes on post_residual: multiples of 25 are clean slots.
    if post_residual % 25 == 0 {
        score -= 5.0;
    } else if post_residual % 10 == 0 {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Late-stream consolidation: as stream progresses, favor existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual below the smallest possible item
    // is pure waste; penalize heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Very small gaps that can only fit tiny items are semi-dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if the gap can't fit the next item but could have with another bin choice.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones (favor low index bins implicitly via residual),
    // penalize opening new bins when open count is already high.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins, relax late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + open_pressure * 1.5 * (1.0 - 0.5 * progress);
    } else {
        // Reward using an existing bin, more so when many bins are open.
        score -= (open_pressure * 0.4).min(6.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a poor bin;
    // prefer bins whose residual is close to mean (balanced packing) unless exact fit.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item can use this bin's post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Bonus if next item nearly fills remaining space too.
            let chain_waste = post_residual - next_item_size;
            score -= (bin_capacity as f64 - chain_waste as f64).max(0.0) * 0.05;
        } else {
            // Dead space the next item can't use: penalize.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit, unless residuals are all poor.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual.max(0.0);
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 30.0 + 0.5 * avg_fit;
        // Early in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // Few open bins: consolidation is cheap, avoid new bins.
        score += 5.0 * open_bins_count as f64;
    } else {
        // Mild penalty for very fragmented bins (small residual left that nothing fits).
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        // Prefer bins with residual close to item (best-fit behavior) already captured;
        // slight preference to use fuller bins first.
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    // Global pressure: when many bins are open, keep items consolidated.
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = post;

    // Quadratic coupling of post residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let quad = norm_post * norm_post;
    score += 40.0 * quad * progress;

    // Cubic term: heavily penalize large dead space as stream matures.
    score += 60.0 * quad * norm_post * (1.0 - progress);

    // Reward near-perfect fits smoothly: subtract a gaussian-like bump
    // centered at zero post-residual.
    let tight = (-norm_post * norm_post * 30.0).exp();
    score -= 25.0 * tight * (0.5 + progress);

    // Interaction with mean residual: prefer bins whose post residual
    // aligns with the average residual landscape.
    let dev = (post - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Lookahead: if next item fits smoothly into post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (-slack * 8.0).exp();
        } else {
            // Next item won't fit: penalize proportionally to mismatch.
            score += 8.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.5 * open_bins_count as f64 * progress * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit class: post_residual in {0, 1..=3} is near-perfect — reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 300.0 + (4 - post_residual) as f64 * 50.0;
    }

    // Dead-space class: post_residual in (3, 10) is too small for typical items — penalize.
    if post_residual > 3 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Integer-division harmonic classes: post_residual / 10 buckets.
    // Class 0 (0..9): unusable sliver. Class 1 (10..19): only tiny items fit.
    // Higher classes are progressively more reusable.
    let class = post_residual / 10;
    score -= class as f64 * 12.0;

    // Coupling with next item: reward residuals that exactly (or nearly) fit next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 150.0 - gap as f64 * 10.0;
            }
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 5 {
                score += 30.0 + gap as f64 * 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when mean residual
    // is high (existing bins are fragmented) and the fit is poor.
    if bin_residual == bin_capacity {
        score += 150.0;
        let fit_ratio = item_size as f64 / c;
        if fit_ratio > 0.7 {
            score -= 80.0; // big items go to fresh bins happily
        }
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0).min(50.0);
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Mild preference for tight fits relative to residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 25.0;

    // Small tie-breaker against spreading load across many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Classify the post-placement residual into usable vs dead space.
    let pr = post_residual;
    if pr > 0 {
        // Dead space: residual too small to be useful for typical items (<= 10 min item).
        if pr < 10 {
            score += 60.0; // worst possible: completely wasted space
        } else if pr <= 25 {
            // Small gap: only useful if the next item can actually use it.
            if next_item_size > 0 && next_item_size <= pr {
                score -= 25.0; // lookahead confirms the gap is usable
            } else {
                score += 20.0; // likely dead space
            }
        } else {
            // Larger residual: reward, but discount by how much the next item wastes.
            if next_item_size > 0 {
                let waste = if next_item_size <= pr { (pr - next_item_size) as f64 } else { pr as f64 };
                score -= (pr as f64) * 0.5 - waste * 0.3;
            } else {
                score -= (pr as f64) * 0.5;
            }
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 80.0;
    }

    // Open-bin pressure: penalize spreading across many open bins,
    // encouraging filling existing bins when the fit is decent.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mean residual coupling: prefer bins whose residual is close to the mean
    // (balanced packing), penalize outliers that fragment capacity.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    // New-bin candidate handling: an empty bin is attractive only when the
    // item is large (poor fit elsewhere) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > bin_capacity as f64 * 0.6;
        if large_item {
            score -= 70.0; // big items deserve a fresh bin
        } else if progress < 0.2 {
            score -= 10.0; // early stream: cheap to open bins
        } else {
            score += 40.0; // late stream: strongly prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item still fits comfortably (post_residual >= next_item_size).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.35; // reward closeness of the chain fit
    }

    // Penalize dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals everywhere are tiny.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can chain the next item too
        }
    }

    // Prefer bins whose residual is already below mean (tight bins first).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    } else {
        score += (res - mean_residual) * 0.10;
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Non-linear polynomial coupling of post_residual with progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth waste penalty: cubic in normalized post-residual, modulated by progress.
    // Early in the stream, waste is cheap (bins get filled later); late, waste is costly.
    let progress_coupling = 0.5 + 1.5 * progress * progress;
    score += 2.0 * pr_norm * pr_norm * pr_norm * cap * progress_coupling;

    // Reward tight fits: quadratic bonus when post_residual is small, stronger late.
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead coupling: if next item fits into post_residual, reward leaving
    // exactly that much space (smooth interaction term).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let nx_norm = nx / cap;
        let gap = (pr_norm - nx_norm).abs();
        // penalize mismatch between leftover space and next item size
        score += 3.0 * gap * gap * cap * (0.4 + 0.6 * progress);
        // extra reward if next item fits exactly-ish
        if nx <= pr {
            score -= 2.0 * (1.0 - gap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the waste is huge (smooth tradeoff rather than hard threshold).
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_norm * pr_norm);
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in a way that consolidates space (smooth quadratic attraction).
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / (cap * cap) * 10.0;

    // New-bin candidate handling: an empty bin has zero waste now, but opening
    // it early is wasteful; penalize smoothly with progress and open-bin count.
    if bin_residual == bin_capacity {
        let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 4.0 + 6.0 * progress + 5.0 * open_norm;
        // but if the item is huge relative to capacity and nothing else fits well,
        // the last-chance bonus above already covers single-fit cases.
    }

    // Mild preference for fuller bins overall (smooth in bin_residual).
    let br_norm = bin_residual as f64 / cap;
    score -= 1.5 * br_norm * br_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the residual: classify post_residual into modulo classes ---
    // Residuals that are "harmonically useful" (multiples of small sizes) are less dead space.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -40.0 // perfect closure: heavily reward
    } else if pr % 10 == 0 {
        -12.0 // round residual: likely reusable by future items
    } else if pr % 5 == 0 {
        -6.0
    } else if pr < 10 {
        18.0 // tiny dead space: unusable, penalize strongly
    } else {
        0.0
    };
    score += class_penalty;

    // --- Coupling with next item: does post_residual accommodate the lookahead item? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits here too: reward proportionally to how snugly
            let snug = (pr - next_item_size) as f64;
            score -= 8.0 + 0.25 * (pr as f64) - 0.1 * snug;
        } else {
            // lookahead does NOT fit: penalize more if the miss is small (near-miss waste)
            let miss = (next_item_size - pr) as f64;
            score += 0.35 * miss;
        }
    }

    // --- Integer-division threshold on post_residual vs capacity fractions ---
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr <= quarter {
        score -= 5.0; // compact bins are good bins
    } else if pr > half {
        score += 6.0; // leaving more than half empty is wasteful placement
    }

    // --- Last-chance dynamics: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate (empty bin) handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: its full residual is potential waste.
        score = (bin_capacity as f64) * 0.85;
        // Open a new bin only when existing bins fit badly or are congested.
        if fitting_bins_count == 0 {
            score -= 60.0; // forced: nothing fits elsewhere
        } else if fitting_bins_count == 1 {
            score -= 10.0; // mild competition with the lone fitting bin
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin can absorb the upcoming item too
        }
        if open_bins_count > 24 {
            score += 0.5 * (open_bins_count as f64 - 24.0); // discourage bin sprawl
        }
        return score;
    }

    // --- Tightness bonus: reward filling most of the bin ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // --- Stream progression: later in stream, prefer closing bins tightly ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - pr as f64 / bin_capacity as f64);

    // --- Mean residual coupling: penalize deviating far from the fleet mean ---
    score += 0.08 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to be useful later, but not zero.
    if post_residual > 0 {
        // Small gaps (<= 10) are almost certainly dead space.
        if post_residual <= 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 40 {
            score += 8.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 100.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open,
    // to avoid bin proliferation.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += open_pressure;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is part of a good chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit in the leftover: leftover likely becomes dead space.
        score += 12.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight — finishing it is good.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    } else {
        score += (-residual_gap) * 0.1;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
        // If no open bin fits well and post_residual of new bin is large, allow it.
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // 2-step lookahead: reward when the next item fits exactly into the post residual
    if next > 0.0 {
        if next <= post {
            // tighter the match, the bigger the reward
            let gap = post - next;
            let fit_quality = 1.0 - gap / cap;
            score -= 30.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit here: penalize leaving large unusable slack
            let waste = post / cap;
            score += 20.0 * waste * waste;
        }
    }

    // prefer filling bins below mean residual (tight packing)
    let mean_gap = post - mean_residual;
    score += 0.15 * mean_gap;

    // last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // slight preference for existing bins over opening new ones early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - progress);
    } else {
        score -= 2.0;
    }

    // penalize very small dead space that is hard to reuse
    if post > 0.0 && post < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be picky; later, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: penalize large post-residual quadratically.
    let pr = post_residual as f64;
    score += (pr * pr) / bin_capacity as f64;

    // Reward using bins that are already partially full (avoid bin sprawl).
    let used = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 20.0 * used * (1.0 - progress);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reserve this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Next item can still go here; mild bonus if it fills the bin perfectly.
            if (post_residual as f64 - nxt).abs() < 1.0 {
                score -= 25.0;
            } else {
                score -= 5.0;
            }
        } else if nxt as u32 > post_residual && nxt as u32 <= bin_residual {
            // Next item would have fit before this placement but not after: penalize.
            score += 12.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        score += pressure * 8.0 * progress;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is opened only for bad fits elsewhere.
        score += 35.0;
        // Early in the stream, opening bins is cheap.
        score -= 25.0 * (1.0 - progress);
        // If many bins can fit this item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // Large items benefit from a fresh bin.
        if fill_ratio > 0.6 {
            score -= 15.0;
        }
    }

    // Slight noise-free tie-break toward lower residual bins.
    score += 0.01 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let mut score = r;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = (1.0 - progress) * (rn * rn) + progress * (rn * rn * rn);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - rn) * (1.0 + progress) * 10.0;

    // Penalize wasted space relative to mean residual of open bins
    score += 0.3 * (r - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving post_residual that can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - progress);
    }

    // Mild penalty for opening a brand-new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // Anything below the minimum item size (1) is dead; penalize residuals
    // that are too small to be useful relative to typical item sizes.
    let dead_threshold = 10.0_f64.min(item_size as f64);
    if (post_residual as f64) < dead_threshold {
        score += 500.0 + (dead_threshold - post_residual as f64) * 50.0;
    }

    // Smooth super-linear penalty on wasted space (quadratic coupling).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good.
    score += (open_bins_count as f64) * 2.0 * (1.0 - fit_ratio);

    // New-bin candidate logic: an empty bin is only attractive when the
    // current item would leave a large, usable residual elsewhere OR when
    // no open bin fits well. Make the empty bin slightly unattractive by
    // default so fragmentation is avoided.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is large relative to mean residual, opening fresh
        // may be better: relax the penalty.
        if item_size as f64 > mean_residual * 0.8 {
            score -= 25.0;
        }
        // Lookahead: if the next item is large, prefer keeping big residuals
        // in existing bins and start fresh.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 10.0;
        }
    } else {
        // Lookahead synergy: reward leaving a residual that exactly fits the
        // next item (or nearly so).
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        }
    }

    // Early-stream exploration: with few bins open, be more willing to fill
    // imperfectly; late-stream, be stricter about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * waste_frac;

    // Mean-residual coupling: bins far below the mean residual are better
    // candidates to close out (fill them now).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: match post_residual to the next item.
    let next = next_item_size as f64;
    if next > 0.0 {
        if post_residual as f64 == next {
            // Perfect 2-step match: heavily reward.
            score -= 60.0;
        } else if (post_residual as f64 - next).abs() <= 5.0 {
            // Near match: strong reward.
            score -= 30.0;
        } else if (post_residual as u32) < next_item_size {
            // Dead space relative to the next item: penalize proportionally.
            score += (next - post_residual as f64) * 0.8;
        } else {
            // Next item fits with leftover: mild reward scaled by proximity.
            score -= 10.0 * (1.0 - ((post_residual as f64 - next) / bin_capacity as f64));
        }
    }

    // Relative to mean residual: prefer bins whose resulting residual
    // is close to (or below) the mean, avoiding outlier waste.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are very fragmented
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 25.0;                       // base penalty: prefer existing bins
        score -= 50.0 * fragmentation;       // reward opening when residuals are large/wasted
        score -= 30.0 * large_item;          // big items justify a fresh bin
        if next > 0.0 && (bin_capacity as f64 - next) < item_size as f64 {
            score -= 20.0;                   // fresh bin pairs well with next item
        }
    }

    // Slight preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 {
            score += 4.0; // leftover too small for lookahead item
        }
    } else {
        // Last item: prefer filling a bin completely.
        score -= 5.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, be aggressive about filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * fit_ratio;
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
        score -= 0.02 * mean_residual;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Opening a new bin is fine early on when mean residual is high (bins fragmented).
        score -= 3.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nr = next_item_size as f64;
    let fits = post_residual > 0 && (nr == 0.0 || nr <= pr);

    // Base: minimize wasted residual, with non-linear (quadratic + cubic) shaping
    let mut score = pr / cap;
    score += 0.35 * (pr / cap).powi(2);
    score -= 0.15 * (pr / cap).powi(3);

    // Smooth non-linear coupling between post_residual and stream progress:
    // early on, tolerate slack; late, punish residual harshly (super-linear ramp)
    let late_bias = progress * progress;
    score += pr / cap * (0.4 * late_bias + 0.8 * progress.powi(3));

    // Reward bins whose post-residual still fits the lookahead item (smooth gate)
    if fits && nr > 0.0 {
        let tightness = 1.0 - ((pr - nr) / cap).abs();
        score -= 0.6 * tightness * (1.0 + 0.5 * progress);
    }

    // Penalize "last chance" bins only mildly, more as stream progresses
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 0.3 + 0.4 * progress;
    }

    // New-bin candidate: prefer opening fresh bins when mean residual of open bins is low
    if bin_residual == bin_capacity {
        let mr = mean_residual / cap;
        score = 0.9 - 0.5 * mr * (1.0 - progress) - 0.3 * progress;
    }

    // Mild pressure against bin proliferation
    score += 0.002 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (integer division buckets).
    let class = post_residual / 25; // 0: tiny, 1: small, 2: medium, 3: large
    match class {
        0 => score -= 30.0,                       // near-perfect fill
        1 => score -= 12.0,                       // good fill
        2 => score -= 4.0,                        // moderate
        _ => {}                                   // large residual: neutral
    }

    // Exact-fit reward modulo classes: residual divisible by small harmonics.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 5 == 0 { score -= 3.0; }

    // Pairing lookahead: can next item exactly fill post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nxt_class = (post_residual - next_item_size) / 25;
            score -= 10.0 - 3.0 * nxt_class as f64;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    } else {
        // last item: any placement is free
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless residual would be well-harmonic.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 { score -= 35.0; }
            else if rem / 25 == 0 { score -= 20.0; }
        }
        if post_residual % 10 == 0 { score -= 10.0; }
    }

    // Progress-aware tie-break: later in stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for tighter bins among equals.
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 unknown,
    // assume min plausible item ~10) are wasted; penalize the "unusable gap" zone hard.
    let min_item = 10u32;
    if post_residual < min_item && post_residual > 0 {
        // dead space: scale penalty by how close we came to a perfect fill vs a hopeless gap
        score += 40.0 * (1.0 - post_residual as f64 / min_item as f64) + 15.0;
    } else if post_residual == 0 {
        // perfect fill: strong reward
        score -= 50.0;
    }

    // Tight fit reward: fraction of bin used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Open-bins pressure: with many bins open, prefer consolidating into existing bins;
    // with few bins open, spreading out is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
        // If next item is large, a fresh bin gives future flexibility
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for leaving medium gaps
        if post_residual >= min_item {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nr;
        if diff == 0.0 {
            // Perfect: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else if diff < 0.0 {
            // Dead space for the next item: penalize proportionally.
            score += (-diff) * 1.5;
        } else {
            // Leftover after next item: mild penalty, worse if tiny sliver.
            if diff < 5.0 {
                score += 25.0;
            } else {
                score += diff * 0.25;
            }
        }
    }

    // Prefer bins whose residual is below the mean (tight packing targets).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening new bins early in the stream when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 35.0 + 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for filling large chunks of a bin.
    score -= item_size as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of fit: reward near-perfect fills strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 4.0 + 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: many open bins with high mean residual -> prefer new bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when open bins are fragmented.
        score -= 6.0 + 3.0 * (mean_residual / bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);
    }

    // Time-horizon modulation: early stream, be conservative (avoid waste); late, exploit tight fits.
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * (1.0 - progress);
    score += 12.0 * poly;

    // Tight fits favored more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as i32 as f64;
        score -= 6.0 * next_fits * (1.0 - (next_item_size as f64 / cap - norm_pr).abs());
    } else {
        score -= 5.0 * norm_pr;
    }

    // Penalize scattering across many open bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress * norm_pr;

    // Mean residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: mildly penalize opening a fresh bin early, allow late
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 - progress);
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue classes
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "dead" (small, hard to fill) get penalized
    if pr > 0 && pr < 10 {
        score += 12.0;
    } else if pr == 0 {
        score -= 30.0; // perfect fill
    } else {
        // Harmonic bonus: residual divisible by common item classes (5,10,20,25)
        if pr % 25 == 0 { score -= 8.0; }
        else if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else { score += 2.0; }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + 0.1 * (pr - next_item_size) as f64;
            // harmonic match: next item exactly consumes a class boundary
            if pr % next_item_size == 0 { score -= 6.0; }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    } else {
        score -= 15.0; // last item: prefer filling existing bins
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // all existing fits would leave tiny dead space
    if bin_residual == bin_capacity {
        score = 45.0 - 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Progress-based tightening: late in stream, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;
    score -= 0.1 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use are pure waste.
    // Penalize unusable slivers harshly; tiny leftovers (< ~10) are near-waste.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: heavily rewarded
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual < 20 {
        score += 12.0; // barely usable
    }

    // Reward good fits proportionally (low post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few, opening is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if this bin is a bad fit elsewhere or bins are few.
        score += 8.0 + pressure * 0.5;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
    } else {
        score -= pressure * 0.15;
    }

    // Lookahead: if the next item fits the post-residual, reward keeping this residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in post-residual but could fit elsewhere, slightly penalize.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Perfect chain: next item exactly fills remaining space.
            if (pr - nxt).abs() < 1.0 {
                score -= 500.0;
            } else {
                score -= 120.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize proportionally to the mismatch.
            score += 40.0 * (nxt - pr) / 100.0;
        }
        // Coupling with mean residual: prefer bins whose leftover stays near the mean
        // (keeps flexibility across the fleet of open bins).
        let dev = (pr - mean_residual).abs();
        score += 0.5 * dev;
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Late in the stream, prefer tighter packing over opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress;

    // Slight penalty when many bins are already open (encourage consolidation).
    score += 0.2 * open_bins_count as f64;

    // New-bin candidate: only attractive if no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but avoid leaving useless slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead-space penalty for unusable slivers
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits into the post residual (chaining),
    // penalize if it nearly fits but not quite (wasted opportunity).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // placing here kills a fit for next item that exists now
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tightness ratio: normalized fill quality.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness * tightness;

    // Time horizon: early in the stream, be pickier (penalize loose fits),
    // late in the stream, just fill bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    // Global state: many open bins -> encourage closing them out (use existing bins).
    if open_bins_count > 3 {
        score -= 0.8 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: if this bin is far below mean residual (it is fuller),
    // it is a good target; if far above (very empty), less attractive unless new bin.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -100.0; // must open a new bin
        } else {
            // penalize opening new bin, more so early when we can still pack tightly
            score = 60.0 + 40.0 * (1.0 - progress) + 0.5 * mean_residual;
            if next_item_size > 0 && next_item_size <= item_size {
                score -= 10.0; // new bin can host next item too
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < f64::EPSILON;

    // Base: prefer tight fits (small post_residual), with a non-linear
    // (quadratic) penalty on wasted space normalized by capacity.
    let w = post / cap;
    let mut score = post * (1.0 + 2.0 * w * w);

    // Smooth stream-progress coupling: as the stream advances, waste
    // becomes increasingly costly (bins already sunk, consolidate).
    let prog_coupling = 1.0 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Interaction of post_residual with mean residual: placing into a bin
    // whose residual is near the item size is ideal; a large gap between
    // bin_residual and item (big leftover elsewhere in the pool) is a mild penalty.
    let fit_gap = (bin_residual as f64 - item) / cap;
    score += 8.0 * fit_gap * fit_gap * (0.5 + progress);

    // Lookahead coupling (k=2): reward bins whose post_residual still
    // accommodates the next item; penalize bins that strand the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (post - nxt) / cap;
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin for a placeable item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0 * (1.0 - w) * (1.0 + progress);
    }

    // New-bin candidate handling: a fresh bin is attractive only when no
    // open bin fits well (large item, scarce fitting bins) or early stream.
    if is_new_bin {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let big_item = item / cap;
        score += 15.0 * (1.0 - big_item) * (1.0 + progress); // fresh-bin waste penalty
        score -= 20.0 * scarcity * (1.0 - w);                 // reward when fits are scarce
        score -= 5.0 * (1.0 - progress);                      // slightly cheaper to open early
        // If the next item would pair well with the leftover, new bin is fine.
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 4.0;
        }
    }

    // Mild penalty for proliferation of open bins, smoothed by progress.
    score += 0.6 * open_bins_count as f64 * (0.3 + progress);

    // Tie-breaker: tiny preference toward bins closest to full.
    score += 0.05 * (1.0 - (bin_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into usable classes.
    // Class 0: post_residual == 0 (perfect)
    // Class 1: post_residual small (<=10) -> near-perfect
    // Class 2: post_residual can host next item
    // Class 3: post_residual is a "harmonic" size (multiple of common item sizes)
    let mut class_penalty = 0.0;

    if post_residual > 0 {
        // Dead-space penalty grows super-linearly for small unusable slivers.
        if post_residual < 10 {
            class_penalty += (10 - post_residual) as f64 * 2.0;
        }

        // Harmonic divisibility bonus: leftover divisible by 10/20/25/50 is reusable.
        let harmonic = (post_residual % 10 == 0) as f64 * 3.0
            + (post_residual % 20 == 0) as f64 * 2.0
            + (post_residual % 25 == 0) as f64 * 2.0
            + (post_residual % 50 == 0) as f64 * 3.0;
        class_penalty -= harmonic;

        // If next item fits into post_residual, big reward (chaining).
        if next_item_size > 0 && next_item_size <= post_residual {
            class_penalty -= 15.0;
            // Extra reward if next item then leaves a harmonic leftover.
            let nn = post_residual - next_item_size;
            class_penalty -= (nn % 10 == 0) as f64 * 5.0;
        } else if next_item_size > 0 {
            // Next item cannot use leftover: penalize proportionally.
            class_penalty += (next_item_size as f64).min(post_residual as f64) * 0.3;
        }
    }

    // Integer-division threshold on post_residual: mid-range leftovers are worst.
    let q = post_residual / 25; // 0..4
    match q {
        0 => class_penalty += 4.0,          // tiny sliver
        1 => class_penalty += 0.0,          // 25..49: usable
        2 => class_penalty += 2.0,          // 50..74
        3 => class_penalty += 1.0,          // 75..99
        _ => class_penalty += 6.0,          // full empty bin chosen as normal candidate
    }

    score += class_penalty;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless open bins are nearly full or item is huge.
    if bin_residual == bin_capacity {
        let tight = mean_residual < 15.0;
        let big_item = item_size >= 60;
        let mut nb = 40.0;
        if tight { nb -= 30.0; }
        if big_item { nb -= 10.0; }
        // Early in stream, slightly prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += (1.0 - progress) * 5.0;
        score += nb;
    }

    // Mild pressure to prefer bins with less residual among ties.
    score += (bin_residual as f64) * 0.05;
    score -= (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (min size 1, but realistically small gaps) are heavily
    // penalized. Treat residual < 10 as unusable dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits (small post_residual) more aggressively.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fits.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and this bin's post_residual is a near-miss gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 40 {
        score += 10.0;
    }

    // Slight preference for keeping mean residual high (avoid fragmenting bins
    // when average leftover is already small).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Progress: late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next > 0.0 {
        let gap = (post - next).abs();
        if post >= next {
            // Perfect chain: next item exactly fills the leftover space.
            if gap < 1.0 {
                score -= 30.0;
            } else if gap <= 5.0 {
                score -= 20.0 * (1.0 - gap / 5.0);
            } else {
                score -= 8.0 * (1.0 - gap / cap).max(0.0);
            }
        } else {
            // Next item doesn't fit here: penalize wasted potential.
            score += 6.0 + 4.0 * (next - post) / cap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when they fit well.
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent chain.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next > 0.0 && post >= next {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: tighten packing as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize small unusable dead space (residual < smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to leftover waste
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer the fullest (small residual before placement)
        score += 3.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Global state: many open bins -> encourage consolidation into existing bins
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += 5.0 * openness.min(3.0);

    // Mean residual coupling: if this bin is much emptier than average, discourage wasting it
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.10 * (-dev);
    }

    // Time horizon: late in stream, be more conservative (prefer exact packing, avoid new bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a moderate default cost;
    // only attractive when no open bin is a decent fit (handled via fitting_bins_count)
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover residual, but non-linearly (quadratic waste pressure)
    let mut score = pr * (1.0 + 0.6 * norm_pr);

    // Smooth coupling of residual with stream progress: later in the stream,
    // tighter fits matter more (dead space becomes costlier).
    let progress_coupling = 1.0 + 0.9 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= progress_coupling;

    // Non-linear interaction: post_residual vs mean residual across open bins.
    // Prefer bins whose post-residual sits below the mean (tighter than average).
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.35 * (pr - mr) + 0.15 * (pr - mr).powi(2) / cap;

    // Reward filling bins nearly exactly: smooth exponential bonus as post_residual -> 0.
    score -= 12.0 * (-pr / 15.0).exp();

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth via inverse count).
    let fit = fitting_bins_count as f64;
    score -= 8.0 / fit;

    // Lookahead: reward if next item fits well into post_residual (smooth gaussian match)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-gap * gap / 200.0).exp();
    } else {
        // Last item: strongly prefer exact fill
        score -= 10.0 * (-pr / 8.0).exp();
    }

    // Mild penalty for spreading across many bins: encourage consolidation
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: empty bin has full residual; make it unattractive unless
    // nothing fits well (its large residual already scores high, add slight bias).
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space
    // Class 0: post_residual == 0 (perfect fill) -> huge reward
    // Class 1: tiny leftover (1..=5) -> strong reward
    // Class 2: leftover is a common item size (10,20,...,80) -> reward
    // Class 3: leftover divisible by 10 -> mild reward
    // Class 4: awkward leftover -> penalty
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 5 {
        score -= 60.0;
    } else if pr % 10 == 0 && pr >= 10 && pr <= 80 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else {
        // awkward dead space penalty, worse for very small unusable slivers
        score += (10 - (pr % 10)) as f64 * 2.0;
        if pr < 10 {
            score += 40.0; // dead space below minimum item size
        }
    }

    // Harmonic class via integer division: leftover in [0,20) vs [20,50) vs [50,100]
    let tier = pr / 20; // 0,1,2,3,4
    score -= (4 - tier.min(4)) as f64 * 5.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            // next item won't fit here: penalize leaving large unused space
            score += (pr as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (tight packing)
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Mild preference to consolidate when many bins open
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize unless nothing else works well;
    // opening a new bin is only good if this item is large relative to capacity
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 35.0 - large_item * 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // pairing potential in fresh bin
        }
    }

    // Stream progression: late in stream, be greedier about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Tie-break against mean residual spread
    score -= (mean_residual - pr as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1..10)
    // are worthless; penalize them hard, especially gaps in [1, 12].
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 8.0 + 10.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // But if this bin would otherwise leave a large unusable gap in an
        // existing bin, opening fresh can still win via lower base score.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item can't use the leftover: leftover is likely dead space
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // Mild preference to keep bins' residuals balanced around the mean.
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack * 0.15);
    }
    // Penalize residuals too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable residuals relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly reward using it, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // unless the current item leaves a perfect next-fit residual.
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && post_residual == next_item_size;
        if fitting_bins_count > 0 && !perfect {
            score += 30.0;
        } else if fitting_bins_count > 0 && perfect {
            score += 5.0;
        }
        // Later in the stream, prefer consolidation into open bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild reward for many fitting alternatives being reduced by this choice.
    if fitting_bins_count > 2 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is ideal).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize large dead space that only a small future item could use.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.05;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 25.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this bin's remaining space: mild penalty scaled by waste.
            score += 0.1 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual.max(0.0))).min(10.0);
    score -= pressure * 0.5;

    // New-bin candidate: penalize opening a new bin unless the item is large and
    // current open bins are crowded (their residuals are small relative to item).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        let late = step_index as f64 / total_items.max(1) as f64;
        if crowded && late > 0.3 {
            score -= 8.0; // acceptable to open a bin when nothing fits well
        } else {
            score += 40.0 + 20.0 * (1.0 - late); // discourage early bin opening
        }
    }

    // Time horizon: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to mean (balanced packing) slightly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness reward: strongly favor bins where the item nearly fills residual.
    let residual = bin_residual as f64;
    let fit_ratio = if residual > 0.0 { item_size as f64 / residual } else { 0.0 };
    // Smooth quadratic coupling: perfect fit (fit_ratio ~ 1) gets max reward.
    let tightness = fit_ratio * fit_ratio;
    score -= 25.0 * tightness;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space hurts more -> penalize leftover space super-linearly.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let progress_coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress * progress);
    score += 40.0 * progress_coupling;

    // Lookahead: reward if the next item can use the post residual exactly or well.
    if next_item_size > 0 && post_residual > 0 {
        let next_fit = if (post_residual as f64) >= next_item_size as f64 {
            let r = next_item_size as f64 / post_residual as f64;
            r * r
        } else {
            0.0
        };
        score -= 12.0 * next_fit;
        // Penalize if post residual is smaller than next item but nonzero (dead space for lookahead).
        if post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + progress);
    } else if fitting_bins_count > 1 {
        // Mild penalty to allow discrimination among multiple fits by tightness.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: prefer bins whose residual deviates from mean
    // in the direction of being filled (below-mean residual bins are "warm").
    let dev = residual - mean_residual;
    score -= 5.0 * (dev / bin_capacity as f64) * (1.0 - progress);

    // New-bin candidate: only attractive when no good fits exist (many bins but
    // poor tightness) or early in the stream. Otherwise penalize opening new bins.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        let squeeze = (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)).powi(2);
        let new_bin_score = pr + 20.0 - 45.0 * squeeze - 15.0 * (1.0 - progress);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Dead-space penalty grows superlinearly for residuals in "awkward" bands.
    if post == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if post < eighth {
        // Tiny sliver: nearly dead space, but cheap to leave behind.
        score += 15.0 - (post as f64);
    } else if post < quarter {
        // (C/8, C/4): moderately awkward band.
        score += 8.0;
    } else if post < bin_capacity / 2 {
        // (C/4, C/2): still useful for medium items.
        score -= 6.0;
    } else {
        // Large residual left: wasteful placement.
        score += 10.0;
    }

    // --- Harmonic compatibility: does post_residual match the lookahead item via modular classes?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= post {
            // Lookahead fits exactly into the resulting hole: excellent chaining.
            let gap = post - nxt;
            score -= 25.0 - (gap as f64).min(20.0);
            // Exact chain (gap 0) is the best outcome.
            if gap == 0 {
                score -= 20.0;
            }
        } else {
            // Lookahead does NOT fit this bin's hole; penalize if the hole is
            // just barely too small (frustrating near-miss), mildly otherwise.
            let miss = nxt - post;
            if miss <= eighth {
                score += (miss as f64) * 1.5;
            } else {
                score += 2.0;
            }
        }
        // Modular harmony: residuals congruent to common item sizes mod 10 are reusable.
        let mod_class = post % 10;
        if mod_class == 0 {
            score -= 5.0;
        } else if mod_class >= 7 {
            score += 4.0; // ragged residue, hard to reuse
        }
    } else {
        // Last item: just fill tightest possible.
        score -= 30.0;
    }

    // --- Last-chance bin: strongly prefer using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling: opening a fresh bin is only attractive when
    // this item is large and existing residuals are small/awkward.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin: proportional to stream progress
        // (early on, keep bin count low; later, be more willing to open).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * (0.55 - 0.15 * progress);
        // If item is huge, a new bin is fine (it will consume most of it anyway).
        if (item_size as f64) > 0.6 * cap {
            score -= 15.0;
        }
        // If the current bin would be left with an awkward sliver, new bin looks better.
        if post > 0 && post < eighth {
            score -= 12.0;
        }
        // Many open bins with big mean residual: don't open another.
        if mean_residual > 0.35 * cap {
            score += 20.0;
        }
    } else {
        // Slight preference for tighter existing bins beyond raw post_residual:
        // couple with mean residual to break ties toward below-average-fill bins.
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // --- Mild global pressure: when many bins are open, consolidate more aggressively.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
