        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when existing bins would waste space badly.
    if bin_residual == bin_capacity {
        // Baseline competitiveness: raw post_residual = capacity - item_size.
        // Slight bonus so a fresh bin wins when all open bins create dead space.
        score -= 5.0;
        // Discourage opening new bins when the stream is early and few bins are open.
        if open_bins_count < 3 {
            score += 25.0;
        }
        // If many bins are open, prefer consolidation unless dead space penalty above dominates.
        score += (open_bins_count.min(10) as f64) * 0.5;
    }

    // Mild mean-residual coupling: prefer bins near the mean residual (typical fill level).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

