    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in a
    // "usable" residue class (divisible by small denominators) are favored,
    // since future items more likely tile them exactly.
    let cap = bin_capacity as f64;

    // Class-1: post_residual divisible by 10 -> prime target for tiling.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class-2: divisible by 5 but not 10 -> secondary target.
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class-3: odd residual is harder to fill with even-ish items.
    if post_residual % 2 == 1 {
        score += 2.0;
    }

    // Integer-division thresholds: how many "unit chunks" of 10 remain.
    let chunks = post_residual / 10;
    match chunks {
        0 => score += 4.0,            // dead space, nearly unusable
        1 => score += 1.5,            // only tiny items fit
        2 | 3 => score -= 1.0,        // sweet spot for medium items
        _ => score -= 0.5,            // roomy bin, keep flexible
    }

    // Coupling with lookahead item: if next item exactly matches post
    // residual, this is a perfect closure -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        } else if next_item_size > post_residual {
            score += 1.0; // next item won't fit here; bin will strand anyway
        }
    }

    // Fraction-of-capacity harmonic bands on the fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill > 0.9 {
        score -= 4.0; // nearly full: close it out, great packing
    } else if fill > 0.7 {
        score -= 2.0;
    } else if fill < 0.3 {
        score += 1.0; // shallow packing: deprioritize dumping into it early
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a
    // terrible fit unless post_residual is harmonically small.
    if fitting_bins_count == 1 {
        if post_residual <= 5 {
            score -= 8.0; // acceptable: bin is essentially done
        } else {
            score += 2.0; // prefer opening a fresh bin if fit is sloppy
        }
    }

    // New-bin candidate handling: empty bin has neutral baseline; make it
    // attractive only when open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64 / cap) * 0.0; // empty bin: post==cap
        let _ = pressure;
        // Compare mean fragmentation of open bins.
        if open_bins_count > 0 && mean_residual > 40.0 {
            score = cap * 0.6; // open bins are roomy; don't open another
        } else {
            score = cap * 0.45; // fresh bin is a decent fallback
        }
        // Early stream: keep bin count low, prefer existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 8.0;
        // If next item is huge, a fresh bin may serve it better.
        if next_item_size >= 70 {
            score -= 5.0;
        }
    }

    // Mild global pressure: many open bins -> consolidate into existing ones.
    score += open_bins_count as f64 * 0.15;

    // Tiny tie-break on exact-fit geometry of item vs residual.
    if item_size == bin_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold
    // the minimum item size (1..100 domain -> use a conservative
    // small-gap threshold) are heavily penalized.
    let dead_threshold = 8.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 12.0; // unusable sliver penalty
    }

    // Perfect / near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if pr <= 3.0 {
        score -= 25.0;
    }

    // General tightness reward: smaller post_residual relative to
    // capacity means the bin was used efficiently.
    score -= 40.0 * (1.0 - pr / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive when
    // many bins are already open; favor existing bins then.
    if bin_residual == bin_capacity {
        score += 25.0 + 6.0 * open_bins_count as f64;
        // But if no existing bin fits well, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Open-bins pressure: more open bins -> prefer consolidating
    // into existing bins (penalize new bins implicitly, reward
    // placements that reduce mean residual imbalance).
    score += 0.15 * open_bins_count as f64 * (pr / bin_capacity as f64);

    // If the next item could exactly use the leftover space,
    // reward leaving exactly that residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // Avoid leaving residuals that neither fit the next item nor
    // any plausible item (dead space prediction).
    if next_item_size > post_residual && post_residual > 0 && pr < 25.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            score -= 60.0; // next item still fits here
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8; // dead space penalty
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates usefully
    let diff = post_residual as f64 - mean_residual;
    if diff < 0.0 {
        score += diff * 0.5; // tighter-than-average bins favored
    } else {
        score += diff * 0.3;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 50.0 * open_bins_count as f64 + 200.0;
        if fitting_bins_count == 0 || next_item_size > post_residual {
            score -= 250.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 30.0 * (post_residual == 0 || post_residual == next_item_size) as u32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), with a safe fallback for total_items == 0.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base fit quality: strongly favor minimal post_residual (best-fit core).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 10.0;

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item can exactly use the leftover space, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mildly reward, proportional to how well the leftover
            // is consumed by the pair.
            let pair_waste = (post_residual - next_item_size) as f64;
            score += pair_waste * 0.3;
            score -= 8.0;
        } else {
            // Next item cannot use the leftover: penalize leaving large dead space.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        // Extra urgency late in the stream: keep bins tight.
        score -= progress * 6.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit into
    // existing bins is bad or the item is large enough to deserve fresh space.
    if bin_residual == bin_capacity {
        // Base penalty: opening a new bin is expensive.
        score += 25.0;
        // Large items benefit from a fresh bin (avoid fragmenting many small bins).
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If many bins are open with high mean residual, prefer consolidating.
        score += mean_residual * 0.2;
        // Late in the stream, prefer reusing existing bins.
        score += progress * 10.0;
        // If only one fitting bin exists, opening a new bin is rarely good.
        if fitting_bins_count <= 1 {
            score += 15.0;
        }
    }

    // Global state coupling: with many open bins, tighten packing (penalize waste).
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.02;

    // Reward bins whose residual is already small relative to the mean (tight bins).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Slight preference for filling bins closer to capacity as the stream ends.
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress:
    // later in stream => waste penalized more strongly (quartic ramp)
    let progress_ramp = 0.5 + 3.5 * progress * progress * progress;
    score += progress_ramp * norm_pr * pr * 0.5;

    // Dead-space penalty: residuals too small to fit even the smallest item (1..)
    let dead = if pr == 0 { 0.0 } else if pr < 10.0 { (10.0 - pr) * (10.0 - pr) } else { 0.0 };
    score -= dead * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits exactly into post residual (smooth gaussian coupling)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_bonus = (-0.05 * diff * diff).exp();
        score -= 12.0 * fit_bonus * (1.0 + progress);
        // Penalize if post residual too small for plausible next item
        if pr > 0.0 && (next_item_size as f64) > pr {
            score += 3.0 * (1.0 - (pr / next_item_size as f64).powf(2.0));
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + 2.0 * progress);
    }

    // New-bin candidate: penalize opening new bins when decent fits exist,
    // but allow it when mean residual across open bins is low (bins nearly full)
    if bin_residual == bin_capacity {
        let mean_fill = mean_residual / cap;
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 18.0 * openness * (1.0 - mean_fill).powf(1.5);
        score -= 10.0 * mean_fill * mean_fill;
        // early stream: opening bins is cheap
        score -= 15.0 * (1.0 - progress).powf(2.0);
    }

    // Mild penalty for bins whose residual deviates from mean (keep pool homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: bins whose post_residual falls into "usable" residue classes
    // (multiples of 10) are rewarded; awkward residues are penalized.
    let pr = post_residual;
    let residue = pr % 10;
    if residue == 0 {
        score -= 12.0; // perfectly aligned leftover
    } else if residue <= 3 || residue >= 7 {
        score += 6.0; // awkward dead-space class
    }

    // Integer-division thresholds: post_residual bucketed by capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr < quarter {
        score += 10.0; // nearly-full bin, good closure
    } else if pr < half {
        score -= 4.0; // half-class residual still flexible
    } else if pr == bin_capacity {
        // new-bin candidate: only attractive when nothing fits well
        let pressure = if fitting_bins_count <= 1 { 25.0 } else { 0.0 };
        score -= pressure;
        score += 15.0; // default mild penalty vs reusing open bins
    } else {
        score += 2.0;
    }

    // Lookahead harmonic coupling: can next item exactly fill the leftover?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect pairing
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 14.0; // next item leaves aligned residue
        } else if next_item_size > pr {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Stream progression: early on prefer tight packing (minimize score for low waste),
    // later allow looser fits to keep many bins serviceable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Mean-residual coupling: if open bins are already tight on average,
    // reward placing into this bin rather than spreading.
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are nearly worthless; penalize them heavily.
    let dead_zone = 15.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal.
        score -= 60.0;
    }

    // Reward bins whose residual is "chunked" into useful sizes:
    // post_residual exactly matching a plausibly arriving item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0; // cannot host the lookahead item
    }

    // Tight-fit bonus: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a good candidate to be "closed out" (filled tightly).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: mild penalty so tight existing fits win,
        // but poor fits (large post_residual) lose to it.
        score = 55.0 + 2.0 * open_bins_count as f64
            - 30.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 {
            // A fresh bin always fits the next item; slight bonus.
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            // No real alternative: opening a new bin is fine.
            score -= 20.0;
        }
    }

    // Slight stream-progression tilt: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item can fit into the post
    // residual, this placement chains nicely — reward it proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // perfect chain: two items fill the bin exactly
        } else if next_item_size < post_residual {
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 300.0 - chain_left * 2.0; // good chain, penalize leftover
        } else {
            // next item cannot follow into this bin: dead-end penalty scaled
            // by how much usable space is wasted relative to next item size.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 3.0;
        }
    }

    // Compare against mean residual: bins already tighter than average are
    // natural targets; loose bins (high residual) should absorb big items.
    let res_f = bin_residual as f64;
    let dev = res_f - mean_residual;
    score += dev * 0.5;

    // Last-chance bin: if this is the only bin that fits, use it before
    // opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is huge and no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let decent_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64 * 1.2;
        if decent_fit_exists && item_size < 60 {
            score += 120.0; // discourage wasting a fresh bin
        } else {
            score -= 40.0; // big items or no alternatives: fresh bin is fine
        }
    }

    // Early in the stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && progress < 0.5 {
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer leaving residuals that are commonly reusable (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins with small post-residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = post_residual - next_item_size;
        score -= 6.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
    }
    // If next item does NOT fit post_residual, mild penalty proportional to dead space.
    else if next_item_size > 0 {
        score += 2.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64).min(1.0));
    }

    // Last-chance bin: reward using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize new empty bins unless it's a genuinely good deal:
    // opening a bin is cheaper when many bins are open with high mean residual.
    if bin_residual == bin_capacity {
        score += 10.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in stream, avoid opening bins for small items.
        score += 8.0 * progress * (1.0 - item_size as f64 / bin_capacity as f64);
        // If item fills a fresh bin well, allow opening.
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
        // If a fitting open bin has decent residual, discourage new bin.
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 4.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * (0.5 - progress);

    let mut score = pr + 20.0 * poly;

    // Reward tight fits smoothly
    score -= 15.0 * fill * fill;

    // Last fitting bin: strong bonus that decays with progress
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress) + 6.0;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Slight preference for bins below mean residual early on
    score += 3.0 * (mean_residual - pr) / cap * (1.0 - progress);

    // Mild penalty for many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are reusable
    // by "nice" item sizes; odd/prime-ish residuals are dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res_mod10 = post_residual % 10;
    let res_mod5 = post_residual % 5;

    // Penalize residuals that fall in "awkward" classes (not multiples of 5/10).
    if res_mod10 == 0 {
        score -= 12.0;
    } else if res_mod5 == 0 {
        score -= 5.0;
    } else {
        score += (5 - res_mod5) as f64 * 2.0;
    }

    // Very small post-residual is excellent (tight fit): reward quadratically.
    if post_residual <= 10 {
        score -= (10 - post_residual) as f64 * 4.0;
    }

    // Integer-division threshold classes on post_residual: bucket quality.
    let bucket = post_residual / 20; // 0..5
    score += bucket as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (1.0 - slack / cap) * 8.0;
            if slack % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; mildly penalize leaving a mid-sized gap.
            if post_residual >= 10 && post_residual < 30 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fits = if post_residual > 0 { 1.0 } else { 0.0 };
        score += 30.0 * poor_fits;
        // Prefer new bin when mean residual of open bins is small (fragmented)
        // and the item is large relative to capacity.
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score -= frag * 20.0;
        score -= (item_size as f64 / cap) * 10.0;
        // Late in the stream, consolidating is better than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins: discourage further bin creation.
        score += open_bins_count as f64 * 0.8;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Slight preference for using fuller bins (small residual before placement).
    score += (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // future items are "dead". Penalize them super-linearly.
    let min_useful = 10u32; // smallest item size
    if post_residual > 0 && post_residual < min_useful {
        score += 200.0;
    } else if post_residual > 0 {
        // penalize small-but-nonzero gaps more than large usable gaps
        let gap = post_residual as f64;
        if gap < 30.0 {
            score += (30.0 - gap) * 2.0;
        }
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness reward: fraction of residual consumed by the item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 30.0;

    // New-bin candidate handling: opening a bin wastes capacity when an
    // open bin fits decently; add pressure proportional to open bins.
    if bin_residual == bin_capacity {
        // Only attractive if no good fit exists or many bins are open
        // with fragmented residuals.
        let pressure = open_bins_count as f64 * 1.5;
        let poor_fit_bonus = if post_residual_of_best_unknown() { 0.0 } else { 0.0 };
        let _ = poor_fit_bonus;
        score += 40.0 - pressure + mean_residual * 0.2;
        // lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size > 0 && next_item_size >= item_size {
            score -= next_item_size as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Slight preference for bins with residual below the mean (consolidate
    // small residuals, keep large residuals free).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Early in the stream, allow opening bins more freely to build a spread
    // of residual classes; late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + (post_residual - next_item_size) as f64;
        } else {
            // dead space for next item: penalize proportionally to mismatch
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins tighter than average residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize creating large unusable fragments (post_residual too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New bin candidate: prefer opening a new bin when current open bins are mostly full
    // (i.e., this call is for the empty bin, so bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // favor new bin if existing bins are tight
        if mean_residual < item_size as f64 * 1.2 {
            score -= 80.0;
        } else {
            score += 120.0 + 50.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization dominates).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else {
        // Quadratic penalty on leftover dead space.
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // Fit ratio: reward bins that are well-utilized after placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins fit: encourage spreading tight fits first.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    // (keeps a compatible companion space); otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when current residuals are large relative to the item or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_cost = 40.0 + open_bins_count as f64 * 3.0;
        // Attractive if mean residual is big (existing bins are too full / fragmented).
        let mean_bonus = (mean_residual - item_size as f64).max(0.0) * 0.5;
        score += open_cost - mean_bonus;
    } else {
        // Mild penalty per open bin to discourage fragmentation over consolidation.
        score += open_bins_count as f64 * 0.5;
    }

    // Time horizon: early in the stream be slightly more conservative about
    // tight fits (more items remain to use residuals); late, prioritize closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;

    // Coupling: penalize leaving residual just below common item sizes
    // (unusable gap) — approximate via distance to next item.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        let gap_waste = post_residual as f64 / next_item_size as f64;
        score += gap_waste * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Normalize post_residual and apply a non-linear polynomial coupling with stream progress.
    let x = pr / cap; // in [0,1]
    let poly = x * x * (1.0 - progress) + x * progress * progress;
    score += poly * cap * 0.5;

    // Penalize dead space more aggressively as the stream progresses (fewer chances to fill it).
    let dead = (pr * pr) / cap;
    score += dead * (0.2 + 0.8 * progress);

    // Reward tight fits: small post_residual relative to item size.
    let item = item_size as f64;
    if item > 0.0 {
        let tightness = pr / item;
        score -= (1.0 / (1.0 + tightness)) * 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: penalize if post_residual cannot fit the next item but almost could.
    let nxt = next_item_size as f64;
    if nxt > 0.0 && pr < nxt {
        let gap = (nxt - pr) / cap;
        score += gap * cap * 0.3;
    } else if nxt > 0.0 {
        // reward leaving space exactly usable by next item
        let match_bonus = 1.0 - ((pr - nxt) / cap);
        score -= match_bonus * 2.0;
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins near the mean to keep balance.
    let dev = (pr - mean_residual).abs();
    score += dev * 0.1;

    // New-bin candidate handling: make empty bin moderately attractive only for large items.
    if bin_residual == bin_capacity {
        let large = (item as f64 / cap).powi(2);
        score = cap as f64 * (0.6 - 0.4 * large) + (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "reusable" classes (multiples of 10, or large enough for typical items)
    // are rewarded; awkward slivers are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Integer-division thresholds on post_residual
    let class = pr / 10; // harmonic decade class
    let exact = pr % 10 == 0;

    // Reward residuals that are "useful": can host a mid-size future item
    if pr >= 50 {
        score -= 12.0 * frac; // roomy bin stays attractive
    } else if pr >= 20 {
        score -= 6.0;
        if exact { score -= 4.0; } // decade-aligned leftover is reusable
    } else if pr > 0 {
        // sliver: dead space risk
        score += 18.0 * (1.0 - frac);
        if pr < 10 { score += 10.0; }
    }

    // Perfect fit is best possible
    if pr == 0 {
        score -= 100.0;
    }

    // Modulo coupling with next item: if the NEXT item fits exactly into
    // this bin's post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            // harmonic pairing: (post_residual + next) hits a decade boundary
            if (pr + next_item_size) % 10 == 0 { score -= 8.0; }
        } else {
            // next item cannot follow here; slight penalty unless bin is nearly full
            if pr < 15 { score -= 5.0; } else { score += 4.0; }
        }
    }

    // Last-chance bin: using it avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins with low residual relative to fleet mean (compactness)
    score -= 0.5 * (mean_residual - pr as f64);

    // New-bin candidate: only attractive when no open bin is a decent host
    if bin_residual == bin_capacity {
        let baseline = 45.0
            + 10.0 * (open_bins_count as f64).ln()
            - 20.0 * (1.0 - (step_index as f64) / (total_items.max(1) as f64).max(1.0));
        // discourage new bins when a fitting bin exists with usable residual
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 5.0 {
            score = baseline + 25.0;
        } else {
            score = baseline;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for pairing in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are completely unusable -> heavy penalty proportional to wasted capacity.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // Small but potentially usable gaps: mild penalty to prefer tighter fits elsewhere.
        score += (20 - post_residual) as f64 * 0.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate implicitly via residual=capacity, but add pressure
    // so tight existing fits win over spreading out).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    }

    // Slight normalization against mean residual state: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits into the post residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - chain_gap / (bin_capacity as f64));
        // Perfect 2-item closure (item + next == residual).
        if chain_gap == 0.0 {
            score -= 500.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: penalize proportional to dead space.
        let dead = (post_residual as f64).min(next_item_size as f64);
        score += 8.0 * (dead / 100.0);
    }

    // Compare residual against mean residual: bins tighter than average
    // are more valuable to close out — placing here is good.
    score -= 5.0 * (mean_residual - post_residual as f64) / (bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals
    // across open bins are all large (fragmented state).
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual > 50.0 {
            score -= 20.0 * ((mean_residual - 50.0) / 50.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    // Mild penalty for very large items filling nearly-empty bins when
    // other bins exist (keep big items for tight residual matches).
    if item_size >= 70 && open_bins_count > 0 && bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * (bin_residual as f64);

    // Penalize small dead space that can't hold typical items (post_residual too small to be useful).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a sliver that the next item cannot use.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no good fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 25.0 - 20.0 * pressure;
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - t);
    }

    // Prefer packing into bins with larger residuals relative to the mean (balance spread).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins with low residual (best-fit bias) as stream progresses.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let fit = item_size as f64 / cap;
    let mut score = prn;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 0.35 * prn * prn * (1.0 - progress);
    score -= 0.5 * fit * (0.5 + prog3);
    score += 0.2 * (1.0 - fit) * (1.0 - fit) * (1.0 - prog2);

    // Reward near-perfect fits smoothly
    let tightness = 1.0 - prn;
    score -= 0.4 * tightness * tightness * tightness;

    // Lookahead coupling: penalize post-residual that cannot host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        let slack = ((pr - nx).max(0.0)) / cap;
        score -= 0.45 * fits_next * (0.3 + progress) + 0.15 * slack;
        score += 0.3 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 0.6 * (0.5 + 0.5 * progress);
    } else {
        score += 0.05 * (fitting_bins_count as f64).ln();
    }

    // Mean residual dispersion term
    score += 0.1 * ((mean_residual - pr) / cap).abs();

    // Penalize opening new bins when existing bins fit well
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score += 0.25 + 0.5 * waste * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    let decade = (pr / 10) as f64;

    // Reward post-residuals that are "usable" sizes (multiples of 10 / small remainders).
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        score += class * 1.5; // penalize awkward remainders
        if pr % 5 == 0 { score -= 8.0; }
        if pr >= 10 && pr <= 30 { score -= 10.0; } // highly reusable window
        if pr > 80 { score += 6.0; } // near-empty bin, wasteful placement
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - slack.min(25.0); // reward next-item compatibility
            if pr == next_item_size { score -= 30.0; }
        } else {
            score += 12.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize unless current bin is a poor host.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 20.0 * progress; // mildly prefer reusing bins early
        if item_size <= 40 { score += 10.0; } // small items should go into existing bins
        if next_item_size > 0 && next_item_size >= 60 && item_size >= 60 {
            score -= 15.0; // two big items pair better in fresh bins
        }
    }

    // Mean residual coupling: if this bin is far above mean residual, it's a good host.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Integer-division threshold on decade classes.
    if decade >= 5.0 && pr < bin_capacity {
        score += 4.0; // very large residuals after placement = wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible follow-up item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Dead space that cannot fit the lookahead item is risky.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness reward: fraction of the item's demand covered exactly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bonus: only one open bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but keep pressure mild so tight fits still dominate.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residuals below the mean (consolidate small gaps).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when no open bin fits well,
    // i.e. when the current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        // Base new-bin score: moderate, so good existing fits win.
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count <= 1 {
            // No real alternative: opening a fresh bin is fine.
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            // Large incoming item: a fresh bin preserves capacity for it.
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits the post_residual exactly/well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
        // Perfect chain: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: minimize leftover as much as possible
        score += 15.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leaving residual far above the mean residual (creating outliers)
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Early in the stream, be more willing to open bins (keeps flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, less when stream is late
        score += 8.0 + 12.0 * progress;
        // Opening a new bin is good if next item is large and no open bin chains well
        if next_item_size > 0 && next_item_size > post_residual && post_residual < item_size / 2 {
            score -= 6.0;
        }
    }

    // Slight preference to fill fuller bins when many bins are open
    score -= 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio.powf(3.0);

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect pairing: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += crowd * 0.5;

    // Compare bin residual to mean residual: prefer below-average-residual (fuller) bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and stream is early enough that fresh capacity pays off.
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.5;
        let early = progress < 0.4;
        if bad_fit && early {
            score -= 15.0;
        } else {
            score += 60.0;
        }
    }

    // Late stream: avoid spreading residual capacity; favor exact exhaustion.
    if progress > 0.8 && post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - progress) + prn * prn * prn * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64;
        let nx = next_item_size as f64;
        let unusable = (nx - gap).max(0.0) / cap;
        score += 18.0 * unusable * unusable;
        // Reward leaving exactly enough room for the lookahead item
        let fit_next = ((gap - nx).abs()) / cap;
        score -= 12.0 * (1.0 - fit_next.min(1.0)) * (1.0 - fit_next.min(1.0));
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // Pull toward mean residual: prefer bins near average fullness
    score += 6.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction does it occupy?
    let item_class = item_size / 10; // 1..=10 classes
    let post_class = post_residual / 10;

    // Reward placements whose post-residual falls into a "harmonically useful" class
    // (small residuals that later items can still fill: 0, 10, 20 are best).
    match post_residual {
        0 => score -= 30.0,                              // perfect closure
        1..=5 => score -= 12.0,                          // near-closure
        6..=19 => score += 8.0,                          // awkward dead space
        20..=29 => score -= 4.0,                         // fits a small item later
        30..=49 => score += 3.0,                         // moderate
        _ => {}                                          // large residual, naturally ok
    }

    // Modulo-10 harmony: post_residual divisible by 10 pairs well with class-sized items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // extra harmony bonus when both are in the same decade class
            if next_item_size / 10 == post_class {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: penalize small leftovers more
            if post_residual < next_item_size && post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (residual would be huge) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_open = mean_residual.max(0.0);
        // Opening a new bin is penalized proportionally to wasted space in open bins,
        // but rewarded when existing residuals are tiny (nothing fits well).
        score += 20.0 + waste_if_open * 0.3 - progress * 10.0;
        if item_class >= 8 {
            score -= 10.0; // big items pair naturally with fresh bins
        }
    }

    // Spread pressure: when many bins are open, tighten packing (prefer fuller bins).
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.05;

    // Small nudge toward bins whose residual is close in class to the item.
    if bin_residual / 10 == item_class && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Non-linear dead-space penalty: small-but-nonzero gaps are quadratic in badness.
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 900.0 / pr;
    }

    // Reward tight fits (post_residual near zero) with a strong subtraction.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Perfect fit relative to capacity: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading out; penalize candidates lightly as bins multiply.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: make it unattractive unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But late in the stream with high pressure, opening fresh is less penalized.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would leave the post residual in a dead zone, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean (tight bin),
    // placing here is efficient; if far above mean, it's a loose bin needing filling.
    let resid_diff = mean_residual - post_residual as f64;
    score += 0.15 * resid_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-perfect match: next item fits with minimal slack (<= 5).
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 - 8.0 * slack;
    }
    // Next item does NOT fit after this placement: penalize dead space.
    else if next_item_size > 0 {
        score += 30.0 + 0.5 * (next_item_size as f64);
    }

    // Penalize tiny unusable residuals (dead space below minimum item size).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (good fit consolidation).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Late in the stream, be more conservative about leaving large residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // New empty bin candidate: penalize opening a new bin unless it enables
    // an exact 2-step match or the item is very large relative to residuals.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 250.0;
        }
        if item_size >= 60 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later:
    // residuals below the minimum plausible item size (1..100 unknown,
    // so treat < 15 as near-dead) get a strong penalty.
    if post_residual < 15 {
        score += 25.0 * (15.0 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it, else we open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; mild penalty proportional to waste.
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (many items remain, keep bins flexible); late in stream, pack tightly.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // New-bin candidate: only attractive early or when all open bins fit poorly.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let open_pressure = if fitting_bins_count > 0 {
            fitting_bins_count as f64
        } else {
            0.0
        };
        let flexibility_need = (1.0 - progress) * 20.0;
        score += 15.0 + open_pressure * 2.0 - flexibility_need;
        // If no open bin is a good fit (large post_residual everywhere),
        // opening a fresh bin becomes more attractive.
        if mean_residual > 0.0 {
            let avg_waste = mean_residual - item_size as f64;
            if avg_waste > 30.0 {
                score -= (avg_waste - 30.0) * 0.5;
            }
        }
    }

    // Penalize bins whose residual deviates strongly from the mean residual
    // when the fit is mediocre (keeps bin-size diversity balanced).
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    if fit_quality < 0.5 {
        let dev = (mean_residual - bin_residual as f64).abs();
        score += dev * 0.05 * (1.0 - fit_quality);
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0 * fit_quality;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them quadratically.
    let w = 0.5 + 2.5 * progress;
    score += w * (post / cap) * (post / cap) * 20.0;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 6.0 * (1.0 - post / cap) * progress;

    // Penalize dead space relative to mean residual (smooth quadratic).
    score += 0.05 * (post - mean_residual) * (post - mean_residual) / cap;

    // Last-chance bin: strong smooth reward to use it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 0.5 * progress);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = post - nx;
        if gap >= 0.0 {
            score -= 4.0 * (gap / cap);
        } else {
            score += 2.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual dominates score).
    // Harmonic-class penalty: dead space in awkward modular classes is worse.
    let pr = post_residual;
    // Classify post_residual into harmonic buckets via integer division on 10.
    let bucket = pr / 10; // 0..=10
    // Small buckets (0..=2) are fine (near-exact or reusable slivers).
    // Buckets 3..=6 are "dead zone" sizes: too big to waste, too small for typical items.
    let dead_zone = if (3..=6).contains(&bucket) { 1.0 } else { 0.0 };
    score += dead_zone * 12.0;

    // Odd/awkward modulo classes on post_residual: residuals like %10 in {1,2,7,9}
    // are hard to fill with items of typical sizes; penalize mildly.
    let m = pr % 10;
    let awkward = if m == 0 { 0.0 } else if m <= 2 || m >= 8 { 1.5 } else { 0.5 };
    score += awkward;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 25.0; // perfect chaining
        } else if slack <= 5 {
            score -= 12.0;
        } else {
            score -= (pr as f64 - next_item_size as f64).min(10.0) * 0.6;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; residual becomes dead space -> penalize if residual is mid-sized.
        if pr > 0 && pr < 30 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced when many items remain or few open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut newbin = 18.0;
        newbin -= progress * 6.0;                 // later in stream: cheaper to open
        newbin += open_bins_count as f64 * 1.5;   // too many open bins: discourage
        // If mean residual across open bins is large, prefer reusing them.
        newbin += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
        // If next item is large, an empty bin is a good host.
        if next_item_size >= 60 {
            newbin -= 8.0;
        }
        score += newbin;
    }

    // Slight global preference for filling fuller bins (lower residual first).
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize unusable dead space: small non-zero gaps that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mild preference for fuller bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // New-bin candidate: make it less attractive unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual, but reward exact 2-step lookahead matches strongly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect chain: item + next item exactly fills the bin
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
        // Next item would be wasted if it can't fit anywhere: chain feasibility
        if next_item_size as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Penalize large unusable dead space (nothing small can use it)
    if post_residual < 10 && post_residual > 0 {
        score -= 10.0; // tiny dead space is fine, item is packed tightly
    }
    if post_residual > 60 {
        score += (post_residual as f64 - 60.0) * 0.5;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Relative to mean residual: bins with residual below mean are "dying" — use them
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // Penalize opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional stream progression (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Penalize tiny dead space that nothing (>=10 typical, but be safe for 1..100) can use
    if post_residual > 0 {
        let min_useful = if next_item_size > 0 { next_item_size.min(15) } else { 15 };
        if (post_residual as u32) < min_useful {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // New-bin candidate handling: make it attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a decent existing fit
        score = bin_capacity as f64 - 5.0;
        // Early in the stream, opening bins is cheap and helps spread load
        score -= 10.0 * (1.0 - progress);
        // If many bins already fit the item, discourage opening another
        if fitting_bins_count > 0 {
            score += 6.0 * (fitting_bins_count as f64).sqrt();
        }
        // If the next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild global coupling: prefer bins below mean residual (tighter bins) early on
    score += 0.05 * (mean_residual - bin_residual as f64) * (1.0 - progress);

    // Slight preference for fuller bins overall
    score -= 0.03 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual (tight fit), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Smooth dead-space penalty: residuals that are too small to host the
    // minimum plausible item are wasted; use a smooth saturating term.
    let unusable = (10.0 - post).max(0.0) / 10.0;
    score += 40.0 * unusable * unusable;

    // Reward tight fits more strongly as the stream progresses
    // (consolidation matters more late in the stream).
    score -= 20.0 * (1.0 - post / cap) * progress * progress;

    // Penalize opening a new bin when existing bins can fit the item,
    // with strength decaying as the stream progresses (early on, spreading
    // out is safer; late, we consolidate).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let fit_pressure = (fitting_bins_count.max(1) as f64).ln();
        score += (30.0 + item * 0.5) * (1.0 - progress) / fit_pressure;
    } else {
        // Slight reward for using an existing bin, stronger when it's the
        // last fitting bin (avoid opening a bin for nothing).
        if fitting_bins_count == 1 {
            score -= 15.0 * (1.0 - progress);
        }
        // Reward bins whose residual is close to the mean (keeps the pool balanced),
        // with a smooth quadratic coupling.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev * dev;
    }

    // Lookahead coupling: if the next item fits exactly into the projected
    // post_residual, reward this placement (perfect chaining).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 12.0 * (-gap / 15.0).exp();
        // Penalize post_residuals that are just barely too small for the next item.
        if post < next_item_size as f64 {
            score += 6.0 * (next_item_size as f64 - post) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: which capacity-fraction bucket does post_residual fall in?
    // Classes of 10 units: 0 = perfect fit, small leftovers are more reusable.
    let class = post_residual / 10;
    match class {
        0 => score -= 40.0,                       // perfect fit: huge reward
        1 => score -= 25.0,                       // leftover <= 19: fits small items
        2 => score -= 15.0,                       // leftover <= 29
        3 => score -= 10.0,                       // leftover <= 39
        4 | 5 => score -= 5.0,                    // mid-range leftover
        6 | 7 | 8 => score += 5.0,                // large leftover: wasteful placement
        _ => score += 10.0,                       // nearly empty bin used for a big item
    }

    // Harmonic coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin's remainder.
            let chain_class = (post_residual - next_item_size) / 10;
            score -= 8.0 + (3 - chain_class.min(3)) as f64 * 4.0;
        } else {
            // Next item cannot use the leftover; penalize proportionally to mismatch.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.15;
            // If next item is large and leftover is a dead class, extra penalty.
            if next_item_size > 50 && post_residual < 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin's raw score is its capacity (100).
    // Only prefer opening a new bin when all open fits would leave bad harmonic classes.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or with many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 - 10.0 * progress;
        if open_bins_count > 8 {
            score -= 5.0;
        }
        // If next item is small, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 4.0;
        }
    }

    // Mild tie-break toward bins tighter than the mean residual (denser bins first).
    let mean_gap = mean_residual - bin_residual as f64;
    score += mean_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that can't fit even the smallest
    // future item (<= 10 assumed, but cap by next_item_size when known) are
    // effectively wasted. Penalize heavily.
    let min_future = if next_item_size > 0 { next_item_size.min(10) as f64 } else { 10.0 };
    if post > 0.0 && post < min_future {
        score += 25.0 + 2.0 * (min_future - post);
    }

    // Small-but-usable gaps are mildly risky; large residuals are fine.
    if post > 0.0 && post < 20.0 {
        score += 6.0 * (1.0 - post / 20.0);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 40.0 / (1.0 + post * post * 0.01);

    // Reward using a bin whose residual was large (consolidation).
    score -= 0.05 * bin_residual as f64;

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but allow opening a new bin when few are open and fit is poor.
    score += 1.5 * open_bins_count as f64 * (post / cap);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size as f64 <= post {
        score -= 5.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * open_bins_count as f64;
        if post < 30.0 {
            score -= 10.0; // opening fresh bin still leaves usable space
        }
    }

    // Slight time decay: later in stream, be greedier about tight fits.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * t * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step fill: strong reward
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits after this one: scale reward by closeness
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted-looking residuals
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize small dead space (< 10, unusable for min-size items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if residual stays large (fresh capacity)
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: opening new bins is cheap; late: prefer filling
        score += 20.0 * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
        // penalize new bin if next item could pair with current in an open bin
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    // Prefer bins tighter than the mean (better fits), avoid loose bins
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later
    // (typical items are >= 10, so post_residual < 10 is likely waste).
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count <= 3 {
        score -= 5.0 / fitting_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize large leftovers
            // that will strand space.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in the stream, pack tightly into
    // existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early, penalize later.
        score += 15.0 * progress;
        // Opening a new bin is fine if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If many bins are open with slack, discourage spreading.
        score += 0.5 * open_bins_count as f64;
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 8.0 * progress;
    }

    // Global slack coupling: if mean residual is high, prefer bins below
    // mean (balance usage); if low, prefer tight packing.
    if mean_residual > 0.0 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
        score -= 2.0 / (1.0 + mean_residual / bin_capacity as f64);
    }

    // Slight preference for filling larger items into emptier bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post residual); late in the stream,
    // slightly tolerate larger residuals to keep bins closable.
    let coupling = x * x * (1.0 - progress) * 30.0 + x * progress * 10.0;
    score += coupling;

    // Smooth penalty for dead space that cannot fit the next item (lookahead),
    // scaled by how "wasted" the gap is.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (post - next_item_size as f64) / cap;
        if gap > 0.0 {
            score += gap * gap * 40.0 * (1.0 - nx);
        }
        // Reward leaving exactly room for the next item (perfect chaining).
        let chain = (post - next_item_size as f64).abs() / cap;
        score -= (1.0 - chain) * (1.0 - chain) * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - x);
    }

    // Penalize spreading residual away from the mean (imbalance), smooth quadratic.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 15.0;

    // New-bin candidate: mild base penalty so open bins with decent fits win,
    // but allow opening a new bin when all fits would be very poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If the item barely fits anywhere (tight fit nowhere), new bin is attractive:
        // expressed smoothly via how small the item is relative to capacity.
        score -= (1.0 - item_size as f64 / cap) * 10.0;
    }

    // Slight preference for filling bins more fully as stream progresses.
    score -= progress * (1.0 - x) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish baseline so we only open a new bin
    // when no open bin offers a genuinely good fit.
    if bin_residual == bin_capacity {
        score = 35.0 + post_residual as f64;
        // Late in the stream, slightly discourage spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If several bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 8.0;
        }
        return score;
    }

    // Dead-space penalty: residuals 1..=9 are nearly unusable (min item is small).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic class logic: reward post_residuals in "friendly" classes.
    // Residuals that are multiples of 10 (or near) tend to pair with common sizes.
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,                       // perfect decade class
        5 => score -= 6.0,                        // half-class
        1 | 9 => score += 10.0,                   // awkward edge class
        _ => {}
    }

    // Integer-division threshold: residual >= 2 * next_item_size is ideal
    // because the next item can still slot in comfortably.
    if next_item_size > 0 {
        if post_residual >= 2 * next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Next item cannot fit here; residual is likely dead weight.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a pointless new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight preference for filling fuller bins (low residual before placement).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=12) are heavily penalized
    // since they are unlikely to be filled by future items.
    let pr = post_residual as f64;
    if post_residual >= 1 && post_residual <= 12 {
        score += (13.0 - pr) * 4.0; // up to +48 for a 1-unit gap
    } else if post_residual > 12 && post_residual < 30.0 {
        // moderate dead space: mild penalty decaying with size
        score += (30.0 - pr) * 0.35;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Reward near-tight fits: small post_residual relative to item_size
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    // Open-bin pressure: when many bins are open, discourage opening new bins.
    // The new-bin candidate has bin_residual == bin_capacity, so penalize high
    // residuals proportionally to open_bins_count.
    let pressure = open_bins_count as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * pressure * 1.2;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post_residual, reward keeping this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize leaving a gap that blocks it
        score += (post_residual as f64) * 0.15;
    }

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for placing into existing bins as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits snugly in the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward tight chain fits heavily.
            score -= 30.0 + 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize large post residuals that strand space.
            score += 0.15 * post_residual as f64 * (0.5 + progress);
        }
        // Bonus for exact chain match (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the fleet average.
    score += 2.0 * (post_residual as f64 - mean_residual);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fill, small dead space
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * open_bins_count as f64;
        // But allow new bin early in stream or when item is huge relative to residuals.
        score -= 30.0 * progress;
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space that nothing can use later
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead);
        }
        // Mild reward for leaving room close to a typical item size
        score -= 3.0 * (-(dead - 25.0f64).abs() / 15.0).exp();
    }

    // Tightness: prefer bins that were already fairly full before placement
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= 25.0 * tightness;

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits in post_residual, reward; if not, penalize
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 20.0;
        } else {
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.3 * gap.min(80.0);
        }
    }

    // Global state: many open bins with slack -> consolidate; few bins -> spreading ok
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * (0.5 + 0.5 * progress);
    score -= 0.4 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: make it unattractive unless remaining open bins are very tight
    if bin_residual == bin_capacity {
        let avg_tight = 1.0 - mean_residual / cap;
        // open new bin only if existing bins are nearly full on average or none fit well
        let desperation = if fitting_bins_count == 0 { 1.0 } else { avg_tight.powf(2.0) };
        score = cap + 30.0 - 90.0 * desperation + 5.0 * open_f * (1.0 - avg_tight);
        if post_residual == 0 { score -= 200.0; } // unreachable but safe
    }

    // Small time-based jitter-free modulation
    score += 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with smooth polynomial shaping.
    let mut score = pr_norm * (1.0 + 0.8 * pr_norm * (1.0 - pr_norm));

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers; late, penalize them more.
    score *= 1.0 + 1.2 * progress * pr_norm * pr_norm;

    // Reward tight fits (small post residual) increasingly over time.
    score -= 0.5 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize creating dead space that no plausible item can use:
    // post_residual below typical minimum item size is wasted.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 0.15 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let slack = (pr - next) / cap;
            score -= 0.6 * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            // Next item won't fit here; slight penalty scaled by mismatch.
            score += 0.2 * ((next - pr) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 0.8 + 0.5 * progress;
    }

    // Context: compare this bin's residual to mean residual across open bins.
    score += 0.1 * (mean_residual - bin_residual as f64) / cap;

    // Mildly discourage proliferating many open bins early.
    score += 0.05 * (open_bins_count as f64 / (total_items as f64 + 1.0)) * (1.0 - progress);

    // New-bin candidate: keep it neutral-to-slightly-poor unless leftovers are bad.
    if bin_residual == bin_capacity {
        score += 0.3 - 0.2 * progress;
        // Prefer a new bin if all current fits would leave tiny unusable gaps.
        if pr < 10.0 {
            score -= 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space is worst when it falls
    // into "small residue" classes that nothing can ever fill.
    let capacity_frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit reward: post_residual in {0} is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Small unusable residues are heavily penalized (dead space).
        if post_residual <= 10 {
            score += 25.0;
        } else if post_residual <= 20 {
            score += 10.0;
        } else if post_residual <= 30 {
            score += 3.0;
        }

        // Harmonic residue classes: residues that are multiples of common item
        // sizes (10, 20, 25, 50) are "fillable" classes -> reward them.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }
        if post_residual % 50 == 0 {
            score -= 5.0;
        }
        // Prime-ish / odd residues tend to become dead space.
        if post_residual % 2 == 1 && post_residual < 40 {
            score += 4.0;
        }
    }

    // Integer-division thresholds: how many "half-capacity chunks" remain.
    let half_chunks = post_residual / (bin_capacity / 2);
    if half_chunks >= 1 {
        score -= 6.0 * half_chunks as f64;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual,
    // penalize if next item cannot fit (bin becomes useless for lookahead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Prefer residues that leave a good follow-up fit.
            let follow = post_residual - next_item_size;
            if follow <= 10 {
                score -= 12.0;
            } else if follow % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: mild penalty scaled by gap.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins are
    // genuinely poor fits (large item vs tight residuals).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Bias toward new bins early (more future items to fill them),
        // and when the current item is large relative to mean residual.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 12.0 - 10.0 * progress - 18.0 * item_frac - 0.3 * mean_gap;
        // Never open a new bin for a tiny item when plenty of space exists.
        if item_size <= 20 && mean_residual > 60.0 {
            score += 30.0;
        }
    }

    // Mild pressure toward consolidating bins.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins already below mean residual (tighter bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful later are costly.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Favor bins whose residual matches next item size (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size as u32;
        score -= 20.0 * (1.0 - (gap as f64) / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This bin becomes dead after placement if next item can't use it.
        score += 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening existing bins.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0));
    score += 25.0 * pressure;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual spread.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    // Slight preference for tighter bins overall.
    score -= 10.0 * (1.0 - (bin_residual as f64) / bin_capacity as f64);

    // Mild time-decay so early stream tolerates exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves more slack — mild penalty proportional to leftover
            score += 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit in this bin after placement — penalize wasted space
            score += 0.5 * next_item_size as f64;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.1 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus dead-space of current item's poor fit elsewhere
        score += 50.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative, new bin is fine
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    score -= 30.0 * fit_ratio;

    // Penalize leaving dead space that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last chance: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: early on, be more willing to open new bins (explore);
    // later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more as stream progresses
        score += 20.0 + 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > cap * 0.5 {
            score -= 15.0; // new bin good for large follow-up
        }
    } else {
        // Existing bin: slight bonus late in stream
        score -= 10.0 * progress;
    }

    // Global state: if many open bins with large mean residual, encourage filling them
    if mean_residual > cap * 0.4 && bin_residual > item_size {
        score -= 5.0 + mean_residual * 0.05;
    }

    // Penalize opening bins when many already open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    // Base: tight fit rewarded, but with non-linear (quadratic/cubic) shaping.
    let mut score = pr_norm * (1.0 + pr_norm * pr_norm);

    // Smooth interaction: waste matters more as stream progresses.
    score += progress * pr_norm * pr_norm * 2.0;

    // Penalize leaving residual that cannot fit the lookahead item (smooth gate).
    let fits_next = (next_norm <= pr_norm) as i32 as f64;
    let gap = (next_norm - pr_norm).max(0.0);
    score -= fits_next * 0.8 * (1.0 - progress);
    score += gap * 1.5;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many are open and mean residual is high.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let mean_norm = mean_residual / cap;
    score += new_bin * (0.5 + mean_norm * 2.0 + open_bins_count as f64 * 0.05 * progress);

    // Prefer filling bins with larger items (smooth coupling).
    score -= item_norm * 0.6;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in a "useful"
    // residue class (multiples of 10, and mid-range 30..60) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: huge reward
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward remainder: dead-space penalty
    };
    score += class_bonus;

    // Integer-division threshold: post_residual bucketed by capacity fraction.
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score += 25.0; // tiny sliver: nearly unusable
    } else if frac < 0.30 {
        score += 5.0;
    } else if frac <= 0.60 {
        score -= 10.0; // sweet spot: fits a wide range of future items
    }

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 14.0 + 0.15 * slack.min(40.0);
            // harmonic class of the post-post residual
            let pp = pr - next_item_size;
            if pp % 10 == 0 { score -= 6.0; }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if it beats filling an existing bin.
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~half a wasted bin on average.
        score += 35.0 + mean_residual * 0.3;
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 15.0;
        }
    }

    // Mild pressure to prefer bins below mean residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Slight preference for already-open crowded bins when many bins exist.
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count.min(20) as f64) * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1),
    // but more meaningfully, gaps below ~10 are nearly dead space in practice.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0;
    }

    // Non-linear waste penalty: squared residual scaled down so exact fits dominate.
    score += (pr * pr) / (bin_capacity as f64 * 2.0);

    // Open bins pressure: discourage spreading when many bins are open,
    // encourage filling existing bins; but encourage new bin when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln() + 1.0;
    score += bin_pressure * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 5.0;
    } else if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        // Next item won't fit here; slight penalty if we leave a large awkward gap.
        score += pr * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (i.e., we are closing out emptier bins), keep full bins attractive.
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.4;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in the stream or when the
        // current item would leave a terrible gap in any existing bin.
        let terrible_gap = pr > 0.0 && pr < dead_threshold;
        if !terrible_gap && progress < 0.85 {
            score += 25.0; // discourage new bins early/mid stream
        } else {
            score += 8.0; // mild discouragement otherwise
        }
    }

    // Reward tight fits explicitly (post_residual near zero).
    if pr == 0.0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - lookahead_waste / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 300.0; // perfect 2-chain
            }
        } else {
            // next item cannot fit here; penalize proportionally to dead space
            score += 0.5 * post_residual as f64;
        }
    } else {
        // last item: minimize post residual
        score += 0.1 * post_residual as f64;
    }

    // Penalize large post residuals relative to mean residual (dead space)
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 80.0 + 0.5 * item_size as f64;
        if fitting_bins_count > 0 && post_residual < next_item_size && next_item_size > 0 {
            score += 100.0; // opening new bin would break a potential chain
        }
    }

    // Mild preference for tighter bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a residual too small for the next item (dead space).
            let waste = post_residual as f64 / next_item_size.max(1) as f64;
            score += 6.0 * (1.0 - waste.min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open but this fit is loose: consolidate.
    if fitting_bins_count > 1 && post_residual > 30 {
        score += 4.0;
    }

    // Global state coupling: when mean residual is low, prefer using existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - mean_residual / bin_capacity as f64) * (0.5 + progress);

    // New-bin candidate: baseline so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 65.0 + 20.0 * progress - 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative, must open
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: squared normalized residual
    let norm_post = post / cap;
    score += 18.0 * norm_post * norm_post * cap;

    // Smooth stream-progress coupling: later in the stream, tighten more
    score -= 12.0 * t * (1.0 - norm_post) * (1.0 - norm_post);

    // Reward near-perfect fits with cubic term
    score -= 25.0 * (1.0 - norm_post).powi(3);

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 15.0 * last_chance;

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (post - nx).max(0.0) / cap;
        score -= 10.0 * usable;
        // reward leaving exactly enough room for next item
        let gap = (post - nx).abs() / cap;
        score += 8.0 * gap * gap;
    }

    // New-bin candidate: penalize opening new bins unless residual waste would be large
    if bin_residual == bin_capacity {
        let waste_avoided = (mean_residual - post).max(0.0);
        score += 30.0 - 20.0 * waste_avoided / cap;
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild pressure to prefer bins with low residual relative to mean
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions (dead zones where few item sizes can still fit).
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr > 0 {
        // Penalize leftovers that fall into "unusable" harmonic classes.
        if pr < quarter / 2 {
            score += 40.0; // tiny sliver, nearly dead space
        } else if pr < quarter {
            score += 12.0;
        } else if pr < half / 2 {
            score += 4.0;
        } else if pr < half {
            score -= 6.0; // still roomy, flexible
        } else {
            score -= 3.0;
        }
    }

    // Modulo-class coupling: does post_residual pair with the next item
    // to form an exact or near-exact fill? Reward such harmonic pairs.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0; // next item exactly fills this bin
        } else if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap < quarter / 2 {
                score -= 60.0; // near-exact harmonic pairing
            } else {
                score -= (gap as f64).sqrt() * 2.0;
            }
        } else {
            // Next item cannot fit here; penalize slightly, scaled by
            // how badly it misses (modular proximity of sizes).
            let miss = next_item_size - pr;
            score += (miss as f64).ln().max(1.0) * 8.0;
        }
    }

    // Integer-division threshold on residual: bins whose residual is a
    // multiple of small harmonic units are more reusable.
    if pr > 0 && pr % 10 == 0 {
        score -= 10.0;
    }
    if pr > 0 && pr % 5 == 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual waste relative to capacity) or late in the stream.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.5 + fragmentation * 100.0 + progress * 20.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing else fits: must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item: fresh bin useful
        }
    }

    // Mild preference for tighter bins among equally good fits.
    score += (bin_residual as f64) * 0.05;

    // Slight penalty for spreading across many bins early on.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Pressure on number of open bins: prefer filling existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: allow opening a new bin only when no open bin
    // offers a good fit (residual much larger than item) and few bins are open.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 20.0 && open_bins_count < 4 {
            score -= 15.0; // opening fresh bin is attractive
        } else {
            score += 12.0; // prefer existing bins otherwise
        }
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item barely misses the post-residual, penalize leaving that gap.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // Early in the stream, be slightly more willing to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: perfect chaining bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 150.0 - gap as f64 * 5.0;
            } else {
                // Penalize leaving a large gap that next item can't close.
                score += gap as f64 * 0.5;
            }
        } else {
            // Next item doesn't fit after placement: penalize.
            let overshoot = next_item_size - post_residual;
            score += overshoot as f64 * 1.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the tightest (already via post_residual).
        score += 5.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 {
            (next_item_size as f64 - post_residual as f64).max(0.0)
        } else {
            0.0
        };
        // Base penalty keeps open bins preferred; reduce when item is large
        // relative to residuals (poor fit everywhere).
        score = 120.0 - desperation * 0.8 - (item_size as f64 - 50.0).max(0.0) * 0.3;
        if fitting_bins_count == 1 {
            score += 60.0; // discourage skipping the only fitting bin
        }
    }

    // Mild late-stream pressure to fill existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * (fit_ratio - 0.85) / 0.15;
    }

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are fine (perfect fit region)
    } else if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.15;
    }

    // Lookahead: bonus if the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 12.0 * next_fit;
        } else if next_item_size <= bin_residual {
            // Next item could have fit here before we consumed space; mild penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins unless current open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0).max(1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 20.0 + 10.0 * progress;
        if mean_residual > 40.0 { new_bin_penalty += 15.0; }
        if next_item_size > 0 && next_item_size > mean_residual { new_bin_penalty -= 8.0; }
        if crowd < 3.0 { new_bin_penalty += 10.0 * (3.0 - crowd); }
        score += new_bin_penalty;
    }

    // Mild preference for bins tighter than the fleet average.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    let item_f = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: penalize large residuals more as stream progresses
    score += 40.0 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with non-linear term
    score -= 15.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - pr);

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / bin_capacity as f64;
        let gap = (pr - nxt).abs();
        score += 10.0 * gap * gap;
        if pr >= nxt && pr - nxt < 0.15 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - item_f);
    }

    // Penalize spreading across many open bins when mean residual is high
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * mean_residual / bin_capacity as f64;

    // New-bin candidate: prefer it only when existing fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let rclass = post_residual % 10;
    // Residuals that are "usable" harmonic slots (multiples of common item sizes)
    let usable = (post_residual % 10 == 0) || (post_residual >= 10 && post_residual % 5 == 0);
    if !usable {
        score += 6.0 + (rclass as f64) * 0.7; // penalize dead space in odd classes
    } else {
        score -= 3.0;
    }

    // Integer division thresholds: how many "typical" items (size ~20) still fit
    let fits20 = post_residual / 20;
    score -= fits20 as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item won't fit here; penalize small leftover more
            if post_residual < 10 {
                score += 12.0; // near-wasted bin
            }
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score,
    // discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        score = 45.0 - (open_bins_count as f64) * 0.5 - mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Phase of stream: early, prefer compacting; late, allow spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Tie-break toward filling bins closer to mean residual (balance)
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be useful
    // are heavily penalized. Treat gaps < 10 (min item size) as total waste.
    if post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual <= 20 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual <= 35 {
        score += 8.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize using bins when many are already open,
    // encouraging consolidation rather than spreading.
    score += 1.5 * open_bins_count as f64;

    // Last chance bin: strongly favor filling the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when item is large and no open bin
    // would leave a decent usable residual.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score -= 70.0 * big_item; // opening fresh bin for huge item beats dead space
        } else {
            score += 30.0; // discourage opening new bins for loose fits
        }
    }

    // Lookahead: favor bins whose residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0; // blocks next item
        }
    }

    // Slight late-stream consolidation bias.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Leftover can host the next item: mild reward, scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover too small for the next item: penalize dead space,
            // worse when the dead space is large relative to the next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize residual far below the mean residual (wasting a roomy bin on a small item).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // Mild penalty for opening a new bin when other bins could fit the item.
    if bin_residual == bin_capacity {
        score += 50.0;
        // New bin is acceptable if no open bin has room for the next item either
        // and this bin would end with a useful residual for the future.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Late in the stream, tighten up: prefer minimizing residual even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residual, non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // Mild penalty per competing bin to break ties toward fuller bins.
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Perfect / near-perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: if the next item could fit into the post-residual of this bin,
    // reward the placement (chaining items into the same bin).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if the next item also fits tightly after this placement.
            let chain_residual = post_residual - next_item_size;
            if chain_residual < 10 {
                score -= 15.0;
            }
        } else {
            // Penalize leaving a gap just slightly smaller than the next item
            // (wasted near-miss space).
            let miss = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            if miss < 0.15 {
                score += 10.0 * (1.0 - miss / 0.15);
            }
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Large items justify a fresh bin (avoids fragmenting existing bins).
        score -= 0.35 * item_size as f64;
        // If the next item is large too, opening a new bin now may be fine.
        if next_item_size >= 60 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Global state coupling: when mean residual across open bins is small
    // (bins are nearly full), prefer squeezing into existing bins.
    score += 0.15 * mean_residual;

    // Penalize creating dead space relative to the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: minimize leftover, with non-linear (quadratic) penalty on waste.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of waste with stream progress: waste becomes more
    // costly later in the stream (less time to refill gaps).
    score += 6.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits (small post residual) smoothly via inverse coupling.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 4.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward; if post residual is too small for the next item, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Penalize spreading across many bins when mean residual is high
    // (encourage consolidating into fuller bins).
    score += 1.5 * (mean_residual - pr).abs() / cap;

    // Mild bonus for using bins in crowded states.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let post_mod = post_residual % 10;
    // Small odd residues (1,3,7,9) are "dead" — no item >=10 can ever fill them
    if post_mod == 1 || post_mod == 3 || post_mod == 7 || post_mod == 9 {
        score += 12.0;
    } else if post_mod == 5 {
        // half-decade leftover, moderately awkward
        score += 5.0;
    }

    // Integer-division thresholds on post_residual: tiny leftovers are fine (well-packed)
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Reward bins whose residual sits in "harmonic" classes matching common item sizes
    // Residuals divisible by 4 or 5 pair well with many sizes
    if post_residual % 4 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            let gap_mod = gap % 10;
            if gap_mod == 1 || gap_mod == 3 || gap_mod == 7 || gap_mod == 9 {
                score += 4.0; // chain leaves dead space
            } else {
                score -= gap as f64 * 0.5; // prefer chains minimizing gap
            }
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // With many fitting bins, prefer tighter fits (handled by post_residual base)
        score += (fitting_bins_count as f64 - 1.0).min(6.0) * 1.5;
    }

    // New-bin candidate handling: empty bin has residual == capacity
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful early in stream or when bins are few
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 30.0 * (1.0 - progress);
        // But if the item is large and would leave a badly-classed residual in any bin,
        // new bin becomes relatively attractive
        let new_post = bin_capacity - item_size;
        let new_mod = new_post % 10;
        if new_mod == 0 || new_mod == 2 || new_mod == 4 || new_mod == 6 || new_mod == 8 {
            score -= 15.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Prefer bins below mean residual (tighter than average) slightly
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Stream-phase modulation: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Modulo coupling between item_size and bin residual classes
    let res_mod = bin_residual % 10;
    let item_mod = item_size % 10;
    if res_mod == item_mod {
        score -= 6.0; // exact decade alignment
    } else if (res_mod as i64 - item_mod as i64).abs() <= 2 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals too small to be useful
    // by the next item (lookahead-aware unusable gap).
    let pr = post_residual as f64;
    if post_residual > 0 {
        if next_item_size > 0 && (next_item_size as f64) > pr {
            // Gap cannot host the lookahead item: dead space penalty.
            score += 12.0 + 0.35 * pr;
        }
        // Very tiny slivers are almost always dead space.
        if post_residual <= 3 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: prefer bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing
    // ones; when few bins are open, opening a new bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    // New-bin candidate: make the empty bin attractive only when the item is
    // large relative to capacity (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 6.0 * large_item * large_item;
        score += 4.0 * (1.0 - large_item);
    }

    // Mild alignment with mean residual: bins far below mean residual are
    // already tight; prefer them slightly.
    score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strong bonus when the item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it matches.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 + 0.5 * (post_residual as f64) - 0.4 * slack;
        } else {
            // Next item does NOT fit: penalize leaving residual that wastes capacity.
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 100.0;
    }

    // Reward bins tighter than the mean residual (good fits), penalize loose bins.
    score += 0.8 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If the next item is small enough to coexist with this item in a fresh bin,
        // opening a new bin becomes more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Late in the stream: consolidate, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * ((post_residual as f64) / bin_capacity as f64);

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 30.0 / (1.0 + tightness);

    // Penalize creating dead space that can't fit typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score -= 5.0; // usable for small future items
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if next_item_size > bin_capacity as u32 - post_residual {
            // next item can't fit here anyway; mild bonus for using this bin now
            score -= 5.0;
        }
        // if next item is large, prefer to keep big-residual bins free
        if next_item_size > 50 && post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // last item: maximize fill
        score -= 50.0;
    }

    // Last chance: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when existing fits are poor (large post_residual)
        // and many bins are already open (fragmentation)
        let poor_fit_penalty = if post_residual as f64 > mean_residual * 0.9 { 0.0 } else { 150.0 };
        score += 80.0 - poor_fit_penalty;
        // Late in stream, avoid opening new bins if any fit exists
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
        // Many open bins: discourage adding another unless needed
        score += (open_bins_count as f64).sqrt() * 8.0;
    }

    // Global state: when mean residual is high, prefer bins above mean (consolidate)
    if !is_new_bin {
        let diff = post_residual as f64 - mean_residual;
        score += 0.3 * diff;
        // More open bins -> encourage filling existing bins
        score -= 0.05 * open_bins_count as f64 * (bin_residual as f64 - post_residual as f64);
    }

    // Time horizon: early stream, be picky; late stream, just fill
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;
    let post = post_residual as f64;

    // Tightness: fraction of bin consumed by this placement (smooth, in [0,1])
    let fill = item / cap;
    // Normalized post residual (0 = perfect fit, 1 = empty bin)
    let post_norm = post / cap;

    // Reward tight fits more aggressively as the stream progresses.
    let tightness_reward = fill * fill * (1.0 + 2.5 * progress) * 30.0;
    score -= tightness_reward;

    // Penalize small-but-nonzero dead space quadratically (unusable slivers),
    // scaled by how many alternative bins exist.
    let dead_penalty = (post_norm * (1.0 - post_norm)).max(0.0);
    score += (1.0 - dead_penalty) * post_norm * post_norm * (10.0 + 8.0 * (fitting_bins_count as f64).ln().max(0.0));

    // Lookahead coupling: if the next item fits the post residual exactly-ish,
    // reward this bin (chaining placements).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            let chain = (1.0 - gap / cap).max(0.0);
            score -= 25.0 * chain * chain * (0.5 + progress);
        } else {
            // Next item cannot fit here: mild penalty proportional to overflow gap.
            score += 5.0 * (gap / cap).min(1.0);
        }
    }

    // Penalize bins whose residual deviates from the mean residual (outliers),
    // with a smooth cubic coupling on progress.
    let dev = (resid - mean_residual).abs() / cap;
    score += dev * dev * dev * 12.0 * (0.3 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoids opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate handling: an empty bin gets a baseline cost that shrinks
    // with progress (late in the stream, opening new bins is cheaper than waste).
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress) - 10.0 * post_norm * 0.0;
        // Extra penalty when other bins fit the item comfortably.
        if fitting_bins_count > 0 {
            score += 6.0 * (1.0 - fill);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common item
    // granularities (5, 10, 20) are more likely to be reusable later.
    let r = post_residual;
    if r == 0 {
        score -= 25.0; // perfect fit: zero dead space
    } else if r % 10 == 0 {
        score -= 8.0;
    } else if r % 5 == 0 {
        score -= 4.0;
    } else if r % 20 == 0 {
        score -= 10.0;
    }

    // Lookahead chaining: if the next item fits exactly or well in the residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 20.0;
        } else if next_item_size < r {
            let slack = r - next_item_size;
            // harmonic class of the slack after the lookahead item
            if slack % 10 == 0 {
                score -= 10.0;
            } else if slack % 5 == 0 {
                score -= 5.0;
            }
            // small slack is good, but tiny (<10) slack is dead space
            if slack < 10 {
                score += (10 - slack) as f64 * 0.5;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 3.0;
        }
    }

    // Integer-division threshold on post_residual: classify into usable bands.
    let band = r / 10; // 0..10
    score += band as f64 * 1.5; // larger leftover costs more, linearized by band

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has high raw residual; make it
    // attractive only when current open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // open a new bin when existing bins are nearly full / fragmented
        if avg < 15.0 && next_item_size > 0 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for leaving residuals in awkward ranges (11..19, 21..29)
    if (11..=19).contains(&r) {
        score += 6.0;
    } else if (21..=29).contains(&r) {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more aggressively than large leftovers.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny gap: almost certainly dead space
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 30 {
            score += 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Prefer bins whose residual matches or exceeds the next item (lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward when the leftover exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover too small for the next item: mild penalty proportional to tightness.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 4.0 + 20.0;
        // Late in the stream, opening new bins is especially wasteful.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 30.0;
        }
    }

    // Prefer filling bins that are already relatively full (below-mean residual).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += 0.6 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: item + next item fills bin exactly
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item cannot fit here: mild penalty scaled by how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.4 * miss;
        }
    }

    // Relative to mean residual: bins with less residual than average are more "committed"
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating very small dead space (unusable slivers) unless next item fills it
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 30.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins (empty bin gets a bonus)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into existing bins
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for likely future items.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 6.0 * (next_item_size as f64) / cap;
        } else if next_item_size > 0 {
            score -= 4.0;
        }
        // Very small slivers are nearly useless.
        if pr < 10.0 {
            score += 12.0 * (10.0 - pr);
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    // Many alternatives: mild penalty to encourage spreading.
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Time horizon: early in the stream, be conservative (favor new bins
    // when fit is bad); late in the stream, pack aggressively into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let urgency = 10.0 * progress;
    score -= urgency * tightness;

    // Global state coupling: if mean residual across open bins is high,
    // there is slack available — prefer filling the emptiest-fit less harshly.
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large post_residual relative to item) or late-game congestion.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / cap;
        score += 20.0;                       // base cost of opening a bin
        score -= 25.0 * poor_fit;            // rebate when item leaves big hole elsewhere
        if fitting_bins_count == 0 { score -= 30.0; }
        if progress > 0.8 { score += 5.0; }  // late stream: consolidate instead
    }

    // Item-size coupling: large items deserve priority placement.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);

    // Quadratic dead-space penalty: small post-residuals are wasteful unless near zero
    let dead = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 6.0 * dead * (1.0 - progress);

    // Tight fit reward (smooth, cubic in post_residual)
    score -= 4.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    let nxt = next_item_size as f64 / cap;
    if nxt > 0.0 {
        let gap = (norm_pr - nxt).abs();
        score += 2.0 * gap * gap - 1.5 * nxt * (1.0 - norm_pr);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: prefer it only when post-residual is full capacity and existing bins are fragmented
    if bin_residual == bin_capacity {
        score -= 2.0 + 3.0 * progress;
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bucket by capacity/8 slices.
    let class = post_residual / (bin_capacity / 8);
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-exact fits (post_residual small) more than linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Harmonic coupling: post_residual classes that pair with common item sizes
    // (10..80 multiples of 5) are more "reusable"; penalize odd dead zones.
    let reusable = (post_residual >= 10 && post_residual <= 80) && (post_residual % 5 == 0);
    if reusable {
        score -= 6.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 10.0; // awkward sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0f64.min(20.0 - slack as f64 * 0.8).max(-20.0);
            if slack <= 5 { score -= 15.0; }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins with decent residuals exist,
    // but allow it early / when residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0
            + 25.0 * (mean_residual / bin_capacity as f64)
            + 10.0 * (open_bins_count as f64).sqrt();
        if post_residual as f64 > mean_residual {
            score += 15.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate waste).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten up: discourage leaving mid-size residuals.
    if progress > 0.7 && post_residual > 30 && post_residual < 50 {
        score += 8.0;
    }

    // Modulo harmonic: residuals near capacity/2 are flexible, slight reward.
    let half = bin_capacity / 2;
    if post_residual.abs_diff(half) <= 5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space that cannot fit the next item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bins pressure: penalize bins in proportion to how many bins are open,
    // pushing toward consolidating into fewer bins unless fit is excellent.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high; only win when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.3;
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post residual equals next item size -> perfect chain
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // If next item cannot fit here, this bin becomes dead-ish space; penalize small leftovers
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.6;
        // tiny unfillable sliver is very bad
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward bins tighter than the mean (best-fit flavor)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discard opening new bins unless nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        // if next item also fits comfortably in a fresh bin, opening is more attractive
        if next_item_size == 0 || next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference for denser packing late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
