pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize leftover residual, with a non-linear (quadratic/cubic) coupling
    // that grows as the stream progresses (late-stage dead space is more costly).
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr + 3.0 * progress * progress * norm_pr * norm_pr);

    // Coupling with item size: prefer bins where the item fills a large fraction
    // of the residual (tight fit), expressed smoothly via a sine-free polynomial.
    let fill = norm_item / (norm_item + norm_pr + 1e-9);
    score -= 2.5 * fill * fill * (1.0 - fill) * (1.0 + progress);

    // Lookahead coupling: reward bins whose post-residual can host the next item
    // exactly or nearly; penalize post-residuals that strand small dead space.
    if next_item_size > 0 {
        let gap = (pr - norm_next * cap).abs();
        let gapn = gap / cap;
        score += 1.8 * gapn * gapn;
        if pr >= next_item_size as f64 {
            score -= 0.8 * (1.0 - gapn);
        }
    }

    // Mean-residual divergence term: placing into a bin far from the mean residual
    // smooths the residual distribution; couple non-linearly with progress.
    let dev = (pr - mean_residual) / cap;
    score += 0.6 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 + progress);
    }

    // Crowding pressure: when many bins are open, mildly favor consolidation
    // into existing bins over opening new ones.
    score += 0.15 * (open_bins_count as f64).sqrt() * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate: make the empty bin unattractive unless the item is very
    // large relative to capacity (poor fit anywhere else) — smooth sigmoid-free
    // polynomial gate on item size.
    if bin_residual == bin_capacity {
        let big = ((norm_item - 0.5) * 4.0).clamp(-1.0, 1.0);
        score += 4.0 - 3.0 * big * big;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space" bands.
    let post = post_residual as u32;
    let residue = post % 10;
    // Penalize residues that are hard to fill (1..=9 small slivers), reward multiples of 10.
    if post > 0 {
        let harm = match residue {
            0 => -3.0,
            1 | 2 => 4.0,
            3 | 4 => 2.0,
            9 => 5.0,
            _ => 1.0,
        };
        score += harm * (post as f64).sqrt();
    }

    // Integer-division thresholds: post_residual bucketed by capacity quarters.
    let quarter = bin_capacity / 4;
    if post < quarter {
        score += 8.0; // very tight bin, nearly unusable
    } else if post < 2 * quarter {
        score -= 1.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 12.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            score -= 4.0 * (1.0 - slack as f64 / cap);
            // Harmonic check: does next item leave a multiple-of-10 residue again?
            if (post - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize large leftovers
            score += (post as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin relative to mean residual of open bins.
        score = cap * 0.55 + mean_residual * 0.5 - 15.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin perfectly fits next item too if item_size + next <= C
            if item_size + next_item_size <= bin_capacity {
                score -= 6.0;
            }
        }
    }

    // Slight preference for tighter existing fits overall.
    score += (bin_residual as f64 - post as f64).abs() * 0.0;

    // Mean-residual divergence penalty: keep open-bin residuals homogeneous.
    score += (mean_residual - post as f64).abs() * 0.05;

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that are unlikely to fit typical items.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly (post_residual near zero is ideal).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a good
    // lookahead fit or current open bins have poor residuals.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is more attractive when open bins are crowded.
        score -= open_bins_count as f64 * 0.5;
        // Lookahead: if next item fits nicely in the fresh bin's residual
        // after this placement, soften the penalty.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 15.0;
        }
    }

    // Pressure from number of open bins: discourage spreading items thin.
    score += open_bins_count as f64 * 0.3;

    // Slight preference to keep residuals near the mean (balance load).
    score += ((post_residual as f64 - mean_residual) / 10.0).abs();

    // Lookahead synergy: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
