pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * (1.0 - tight) * (1.0 - tight * tight);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: penalize bins whose leftover can't host the next item,
    // reward bins whose leftover can host it snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 4.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item barely fits anywhere
    // or open bins are quite full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = (bin_residual as f64) / (item_size as f64).max(1.0);
        // Penalize opening a new bin unless item is large relative to residual
        // or mean residual is small (bins are nearly full).
        score += 18.0;
        score -= 10.0 * (item_size as f64) / (bin_capacity as f64);
        score -= 6.0 * (1.0 - mean_residual / (bin_capacity as f64)).max(0.0);
        score -= 3.0 * progress;
        // If no open bin can fit at all, new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Avoid hoarding many open bins with small items early.
        let _ = openness;
    }

    // Mild preference for filling fuller bins first (best-fit flavor).
    score -= 0.05 * (bin_residual as f64) / (bin_capacity as f64);

    // Small tie-break noise-free structural term using stream position.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // Penalize leaving dead space that no plausible item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: residual^2 scaled by progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (non-linear coupling)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let gap = pr as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 3.0 * (1.0 - (gap / cap).abs()) * (0.4 + 0.6 * progress);
        } else {
            score += 2.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for bin proliferation late in stream
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: neutral baseline with slight progress-dependent cost
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress - 2.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Class index via integer division thresholds (harmonic classes of capacity).
    let class = (post_residual * 5) / bin_capacity; // 0..4 : (0,20,40,60,80)
    // Reward small residuals (good fit), but dead space < 10 is perfect (unusable anyway).
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score -= 40.0; // dead space, nothing can ever use it
    } else {
        // Penalize leftovers that are "awkward" — cannot fit typical small items (10..80).
        // Harmonic class reward: lower class (smaller residual) is better.
        score -= (5 - class) as f64 * 4.0;
        // Non-linear penalty: residual that is just below a common item size is wasted.
        let mut awkward = 0.0;
        for s in [10u32, 15, 20, 25, 30, 40, 50, 60, 70, 80] {
            if post_residual > 0 && post_residual < s && (s - post_residual) <= 8 {
                awkward += (s - post_residual) as f64;
            }
        }
        score += awkward * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // residual after hypothetical next placement
            let r2 = post_residual - next_item_size;
            score -= (r2 == 0) as i32 as f64 * 20.0;
            score -= (r2 < 10) as i32 as f64 * 10.0;
            score += r2 as f64 * 0.3;
        } else {
            // next item won't fit here; residual becomes long-lived dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when residuals
    // across open bins are large (poor fits available) or stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins generally; relax when mean residual is high.
        let mut new_score = 45.0 + mean_residual * 0.2 - progress * 15.0;
        if mean_residual < 20.0 {
            new_score += 20.0; // open bins are nearly full, new bin fine
        }
        if post_residual == bin_capacity {
            // empty-bin call: post_residual == capacity, keep moderate penalty
        }
        score = new_score;
        // Prefer new bin if item leaves perfect dead space pattern? keep simple.
    }

    // Mild preference for tighter bins among equals (best-fit reinforcement).
    score += (bin_residual as f64) * 0.05;

    // Slight global pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
