    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (small gap), mild penalty
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Progression: later in stream, be more conservative about opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect chain — reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    }
    // Next item fits into post residual at all: mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
    } else if next_item_size > post_residual {
        // Next item cannot use leftover: penalize dead space proportionally.
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average.
    let dev = mean_residual - (post_residual as f64);
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or
    // no open bin is attractive. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 200.0;
        // Large items (leave small residual) justify a new bin.
        score -= (item_size as f64 - 50.0) * 2.0;
        // If many bins fit the item, opening new bin is wasteful.
        score += (fitting_bins_count as f64) * 30.0;
        // Late in stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
        // If mean residual across open bins is large, open bins are roomy — use them.
        score += (mean_residual - item_size as f64).max(0.0) * 0.5;
    }

    // Slight penalty for leaving very small unusable residuals (1..=5).
    if post_residual >= 1 && post_residual <= 5 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0; // dead space below minimum item size
    }

    // Lookahead: penalize if next item could have used this residual better.
    if next_item_size > 0 {
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 6.0; // we consumed space the next item needed
        } else if next_item_size <= post_residual {
            score -= 3.0; // residual remains useful
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless fit is bad,
    // but allow opening when open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowding = if mean_residual > 0.0 { mean_residual / (bin_capacity as f64) } else { 0.0 };
        score += 12.0 - 10.0 * crowding;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // If next item is large and won't fit anywhere else, new bin is fine.
        if next_item_size > item_size && next_item_size > mean_residual as u32 {
            score -= 5.0;
        }
    }

    // Many open bins: encourage filling them rather than spreading.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residual above the mean (use the roomier ones for big items,
    // keep tight bins for small future items).
    if (bin_residual as f64) < mean_residual && item_size > 40 {
        score += 4.0;
    } else if (bin_residual as f64) > mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep shape: penalizes large dead space super-linearly
    score += poly * 30.0 * (0.5 + progress);

    // Reward tight fits increasingly as the stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * 20.0 * (1.0 + progress);

    // Interaction: small post-residual that still fits the next item is valuable
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nx = next_item_size as f64 / cap;
        score -= (1.0 - (x - nx)) * 15.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // penalize dead space that cannot host the lookahead item
        score += x * 12.0 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open and this placement wastes space
    score += (open_bins_count as f64).ln().max(0.0) * x * 3.0;

    // Slight preference for bins below mean residual (balancing)
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo capacity/4 classes
    let quarter = bin_capacity / 4;
    let residue_class = post_residual % quarter;
    // Penalize residuals that fall in awkward classes (near half-capacity waste)
    if residue_class > quarter / 2 {
        score += (residue_class - quarter / 2) as f64 * 0.7;
    } else {
        score -= residue_class as f64 * 0.3;
    }

    // Integer-division thresholds: post_residual divided into coarse buckets
    let bucket = post_residual / 10;
    score += bucket as f64 * 0.5;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.4;
        } else {
            score += (next_item_size as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score += 10.0 - crowded * 6.0 + progress * 5.0;
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild penalty proportional to fill asymmetry with mean residual
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in the "unusable gap" zone (1..=15)
    // are much worse than large residuals, since small items may still use big gaps.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64);
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward tight fits relative to the residual available.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: penalize opening new bins when many bins exist,
    // but allow it when few bins are open (early stream).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if this is a poor fit everywhere
        // or the item is large relative to typical residual.
        let poor_fit = fitting_bins_count == 0 || (mean_residual < item_size as f64 * 1.15);
        if poor_fit {
            score -= 60.0;
        } else {
            // Slightly discourage wasting a fresh bin when fits exist.
            score += 10.0 + 5.0 * open_bins_count as f64 * progress;
        }
    } else {
        // Placing into an existing bin is generally good: mild reward.
        score -= 5.0;
        // Last-chance bin: strongly favor using the only bin that fits,
        // otherwise this capacity is lost.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement;
    // if post_residual is small and next item is small too, dead space is less risky.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 8.0; // dead space that next item can't use either
        }
    }

    // Mild preference to balance residuals: avoid dumping into already-large-residual bins
    // when mean residual is low (keeps bins uniform).
    if bin_residual as f64 > mean_residual * 1.5 && open_bins_count > 1 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
            if next_waste == 0 {
                score -= 50.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize proportionally.
            let gap = next_item_size - post_residual;
            score += 10.0 * gap as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - bin_residual as f64).max(-50.0) * 0.5;

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening a new bin when open bins exist and can fit well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 + 20.0 * progress;
        if open_bins_count > 0 && post_residual >= next_item_size && next_item_size > 0 {
            score += 30.0; // existing bin could chain next item; don't open new
        }
        if fitting_bins_count == 1 {
            score += 80.0; // never open when a sole bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + 10.0 * (5 - post_residual) as f64;
    }

    // Penalize residuals that are too small to be useful later (dead space),
    // but reward residuals that can still hold a mid-sized item.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let next_leftover = post_residual - next_item_size;
            score -= 30.0 - 0.5 * next_leftover as f64;
        } else {
            // Next item can't use this bin's leftover: mild penalty scaled by gap.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when open bins
    // would leave badly fragmented space, or when the bin pool is small.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base cost of opening a bin, discounted early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 120.0 - 40.0 * progress;
        // If few bins fit the item, opening a fresh bin is less attractive.
        if fitting_bins_count <= 2 {
            open_cost += 80.0;
        }
        // If mean residual across open bins is high, open bins are roomy; opening
        // a new one wastes capacity, so penalize more.
        open_cost += 0.3 * mean_residual;
        // Many open bins: consolidation is preferable, penalize new bins.
        open_cost += 2.0 * open_bins_count as f64;
        score += open_cost;
    } else {
        // Reward using existing bins, more so when they are below-mean residual
        // (i.e., filling the emptier bins balances the pool).
        score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);
        // Slight preference for bins that are already fairly full.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 20.0 * fill;
    }

    // Time-horizon modulation: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: reward tight fits with a polynomial of the fill ratio
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * fill * fill * (1.0 - 0.5 * progress);

    // Penalize small-but-unusable post_residual (dead space) with smooth term
    let dead = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        score += 10.0 * dead * (1.0 - dead) * (1.0 - dead);
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Slight preference for bins below mean residual (balancing)
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: exact-fill and tiny remnants are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 10.0;
    } else if pr <= 30 {
        score += 8.0;
    } else {
        score += 20.0 + 0.3 * (pr as f64);
    }

    // Modulo-class penalty: remnants that are "dead" (too small for typical items)
    // get an extra harmonic bump; remnants in reusable classes get relief.
    let class = pr % 10;
    if class >= 8 || class == 0 {
        score -= 6.0;
    } else if class <= 2 {
        score += 4.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0 + 0.2 * next_item_size as f64;
        } else if next_item_size == pr + 1 || next_item_size == pr + 2 {
            score += 5.0; // near-miss: dead space likely
        }
        // If nothing can use the remnant at all, penalize more.
        if pr > 0 && pr < 10 && next_item_size > pr {
            score += 10.0;
        }
    } else {
        // Last item: filling tightly matters most.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = pr as f64; // == capacity - item_size
        // Penalize opening a new bin, more so early in the stream.
        let mut nb = 45.0 + 25.0 * (1.0 - progress) + 0.25 * waste;
        // But if it's a near-perfect placement (item ~ capacity), allow it.
        if waste <= 10 {
            nb -= 70.0;
        }
        // If many bins already fit the item, opening new is wasteful.
        if fitting_bins_count > 2 {
            nb += 20.0 * (fitting_bins_count as f64 - 2.0);
        }
        // If mean residual of open bins is large, prefer existing bins.
        if mean_residual > item_size as f64 + 15.0 {
            nb += 25.0;
        }
        score += nb;
    }

    // Slight preference for tighter existing bins (waste-averse).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Late-stream tightening: push toward filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are heavily penalized.
    // Treat gaps below the smallest plausible item (1..100 stream, but small gaps < 10 are dead).
    if post_residual < 10 {
        score += 120.0;
    } else if post_residual <= 20 {
        score += 45.0;
    } else if post_residual <= 30 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: penalize using bins when many are open, favor consolidation;
    // but ease pressure late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * 8.0 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins unless it avoids big dead space.
        score += 70.0 + pressure;
    } else {
        score -= 10.0 + pressure * 0.5;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Slight preference toward bins tighter than the mean (better packing zones).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), softly relative to mean residual.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward when the next item exactly fills the
    // remaining space (post_residual == next_item_size => perfect 2-item packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 / (1.0 + gap * gap * 0.05));
        // Penalize when next item cannot use the leftover space at all
        if next_item_size as u32 > post_residual {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it attractive only when the current item is large
    // (would leave big dead space in an existing bin) or no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items (keeps small leftovers for small items).
        score -= 10.0 * tightness * tightness;
        // Penalize new bin if existing bins fit decently.
        if post_residual < 20 {
            score += 15.0;
        }
        // Late in the stream, avoid spreading items across many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64 * 0.05)).min(3.0);
    }

    // Small penalty for creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (best-fit core)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize large dead space nonlinearly
    if post_residual > 0 {
        score += 0.08 * (post_residual as f64).powf(1.3);
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0; // dead space relative to lookahead
        }
        // If next item would fit perfectly after this placement
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // or few fitting bins exist or stream is early with few bins open
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0;
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        score -= 8.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Global state coupling: prefer filling bins when mean residual is high
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Encourage consolidating when many bins are open
    if bin_residual != bin_capacity {
        score -= 0.3 * open_bins_count as f64 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: penalize post-residual, with a non-linear (quartic) dead-space term
    let mut score = pr + 30.0 * fit_norm * fit_norm * fit_norm * fit_norm * cap;

    // Smooth stream-progress coupling: later in the stream, tighten residual tolerance
    let tighten = 1.0 + 0.8 * progress * progress;
    score += tighten * (pr * pr) / cap;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - fit_norm) * (1.0 - fit_norm) * 10.0 * (0.5 + progress);

    // Last-chance bin: smooth sigmoid-like reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 / (1.0 + (-3.0 * (progress - 0.5)).exp());
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic gap term)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.4 * gap * gap / cap;
        // Exact-fit bonus for the lookahead item
        if pr >= next_item_size as f64 {
            score -= 6.0 * (1.0 - gap / cap);
        }
    } else {
        // Final item: strongly favor filling bins as full as possible
        score -= 20.0 * (1.0 - fit_norm);
    }

    // Mild penalty when this bin's residual deviates from the mean (spread control)
    score += 0.05 * (pr - mean_residual).abs();

    // Prefer consolidating into fewer bins when many are open
    score += 0.02 * open_bins_count as f64 * fit_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals in the same mod-10 class
    // pair well with items drawn on a 10-grid; reward classes that leave
    // "chunk-friendly" space (multiples of 10), penalize odd dead space.
    let pr = post_residual;
    let class = pr % 10;
    let class_reward = match class {
        0 => -8.0,
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        3 | 7 => 1.5,
        4 | 6 => 0.5,
        _ => 0.0,
    };
    score += class_reward;

    // Small residuals are near-perfect fits: strong reward.
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 20.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Integer-division threshold: does the leftover fit the lookahead item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // This bin stays useful for the next item: reward, scaled by
            // how snugly the lookahead fits (post-post residual small).
            let post_post = pr - next_item_size;
            score -= 12.0 - (post_post as f64).min(12.0) * 0.5;
        } else {
            // Lookahead cannot use the leftover: penalize proportional waste.
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it slightly unattractive unless residuals
    // across open bins are already tight (few bins can fit the item).
    if bin_residual == bin_capacity {
        let tightness = (fitting_bins_count as f64).max(1.0);
        score += 6.0 / tightness + (open_bins_count as f64).sqrt() * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0;
    }

    // Mild pull toward bins below the mean residual (keeps large gaps
    // consolidated in bins that can absorb future big items).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are semi-dead until later items.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Reward tight fits (item nearly fills the bin).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones; with few open bins, consolidation is cheap.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize when many bins already open,
        // or when this bin is not the last chance.
        score += 12.0 + (open_bins_count as f64) * 4.0;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Reuse reward grows with number of open bins (bin consolidation).
        score -= (open_bins_count as f64).ln() * 6.0;
        // Last-chance bin: use it or lose it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Slight preference for bins whose residual is below average
    // (keeps large residuals available for large future items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early in the stream, be a bit more willing to open fresh bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills post_residual -> strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Next item fits into post_residual (chainable placement)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 12.0 - 0.15 * slack_after_next;
    }
    // Next item cannot fit here: penalize proportionally to wasted chain potential
    if next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        score += 0.25 * miss.min(60.0);
    }

    // Dead-space penalty: small post_residual that nothing useful can fill
    if post_residual < 10 {
        score += 8.0 + (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tighter bins relative to mean residual
    score += 0.20 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Mild pressure to reuse open bins as stream progresses / many bins open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress + 0.02 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bin leaves a bad leftover
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity as f64 - item_size as f64) - (bin_capacity as f64 - next_item_size as f64)
        } else {
            0.0
        };
        score += 10.0 - 0.1 * bad_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits perfectly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting good residual.
            score += 5.0;
        }
    } else {
        // Last item: any bin is fine, prefer tightest fill (already via post_residual).
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins, discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += crowding * 2.0 * (0.5 + progress);

    // Mean residual context: if this bin's residual is far below mean, it's a good filler.
    let res = bin_residual as f64;
    let dev = res - mean_residual;
    score += 0.1 * dev;

    // New-bin candidate handling: prefer new bin only when existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how full the stream is.
        let mut new_bin_cost = 45.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            new_bin_cost = 0.0; // forced new bin anyway
        } else if fitting_bins_count == 1 {
            new_bin_cost += 30.0; // don't skip the last-chance bin
        }
        // If item is large relative to capacity, filling an existing bin is better.
        new_bin_cost += 0.3 * item_size as f64;
        score += new_bin_cost;
    }

    // Slight preference for bins whose residual is close to item_size (perfect-ish fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    // smooth polynomial coupling of post_residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (1.0 - t);
    score -= 6.0 * norm_item * norm_pr * (0.5 + t);
    // reward near-perfect fits smoothly
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;
    // lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let gap = norm_next - norm_pr;
        score += 5.0 * gap.max(0.0) * gap.max(0.0) * (0.3 + t);
        score -= 3.0 * (1.0 - gap.max(0.0) / cap.max(1.0)) * norm_next * (1.0 - norm_pr);
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 4.0 * norm_item;
    }
    // mild penalty for spreading across many open bins late in stream
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * t * norm_pr;
    // deviation from mean residual: prefer bins below mean residual (tighter)
    score += 2.0 * (pr - mean_residual) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "friendly" residue class (small or exactly reusable) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space classes: leftover <= 10 is nearly worthless.
        if post_residual <= 10 {
            score += 30.0;
        } else if post_residual <= 20 {
            score += 10.0;
        } else if post_residual <= 40 {
            score -= 5.0;
        } else if post_residual <= 70 {
            score -= 12.0;
        }
        // Modulo-10 harmonic class: leftovers that are multiples of 10
        // align with the common item grid and stay reusable.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        // Half-capacity class: leftover near C/2 is highly flexible.
        let half = (cap / 2.0 - pr).abs();
        score -= 15.0 * (1.0 - half / (cap / 2.0)).max(0.0);
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a chained perfect fit — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            if npr <= 10 {
                score -= 40.0; // chain leaves only tiny waste
            } else if npr % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's leftover anyway; slight penalty
            // for wasting a flexible large residual now.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): prefer it only when it yields a
    // harmonious residual (multiple of 10 or large), otherwise penalize
    // proliferation of open bins.
    if bin_residual == bin_capacity {
        if post_residual % 10 == 0 || post_residual >= 50 {
            score -= 10.0;
        } else {
            score += 20.0;
        }
        score += open_bins_count as f64 * 2.0;
    }

    // Progress-scaled consolidation: late in the stream, tighten bins
    // (favor small residuals) to avoid stragglers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr * 0.3;

    // Prefer bins tighter than the mean (best-fit flavor).
    score -= (mean_residual - pr) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are "dead space" — penalize hard.
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Perfect fit for the lookahead item: reserve this bin for it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // If lookahead cannot use the leftover, the gap is likely wasted.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // (and penalize opening new ones) to contain bin proliferation.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure
        // and how tight the current fit already is.
        score += 15.0 + pressure * 10.0 + (item_size as f64) * 0.2;
    } else {
        // Existing bin: reward usage more when many bins are open.
        score -= pressure * (bin_residual - post_residual) as f64 * 0.15;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps the pool of usable gaps uniform).
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item -> big reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize large leftover that becomes dead space.
            score += 8.0 + 0.15 * (post_residual as f64 - mean_residual.max(0.0)).abs();
        }
    } else {
        // Last item: just minimize waste.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize scattering across many bins when this bin is already loose.
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive if current item is large and no bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 * large_item; // fresh bin chains well for large items
        } else {
            score += 15.0 + 10.0 * large_item; // discourage opening new bins casually
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits: must open
        }
    }

    // Slight stream-progression bias: tighten packing more aggressively later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor placements that leave little waste.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: does the next item fit in the leftover space?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible -> reward.
            score -= 10.0 + 5.0 * (next_item_size as f64) / cap;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only if we place current item well.
            score -= 2.0;
        } else if next_item_size > post_residual
            && post_residual > 0
            && post_residual < 15
        {
            // Dead space too small for next item: mild penalty unless near-perfect.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Global mean residual coupling: if open bins are on average roomy,
    // filling this one is more valuable.
    if bin_residual < bin_capacity {
        score -= 4.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin gets a base penalty that shrinks
    // as the stream progresses (later on, opening bins is less costly).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0 - 12.0 * progress;
        // If nothing else really fits (or only this fits), opening is fine.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 25.0;
        }
        // Large item: opening a fresh bin is often the right call.
        if item_size > 60 {
            new_bin_penalty -= 10.0;
        }
        // If the next item is huge and residuals are small, fresh bin helps.
        if next_item_size > 70 && mean_residual < 20.0 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Small penalty for leaving awkward mid-range gaps.
    if post_residual >= 10 && post_residual <= 20 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_post * norm_post * (1.0 - norm_post);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses.
    score -= progress * (cap - post) * 0.15;

    // Penalize dead space relative to mean residual (smooth quadratic coupling).
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space usable by next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (post - nxt).max(0.0) / cap;
        score -= 12.0 * usable * (1.0 - usable) * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins early.
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "large" residue
    // classes (still usable by typical items) are rewarded; tiny dead space penalized.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows quadratically for small unusable residues.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // Modulo-10 harmonic class: residues near multiples of 10 are "clean" fits.
        let cls = pr % 10;
        if cls == 0 {
            score -= 6.0;
        } else if cls <= 2 || cls >= 8 {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    } else {
        // Perfect fill is best.
        score -= 25.0;
    }

    // Integer-division thresholds on post_residual: usable bands for common item ranges.
    if pr >= 40 {
        score -= 8.0;
    } else if pr >= 20 {
        score -= 3.0;
    } else if pr > 0 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 8.0 - (slack as f64).min(8.0);
        } else {
            // Next item cannot use this residue: penalize proportionally.
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Prefer tight bins relative to mean residual (best-fit flavor).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Early in stream: tolerate opening new bins less; late: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper early, expensive late.
        score = 60.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Only open new bin if forced or existing fits are terrible.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else if open_bins_count > 8 {
        score -= 3.0; // encourage filling many open bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (<10, min item size) are unusable
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // hard penalty for creating a dead gap
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Penalize moderate unusable gaps nonlinearly (gap too small for next item)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Open-bin pressure: discourage spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(1.3) * (0.15 + 0.35 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when open bins are crowded / poor fits
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        score += 20.0 + 15.0 * (1.0 - crowd);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Favor bins whose residual is close to the item (best-fit sharpening)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect lookahead fit: next item still fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit in the leftover: penalize dead space, worse if tight
    else if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
    }

    // Reward bins whose residual is below mean (denser bins absorb items better)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base, amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score -= 50.0; // perfect closure
    } else if post_residual > 0 {
        let unusable = (post_residual as f64) < 10.0; // dead wedge below min useful size
        if unusable {
            score += 3.0; // small penalty: bin effectively closed anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual; penalize leaving awkward gaps
            score += 2.0;
        }
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Global state coupling: if this bin's residual is far below mean, it is
    // already fragmented; discourage dumping large items here.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in stream, be pickier (leave room); late, just fill.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // New-bin candidate: neutral baseline with slight preference early on,
    // discouraged late when open bins should be consumed.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter packing matters more.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * 0.5;
    score += poly * cap * 0.3;

    // Reward near-perfect fits smoothly (quadratic trough at post_residual ~ 0).
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * 0.4;

    // Lookahead: bonus if next item fits the post residual (smooth kernel).
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - fit_gap / cap).max(0.0) * next_item_size as f64 * 0.5;
    }

    // Penalize when this is the only fitting bin (last chance) unless fit is tight.
    if fitting_bins_count == 1 {
        score += (1.0 - norm_pr) * 10.0;
    }

    // Mild pressure to prefer filling bins with low mean residual (compact bins).
    score += (mean_residual - pr) * 0.1;

    // Prefer keeping number of open bins low: penalize new-bin candidate smoothly.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).sqrt() * 5.0 + (1.0 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual mod small divisors
    // classify dead space into "usable" vs "waste" classes.
    let pr = post_residual;
    let mod5 = (pr % 5) as f64;
    let mod10 = (pr % 10) as f64;
    let mod25 = (pr % 25) as f64;

    // Waste penalty for awkward leftover classes (not multiples of common sizes)
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0; // perfectly reusable leftover
        } else if pr % 5 == 0 {
            score -= 5.0;
        } else if pr < 10 {
            score += 18.0 * (1.0 - pr as f64 / 10.0); // tiny dead space
        } else {
            score += mod10 * 0.8 + mod25 * 0.3;
        }
    } else {
        score -= 20.0; // perfect fill
    }

    // Exact fit via integer division threshold: leftover divisible by item class
    if pr > 0 && item_size > 0 && pr % item_size == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic class match: next item divides or near-divides leftover
            if pr % next_item_size == 0 {
                score -= 14.0;
            } else {
                score -= (pr - next_item_size) as f64 * 0.25;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.35; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Prefer tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late in stream, consolidate; early, allow spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    // Discourage opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 4.0 + (fitting_bins_count as f64) * 3.0;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item are unusable -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }
    // Penalize small-but-nonzero gaps proportionally harder (nonlinear).
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open, penalized when many.
        score += bin_pressure * 12.0;
        score -= 20.0; // base attractiveness of fresh bin
    } else {
        score += bin_pressure * 2.0;
    }

    // Lookahead: if next item could exactly use the post_residual, reward it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Deviation from mean residual: prefer bins that keep residual spread sane.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact or near match => strong reward (subtract).
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64 * 0.5)).max(-1.0).min(1.0);
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is too small to ever fit the next item (dead space risk).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit (minimize post residual).
        score += 0.0;
        score -= 10.0;
    }

    // Tight fit reward relative to current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize bins with residuals far below the mean residual (fragmented bins) slightly,
    // but favor consuming low-residual bins to close them out.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    // or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let frac_post = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - frac_post) * (1.0 - frac_post);

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more the closer post_residual is to being "almost enough".
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 10.0 * (1.0 - gap / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, growing with number of open bins.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If this is the only fitting option (or few options), discount the new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper (build a pool for later items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If mean residual of open bins is small, a new bin is more attractive.
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for bins whose residual deviates below the mean (consolidating small leftovers).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Time horizon: late in the stream, avoid leaving large residuals unused.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - frac_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual: quadratic in normalized residual
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Reward tight fits strongly (small post_residual gets big subtraction)
    score -= 60.0 * (1.0 - norm_pr).powi(6);

    // Smooth coupling: residual relative to mean residual across open bins
    if mean_residual > 0.0 {
        score += 15.0 * (pr - mean_residual) / (mean_residual + cap);
    }

    // Last-chance bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item could use this post_residual, reward leaving it
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 25.0 * (1.0 - gap / cap) * (1.0 + 0.5 * progress);
        } else {
            score += 10.0 * (-gap / cap);
        }
    } else {
        // Last item: just minimize post_residual, no future to plan for
        score -= 20.0;
    }

    // New-bin candidate: empty bin gets smooth penalty that decreases as stream progresses
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress).powf(1.5) + 10.0;
        // But allow new bin when open bins are congested
        score -= 20.0 * (open_bins_count as f64).ln().max(0.0) / (1.0 + open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits (0), and
    // "harmonic" leftovers that common small items can still reuse.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Leftovers in harmonic classes (multiples of 10, 20, 25, 50) remain
    // usable by typical item sizes; reward them via modulo arithmetic.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 20 == 0 { score -= 2.0; }

    // Dead space: tiny unusable leftovers (1..=9) are penalized hard,
    // scaled by how much of the bin was wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 8.0;
    }

    // Capacity-fraction thresholds: leftover <= 1/4 of capacity is risky
    // dead space unless it is exactly harmonic.
    if pr > 0.0 && pr <= cap / 4.0 && post_residual % 10 != 0 {
        score += 12.0;
    }
    // Leftover >= 3/4 of capacity: bin was nearly empty; mildly discourage
    // burning a fresh bin on a small item.
    if pr >= 3.0 * cap / 4.0 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains beautifully.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits with leftover; reward based on chain quality.
            let chain_left = post_residual - next_item_size;
            score -= 10.0;
            if chain_left % 10 == 0 { score -= 8.0; }
            if chain_left == 0 { score -= 40.0; }
        } else {
            // Next item won't fit here; penalize if leftover becomes dead space.
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size as f64 - pr).min(20.0) * 0.8;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many options: emphasize tightness (small post_residual wins).
        score += (pr / cap) * 15.0;
    }

    // New-bin candidate handling: an empty bin has no scarcity value yet;
    // discourage opening one unless leftovers elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But early in the stream or with few open bins, a fresh bin is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        if open_bins_count == 0 { score -= 40.0; }
        // If next item is large, having a fresh bin around is valuable.
        if next_item_size as f64 > cap * 0.5 { score -= 15.0; }
    }

    // Mild pressure toward bins with below-average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual sizes that could still accommodate typical items
    // (residual >= 10 keeps the bin usable); penalize marginal residuals.
    if post_residual >= 10 {
        score -= 8.0;
        // If the lookahead item fits the resulting residual, reward it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins and a poor fit, opening a new bin becomes attractive.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score = bin_capacity as f64 + open_bins_count as f64 * 2.0;
        // Prefer a new bin when the current item leaves a dead gap in any
        // existing bin and the next item is large.
        if post_residual < 10 || (next_item_size > 50 && post_residual < next_item_size) {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit).
        score += (bin_residual as f64 - item_size as f64) * 0.3;
    }

    // Mild progression term: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_residual = post_residual - next_item_size;
        // Reward chains that end tight
        score -= 50.0 + (chain_residual as f64).min(30.0);
        if chain_residual == 0 {
            score -= 200.0; // perfect 2-item packing
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for next item: dead space penalty
        score += (post_residual as f64) * 0.3;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize wasting large residual space on small items
    if (post_residual as f64) > mean_residual * 1.5 && item_size < 40 {
        score += 15.0;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: keep it attractive unless an excellent fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a bin
        score += 40.0;
        // Open a new bin if item is large and fit is poor elsewhere is handled
        // by other bins' scores; make new bin mildly attractive for big items
        if item_size >= 70 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Slight preference to fill older bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Penalize many open bins mildly (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (waste as f64) / (post_residual as f64).max(1.0));
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap
            // if it's smaller than the smallest plausible item.
            if post_residual < 10 {
                score += 5.0;
            }
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let open_pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0).sqrt());
    score += 2.0 * open_pressure * ((post_residual as f64) / (bin_capacity as f64));

    // Mean residual coupling: if this bin is far below mean residual, it is a
    // poor home; nudge score toward mean-residual alignment.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 6.0 * dev;

    // New-bin candidate logic: only attractive when all open bins would leave
    // big waste or there are no good fits.
    if bin_residual == bin_capacity {
        let mut min_waste: f64 = f64::INFINITY;
        // Approximate waste of placing here vs. an existing bin is captured by
        // fitting_bins_count and mean_residual; make new bin costly by default.
        score += 15.0;
        // But if item is large relative to capacity and few bins fit it,
        // opening a fresh bin may be better.
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 18.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 10.0 * progress;
        // If mean residual across open bins is small, existing bins are full-ish;
        // a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        let _ = min_waste;
    }

    // Small time-dependent jitter-free drift to break ties toward fuller bins
    // as the stream progresses.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 3.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual.
    let mut score = pr - 12.0 * (1.0 - norm_pr) * norm_pr * cap;

    // Smooth stream-progress coupling: later in stream, tighten tolerance on waste.
    let tightness = 0.5 + 1.5 * progress * progress;
    score += tightness * norm_pr * norm_pr * cap;

    // Penalize dead space relative to mean residual of open bins (smooth interaction).
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead: reward leaving space for the next item, smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n).abs();
        score -= 4.0 * (-fit_gap / 20.0) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild preference for reusing existing bins vs opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes (or by 10) are more reusable; penalize awkward residues.
    let pr = post_residual;
    if pr > 0 {
        let mut reusability = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                reusability += 1.0;
            }
        }
        score -= reusability * 3.0;

        // Fractional capacity class of the residual
        let frac = pr as f64 / cap;
        if frac < 0.05 {
            score += 6.0; // nearly-full bin: fine to fill, but tiny residual is dead space
        } else if frac < 0.15 {
            score -= 2.0; // sweet spot: bin almost exactly closed
        } else if frac < 0.35 {
            score -= 1.0;
        } else if frac > 0.7 {
            score += 4.0; // leaving a huge residual means poor packing
        }

        // Integer-division threshold: post_residual / next_item_size
        if next_item_size > 0 {
            let q = pr / next_item_size;
            let r = pr % next_item_size;
            if q >= 1 && r == 0 {
                score -= 8.0; // next item fits perfectly here
            } else if q >= 1 {
                score -= (q.min(3) as f64) * 2.0 - (r as f64) / cap;
            } else {
                score += 3.0; // next item cannot use this residual
            }
        }
    } else {
        score -= 12.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: baseline slightly above a good fit, but attractive
    // when current residuals are large and fragmented.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * mean_residual + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // lookahead suggests fresh bin pairs well
        }
        if step_index as f64 / total_items as f64 > 0.9 {
            score += 5.0; // near stream end: prefer closing existing bins
        }
    }

    // Mild penalty for spreading across too many bins
    score += 0.05 * (open_bins_count as f64);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible follow-up item (<= 1..100 stream) are dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 35 {
        score += 8.0;
    }

    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual can still host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item.
        score += 0.25 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // (penalize the empty-bin candidate implicitly via its large post_residual,
    // but also add pressure so consolidation wins).
    score += 2.0 * (open_bins_count as f64).powf(0.8);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be slightly more willing to open bins (spread risk);
    // later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: does the leftover space match the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can land here -> reward proportional to tightness of fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * next_item_size as f64 - 0.2 * slack;
        } else {
            // Dead space: leftover too small for the next item -> penalize
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste + 10.0;
        }
        // Perfect 2-item fill is ideal
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many options, prefer tighter fits
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Relative to mean residual: bins with unusually small residual are precious,
    // avoid burning them on loose fits
    let tightness = mean_residual - bin_residual as f64;
    score += 0.3 * tightness.max(0.0);

    // New empty bin candidate: only attractive when current item leaves a large,
    // reusable residual and existing bins are mostly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64 / (mean_residual + 1.0);
        // Penalize opening new bins mildly, more as stream progresses / bins are sparse
        score += 20.0 + 30.0 * progress + 2.0 * openness;
        // But reward if the item is huge (poor fit elsewhere likely)
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to ever be useful again.
    if post_residual > 0 {
        let deadness = 1.0 - (post_residual as f64 / 100.0);
        // small residuals (<10) are nearly dead: extra penalty
        if post_residual < 10 {
            score += 6.0 * deadness;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for stranding space
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is penalized, but the penalty
    // shrinks when open bins have large mean residual (fragmented state) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let mut open_penalty = 20.0 + 0.5 * open_bins_count as f64;
        open_penalty -= 18.0 * fragmentation;   // fragmented bins -> new bin more attractive
        open_penalty -= 8.0 * progress;          // late stream -> consolidate less
        // if the item is huge relative to capacity, a fresh bin is natural
        open_penalty -= 5.0 * (item_size as f64 / bin_capacity as f64);
        score += open_penalty.max(2.0);
    } else {
        // Mild reward for using existing bins, scaled by how many bins are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Global state coupling: prefer placing into bins whose residual is above the
    // mean residual (i.e., roomier bins) when the item is small.
    if item_size <= 30 {
        if (bin_residual as f64) > mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic penalty on residual scaled by stream progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction between residual and item size (tight fits rewarded smoothly)
    score -= 12.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: reward residuals that smoothly anticipate the next item
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        score -= 6.0 * (1.0 - gap).max(0.0) * (1.0 - gap).max(0.0);
    } else {
        score += 4.0 * norm_pr;
    }

    // Smooth pressure from open-bin count and mean residual
    let ob_norm = (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    score += 5.0 * ob_norm * norm_pr * (mean_residual / cap);

    // Last-chance bonus (smooth, avoiding hard threshold)
    let last_chance = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 10.0 * last_chance * (1.0 - norm_pr);

    // New-bin candidate: neutral-ish baseline with slight smooth decay over time
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: which "coarse slot" it lands in.
    let slot = post_residual / 10; // 0..=10 integer division threshold
    // Penalize residuals that fall into awkward harmonic classes:
    // class 1..3 (tiny slivers) are nearly dead space; class 0 is perfect.
    match slot {
        0 => score -= 25.0,                       // perfect fit
        1 | 2 => score += 30.0 + 8.0 * (3 - slot) as f64, // dead slivers
        3 | 4 => score += 10.0,
        5 | 6 => score += 3.0,                    // half-capacity zone: reusable
        7 | 8 => score -= 6.0,                    // large residuals stay useful
        _ => {}
    }

    // Modulo-20 coupling: residuals divisible by 20 pair well with common item sizes.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nslot = (post_residual - next_item_size) / 10;
            score -= match nslot { 0 => 20.0, 1 | 2 => -6.0, _ => 4.0 };
        } else {
            // next item cannot use this residual: penalize small leftovers more
            if post_residual < 20 { score += 15.0; }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 45.0;
        // open fewer bins early when stream is young and bins are scarce
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // if mean residual across open bins is small, opening is more justified
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // if many bins already fit the item, opening is wasteful
        if fitting_bins_count > 0 {
            score += 12.0 * fitting_bins_count.min(4) as f64;
        }
    }

    // Mild pressure to consolidate: prefer bins with residual close to item (tight fits).
    let tightness = (bin_residual - item_size) as f64 / cap_f;
    score += 10.0 * tightness * tightness;

    // Slight preference toward bins whose residual is below the mean (fill crowded bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item (min item size 1, but practically small
    // slivers < ~15) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 15 {
            score += 40.0 * (1.0 - post_residual as f64 / 15.0);
        } else if post_residual < 30 {
            score += 12.0 * (1.0 - (post_residual as f64 - 15.0) / 15.0);
        }
    }

    // Reward near-perfect fits strongly (waste-aware best fit).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Exact fill: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item cannot fit in post residual but could fit in a fresh bin,
    // slightly penalize very tight fits when lookahead is large.
    if next_item_size > post_residual && next_item_size > bin_residual.saturating_sub(next_item_size) {
        score += 6.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // (consolidation), allow more bins as the count grows.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 2.0 * (open_bins_count as f64).sqrt();
        // Early in the stream, opening bins is cheap; late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        // If an existing bin leaves a large residual anyway, opening a new bin
        // is less bad: compare against mean residual.
        if mean_residual > 50.0 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Mild reward for keeping bins consolidated when many are open.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to the item (tightness).
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it fills afterwards.
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a residual that is
            // nearly but not exactly usable (awkward dead space).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 30.0 + gap;
            }
        }
    }

    // Compare post_residual to mean residual: penalize creating outliers
    // far above the mean (fragmentation), reward balancing residuals.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.6 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened reluctantly.
        score += 150.0;
        // Less penalty late in the stream or when few bins are open.
        score -= 80.0 * (step_index as f64 / (total_items as f64).max(1.0));
        // If the item leaves a large awkward residual in any existing bin,
        // opening fresh is relatively better: reduce penalty when item is large.
        score -= 0.5 * item_size as f64;
        // If next item is huge, a fresh bin is more flexible.
        if next_item_size >= 70 {
            score -= 40.0;
        }
    }

    // Slight preference for tighter bins among ties.
    score += 0.1 * (bin_residual as f64 - post_residual as f64).signum() as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strongly favor small post_residual (nonlinear).
    let tight = 1.0 - post / cap; // 0..1, higher = tighter fit
    score -= 35.0 * tight * tight;

    // Dead-space penalty: residuals too small for typical items (1..100) are wasted.
    if post_residual < 10 {
        score += 18.0;
    } else if post_residual <= 25 {
        score += 6.0 * (1.0 - post / 25.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, especially when other bins fit.
    if bin_residual == bin_capacity {
        let mut new_score = 45.0;
        if fitting_bins_count > 0 {
            new_score += 30.0 * fitting_bins_count as f64;
        }
        // Late in stream, prefer filling existing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_score += 20.0 * progress;
        // If next item is small, a fresh bin is less useful.
        if next_item_size > 0 && next_item_size <= 30 {
            new_score += 10.0;
        }
        score += new_score;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 20.0; // near-perfect chain
            } else {
                score -= 8.0 * (1.0 - slack / cap);
            }
        } else if post_residual > 0 {
            // next item cannot fit here; penalize leaving medium dead space
            score += 5.0 * post / cap;
        }
    }

    // Global balance: prefer bins with residual below mean (consolidate space).
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 6.0 * (mean_residual - resid) / cap;
    } else {
        score += 4.0 * (resid - mean_residual) / cap;
    }

    // Early stream: mild preference to spread load across bins (keep options open).
    if step_index < total_items / 4 && open_bins_count > 0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, penalize wasted space non-linearly
    let mut score = pr as f64;

    // Smooth non-linear waste penalty: cubic in normalized residual
    score += 40.0 * x * x * x * (1.0 - 0.5 * progress);

    // Interaction: post residual coupled with stream progress — tighter bins matter more late
    score *= 1.0 + 0.8 * progress * (1.0 - x);

    // Lookahead coupling: reward bins whose post residual matches next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 * (-gap / 30.0) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize slightly when good fits exist
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress - 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: penalize bins far from mean residual (outliers)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Fill ratio reward for near-perfect fits
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose post-residual falls into
    // "usable" classes (multiples of common small item sizes) are favored.
    let usable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50] {
            if r >= m && r % m == 0 { bonus += 6.0; }
        }
        // fine-grained: divisible by 5 keeps pairing flexibility
        if r % 5 == 0 { bonus += 2.0; }
        bonus
    };
    score -= usable(post_residual);

    // Penalize post_residual in dead zones: too small to fit any item (1..10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Integer-division threshold: post_residual / next_item_size ratio
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward bins that can also host the lookahead item exactly
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            } else {
                score -= 4.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
            }
        } else {
            // lookahead won't fit here: slight penalty, scaled by how close it is
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Capacity-fraction classes: reward tight fills via fractional thresholds
    let fill = post_residual as f64 / bin_capacity as f64;
    if fill < 0.05 { score -= 12.0; }        // near-perfect fill
    else if fill < 0.15 { score -= 6.0; }    // good fill
    else if fill > 0.5 { score += 4.0; }     // leaving half a bin empty

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current open bins
    // are all tight (mean residual low) and item is large relative to residual
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalty shrinks when open bins are crowded late in the stream
        score = 30.0 + 40.0 * pressure - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // large lookahead: fresh bin gives flexibility
        }
    }

    // Mild preference for bins below mean residual (balancing)
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    // Modulo coupling between item and residual: exact complementary fits
    if bin_residual % item_size.max(1) == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size (1)
    // are not the issue; instead penalize gaps that are "almost full" but too
    // small for typical next items (dead space in the 1..=15 range is hard to reuse).
    if post_residual > 0 && post_residual <= 15 {
        score += (16 - post_residual) as f64 * 3.0; // heavy penalty for tiny unusable slivers
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= tightness * 10.0;

    // Penalize leaving a gap that cannot fit the known next item when this bin
    // could otherwise have been closed out perfectly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }
    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins; a new empty bin
    // should look unattractive when open bins exist with decent fits.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to number of open bins.
        score += (open_bins_count as f64) * 2.0 + 20.0;
        // But allow a new bin when open bins are nearly saturated on average.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
    } else {
        // Mild reward for filling existing bins as open count grows.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Late in the stream, prioritize closing bins out (avoid stragglers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured.

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post_residual (perfect chain), penalize when it cannot fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fit_ratio; // partial chain potential
        } else {
            // next item cannot use this residual: dead space risk
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits badly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead chains perfectly in a fresh bin, ease the penalty.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Early in stream: slightly favor keeping bins open / consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Mild preference for fewer open bins (encourage filling existing bins).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize leaving dead space that nothing typical can use
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny slivers are dead space
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            // placing here would strand the next item; mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive when open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        // Prefer new bin only when existing bins are badly fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 + 20.0 * open_pressure * (1.0 - progress);
        if fragmentation > 40.0 {
            score -= 15.0; // existing bins are poor; new bin more acceptable
        }
        if post_residual as f64 >= mean_residual {
            score -= 8.0; // fresh bin keeps good average residual
        }
    }

    // Mild preference for bins below mean residual (consolidate fullness)
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Time horizon: late in stream, be more greedy about closing gaps
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress * progress;
    let coupling = pr * (1.0 + 0.8 * p) * (1.0 - 0.4 * progress * tightness);
    score += 0.25 * coupling;

    // Reward tight fits with smooth quadratic term
    score -= 1.5 * tightness * tightness * (1.0 + progress);

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        score += 0.4 * waste * waste / cap;
        // Reward bins whose post residual matches next item well
        let fit_next = 1.0 - (pr - nxt).abs() / cap;
        score -= 0.5 * fit_next * fit_next * (pr / cap);
    }

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - progress * 0.5);
    }

    // Slight preference for consolidating into fewer bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Encourage balance with mean residual
    score += 0.1 * (pr - mean_residual).abs() * progress;

    // New-bin candidate: prefer it only when current bins are too full/empty
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
        if next_item_size > 0 {
            score += 0.3 * (cap - next_item_size as f64).abs();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residuals into classes of 10
    // (capacity fractions). Small classes (0..=10) are near-perfect fits.
    let post_class = post_residual / 10;
    match post_class {
        0 => score -= 60.0,                    // residual <= 10: excellent closure
        1 => score -= 35.0,                    // 11..20: good
        2 => score -= 15.0,                    // 21..30: decent
        3 => score -= 5.0,                     // 31..40: mild
        4 | 5 => { score += 10.0; }            // 41..60: mediocre dead space
        _ => { score += 25.0; }                // >60: very wasteful placement
    }

    // Modulo coupling: exact-fit bonus when post_residual is a multiple of
    // common small item sizes (harmonic alignment with likely future items).
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        else if post_residual % 5 == 0 { score -= 5.0; }
        else { score += 3.0; }
    } else {
        score -= 80.0; // perfect fill
    }

    // Lookahead: reward if next item fits the post_residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_left = post_residual - next_item_size;
        score -= 20.0 + (next_left as f64) * 0.3;
        if next_left % 10 == 0 && next_left > 0 { score -= 8.0; }
    } else if next_item_size > post_residual {
        // Next item won't fit here regardless; slight penalty for tiny leftover
        if post_residual < 10 && post_residual > 0 { score += 8.0; }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: neutral baseline; discourage unless open bins are
    // fragmented (mean residual large relative to item) or few bins fit.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.25 * mean_residual
            + 4.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score += 30.0; // keep using the last fitting bin instead
        }
    }

    // Stream progression: later in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_class as f64 / 10.0).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item (>=10, or >=1 under
    // the interface note) can use are pure waste. Penalize unusable gaps hard.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fill: strong reward.
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space: nothing can ever fill it. Heavy penalty scaled by gap size.
        score += 60.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual < 30 {
        // Small gap: only small items can use it; moderate penalty.
        score += 12.0 + (30 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Open-bin pressure: prefer compacting into existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.6;

    // Bias toward bins whose residual is close to the mean (balanced closing),
    // penalize bins with unusually large residual when many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15 * (open_bins_count as f64 / 10.0).min(1.0);

    // Last-chance bin: if this is the ONLY fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    // (chain packing); if next item is large and would leave this bin stranded,
    // slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 15.0; // near-perfect chain
            } else {
                score -= 10.0 / (1.0 + slack as f64 * 0.1);
            }
        } else {
            // Next item won't fit here anyway; residual becomes dead space
            // unless large enough for other items.
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // New-bin candidate: opening a bin is only attractive when no existing bin
    // offers a decent fit (i.e., this call sees a full residual) or when the
    // item is large and tight fits are unlikely later.
    if bin_residual == bin_capacity {
        let base = 35.0 + pressure * 0.3;
        // Discourage opening when a last-chance bin exists.
        let last_chance = fitting_bins_count == 1 && bin_residual == bin_capacity;
        if last_chance {
            score += 0.0; // neutral marker; open-bin call judged against others
        }
        score = base - fill_frac * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item nearly fills the residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        if fill_ratio > 0.95 {
            score -= 60.0 * fill_ratio;
        } else if fill_ratio > 0.7 {
            score -= 25.0 * fill_ratio;
        }
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Next item fits exactly-ish: strong reward.
            let slack = post - next;
            if slack <= 5.0 {
                score -= 45.0;
            } else {
                score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            let overshoot = next - post;
            score += 10.0 + 0.5 * overshoot.min(50.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill.
    let tightness = mean_residual - post;
    score += 0.3 * tightness.max(0.0);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let item_rel = item_size as f64 / bin_capacity as f64;
        // Large items are fine to start a new bin with; small items waste it.
        let relief = if item_rel > 0.5 { 25.0 } else { 0.0 };
        score += base_penalty - relief;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference to consolidate across fewer bins.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // More competing fitting bins => mild penalty to avoid fragmentation.
    if fitting_bins_count > 1 {
        score += 2.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * next_fit;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual likely dead space relative to next item; penalize if large.
        score += 0.15 * post_residual as f64;
    }

    // Global state coupling: if mean residual is high, prefer filling fuller bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (mean_residual / bin_capacity as f64) * 4.0 * (1.0 - t);

    // Time horizon: later in stream, be more conservative about residual waste.
    score += t * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: prefer opening a new bin only when fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slight penalty so it's chosen only when
        // existing bins have bad fits.
        score += 8.0;
        if next_item_size > 0 {
            score -= 0.05 * next_item_size as f64;
        }
    }

    // Mild preference to keep bins balanced across the open set.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let mut score = post_residual as f64;

    // Non-linear coupling: tight fits are rewarded more as stream progresses.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight * (0.5 + progress);

    // Penalize dead space quadratically, amplified by stream progress.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead * (0.5 + progress);

    // Favor exact-ish fits when the next item could use the leftover.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0).exp() * (1.0 - progress);
    }

    // Last-chance bin bonus: avoid opening new bins when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly penalize early, mildly reward late.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 8.0 * progress * progress;
    }

    // Smooth interaction with mean residual: prefer bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "awkward" residue classes modulo common item-size divisors (10/20/25/50).
    let pr = post_residual;
    if pr > 0 {
        // Perfect-fit reward (zero waste).
        score -= 25.0;

        // Small dead space classes: residuals that cannot host even the smallest
        // item (pr < 10) are nearly worthless.
        if pr < 10 {
            score += 20.0;
        }

        // Harmonic classes: residual divisible by 50 or 25 keeps future pairing options.
        if pr % 50 == 0 {
            score -= 12.0;
        } else if pr % 25 == 0 {
            score -= 6.0;
        }
        if pr % 20 == 0 {
            score -= 4.0;
        } else if pr % 10 == 0 {
            score -= 2.0;
        }

        // Dead zone: residuals in (60..bin_capacity) are hard to fill with
        // large items; penalize mildly since item sizes cap around 80.
        if pr > 60 && pr < 90 {
            score += 3.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if next item cannot fit, penalize (bin becomes dead).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - pr).min(30) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // placement into existing bins would be very poor. Penalize opening a
    // new bin, more so when good fits exist or bins are few.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 - 20.0 * pressure;
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer tighter bins: relative fill fraction of the chosen bin.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill;

    // Mild preference for bins below mean residual (balance the pool).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // Gap too small for any item (min size 1..100, but tiny gaps are waste).
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - pr / 20.0);
    }

    // Reward tight fits (small post_residual relative to bin).
    let fill_ratio = item_size as f64 / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Soft reward proportional to how well next item uses the gap.
        let use_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 8.0 * use_ratio;
    } else if next_item_size > post_residual {
        // Next item won't fit in this gap: penalize if gap is stranded.
        score += 6.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin is neutral-ish but should lose to
    // good fits in existing bins; it wins only when all open bins would strand space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins already fit the item.
        score = 55.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin anyway
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: opening new bin is justified if that bin's
            // post residual would be dead space.
            let cand_pr = (bin_residual - item_size) as f64; // same formula for that bin
            let _ = cand_pr;
            score += 0.0; // keep new bin slightly worse; last-chance bonus above decides
        }
        // If mean residual across open bins is small, existing bins are tight;
        // opening a new bin is more attractive.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    }

    // Mild stream-progression coupling: late in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / cap);

    // Penalize deviation from mean residual (prefer balanced bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // If next item fits exactly into post_residual, strongly favor this bin
        if post_residual >= next_item_size {
            score -= 50.0 + 45.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // post_residual too small for next item: penalize proportional to wasted potential
            score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below average (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize creating dead space below the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when open bins would leave large unusable residuals
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // late in stream, discourage opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0..1)
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness of fit: fraction of the bin consumed by this placement
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize small post-residuals that are still large enough to be "wasted"
    // (dead space: too small for typical items but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver: strongly penalize
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // marginal space
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill: big reward
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let reuse_quality = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * reuse_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this leftover: mild penalty proportional to leftover
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Scarcity pressure: when few bins fit, prefer tighter residual usage
    if fitting_bins_count > 0 {
        score -= 6.0 / fitting_bins_count as f64;
    }

    // Global state: if mean residual is high, prefer bins below mean (consolidate)
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 5.0 * dev;
    }

    // Time horizon: early on, be conservative with new bins (favor filling);
    // late in stream, allow new bins more readily since future reuse is limited
    let new_bin_bias = 20.0 - 25.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_bias.max(-10.0) + 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Slight preference for opening new bins when many open bins exist and
    // current fit is very poor (post residual large relative to capacity)
    if bin_residual != bin_capacity && post_residual as f64 > 0.6 * bin_capacity as f64 {
        score += 12.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, normalized and non-linearly shaped.
    let x = pr / cap;
    let mut score = x * x * (3.0 - 2.0 * x) * cap * 0.5 + pr * 0.35;

    // Reward tight fits (small post residual) with a smooth quadratic bonus.
    score -= (1.0 - x) * (1.0 - x) * cap * 0.4;

    // Coupling with stream progress: early on, tolerate slack; late, squeeze bins hard.
    score += progress * pr * 0.5;
    score -= progress * (1.0 - x) * cap * 0.3;

    // Dead-space penalty if post residual cannot fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr).min(cap) * (0.3 + 0.4 * progress);
        } else {
            score -= 0.2 * (pr - nx).min(cap) / cap * cap * 0.1;
        }
    }

    // Last-chance bonus: only one bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    }

    // Penalize crowded bin pools mildly; encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    // Coupling with mean residual: if this bin's residual is below mean, it's a good filler.
    let bin_res = bin_residual as f64;
    let dev = (bin_res - mean_residual) / cap;
    score += dev * dev * cap * 0.2 - dev * cap * 0.15;

    // New-bin candidate penalty: opening a fresh bin should only win when no decent fit exists.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += cap * (1.2 - 0.3 * fill) + (fitting_bins_count as f64) * 0.0;
        // Slightly cheaper to open a new bin late in the stream when open bins are fragmented.
        score -= progress * cap * 0.25;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 0.15 * cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract) when post_residual is exactly 0
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes: post_residual buckets via modulo arithmetic.
    // Residuals divisible by 10 are "usable" by the common size grid (items 1..100
    // often cluster on multiples of 10); odd/dead residuals are penalized.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 15.0; // aligned residual, reusable by grid-sized items
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else if pr < 10 {
        // tiny dead space: near-perfect fit, mildly reward
        score -= 10.0;
    } else {
        // non-aligned dead space penalty grows with how "odd" the residual is
        let oddness = (pr % 10) as f64;
        score += oddness * 0.8;
    }

    // Integer-division thresholds on post_residual: classify residual quality
    let pr_class = pr / 10; // 0..10 harmonic class
    match pr_class {
        0 => score -= 20.0,           // 0-9: almost full, great
        1 => score -= 10.0,           // 10-19: fits a small item
        2 | 3 => score -= 3.0,        // 20-39: decent
        4..=6 => { /* neutral 40-69 */ }
        _ => score += 5.0,            // 70+: wasteful placement in a big-residual bin
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if pr >= next_item_size {
            score -= (next_item_size as f64) * 0.3;
        } else {
            // next item cannot fit here: slight penalty proportional to wasted lookahead
            score += 4.0;
        }
        // Harmonic lookahead: next_item_size on same 10-grid as post_residual
        if next_item_size % 10 == 0 && pr % 10 == 0 && pr >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer open bins unless they are poor fits (large post_residual / dead space).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; scales slightly with how many bins open
        score += 30.0 + (open_bins_count as f64).sqrt() * 5.0;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // if next item is large, a fresh bin preserves flexibility
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: penalize placing into bins far from the mean residual
    // (keeps residuals homogeneous, easier future packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Progress-aware tightness bonus: as stream advances, value tight fits more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * (10.0 + 20.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward gaps that can still fit the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // gap too small for next item: dead space risk
        }
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Mild preference for tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late in stream: discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: eliminate score entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits with modest slack: moderate reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0;
    }
    // Next item does NOT fit: penalize proportionally to how much dead space we create.
    else if next_item_size > 0 {
        score += 150.0 + (next_item_size as f64) * 0.5;
    }

    // Compare post_residual relative to mean residual across open bins.
    // Leaving post_residual below mean suggests consolidating small leftovers elsewhere;
    // leaving post_residual far above mean wastes this bin's capacity.
    let pr = post_residual as f64;
    score += (pr - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening a new bin when open bins could still take the item,
    // unless the item is large and the fit is poor.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 80.0 + waste * 0.2;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 60.0; // big-item-first into fresh bin is fine
        }
    }

    // Early in stream: be slightly more conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let tightness = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that no typical item (>=1) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: bonus if next item fits in the post-residual.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u64) > (post_residual as u64) {
        // Penalize stranding space the next item cannot use.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the item is large and fits poorly elsewhere; otherwise discourage.
    if bin_residual == bin_capacity {
        score -= 8.0 * (item_size as f64 / bin_capacity as f64);
        score += 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // More open bins => less eager to open another.
        score += 2.0 * open_bins_count as f64;
    }

    // Global residual pressure: high mean residual means space is plentiful;
    // waste is cheaper, so slightly relax the penalty for larger post-residuals.
    let mean_r = mean_residual.clamp(0.0, bin_capacity as f64);
    let waste_tol = mean_r / bin_capacity as f64;
    score -= waste_tol * 5.0;

    // Mild preference for bins that are already relatively full.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let post_residual = bin_residual as f64 - item_size as f64;
    let mut score = post_residual;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in?
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0.0 .. 1.0

    // Penalize residuals in "awkward" bands that few item sizes can fill.
    // Items are 1..100, so residuals <= 100 are always fillable in principle;
    // but small leftovers (< next_item_size) are dead space for the lookahead.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Cannot host the next item: dead-space penalty, worse the smaller it is.
            score += 12.0 * (1.0 - pr / (next_item_size.max(1) as f64));
        } else {
            // Reward exact harmonic coupling: post_residual is a near multiple of next_item_size.
            let k = (pr / next_item_size as f64).round();
            let dev = (pr - k * next_item_size as f64).abs();
            score -= 6.0 * (1.0 - dev / (next_item_size as f64));
        }
    }

    // Modulo-16 harmonic classes on post_residual: bins whose leftover lies in
    // "chunky" classes (multiples of 16) pair well with mid-size items.
    let m = post_residual % 16;
    if m == 0 {
        score -= 3.0;
    } else if m >= 13 {
        score += 2.5; // near-empty slivers are hard to fill
    }

    // Fractional capacity bands: prefer leaving ~half or ~quarter bins.
    if (0.45..=0.55).contains(&frac) {
        score -= 4.0;
    } else if (0.2..=0.3).contains(&frac) {
        score -= 2.0;
    } else if frac < 0.1 && post_residual > 0 {
        score += 5.0; // nearly-full bin: fine, but tiny slivers are useless
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // and mean residual is large (fragmentation already high).
        let frag = (mean_residual / c).clamp(0.0, 1.0);
        score = 55.0 - 25.0 * frag - 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // If the item is huge relative to capacity, opening fresh is safer.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Tight fits are golden: minimal waste gets rewarded.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Mild tie-break toward fuller bins overall.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest item are pure waste — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits (post_residual small relative to capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins with already-low residual being consumed further
    // if the leftover could not fit the lookahead item — dead space trap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward if the post residual exactly/nearly accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidation
    // into existing bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // penalize dumping into loose bins.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Slight late-stream urgency to close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, with a mild non-linear penalty on wasted space.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Aggressive 2-step lookahead: reward exact matching of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step packing: this bin becomes exactly full after next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this one; reward proportionally to the resulting leftover.
            let two_step_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
            if two_step_left == 0 {
                score -= 40.0; // both items exactly fill the bin
            }
        } else {
            // Next item cannot follow in this bin: penalize dead-end residuals.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Coupling with mean residual: bins far below mean residual are "more filled";
    // favor them slightly, penalize bins with unusually large residual.
    if mean_residual > 0.0 {
        score += 0.25 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item fits poorly everywhere else. Give the empty bin a mild handicap so
    // reasonable fits into existing bins win.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Lookahead pairing in a fresh bin: allow opening a new bin when the
            // next two items can pair there efficiently.
            score -= 22.0;
        }
    }

    // Late-stream pressure: consolidate as the stream ends to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later
    // (typical items are >= 1, but small slivers below ~15 are often wasted).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Lookahead: if the next item fits into the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Waste: next item cannot use this residual.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Mild penalty when many bins compete: prefer keeping options open.
        score += (fitting_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Prefer filling bins with larger residuals relative to the mean
    // (consolidate emptiness into few bins).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score += (rel - 1.0) * 5.0;
    }

    // Early in the stream, favor opening new bins less; late, prefer using open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early (keep bins closed), discount late.
        score += 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // But if it's a big item and no open bin fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for bins that would end up nearly full.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let fit_ratio = item / cap;                       // how full the bin becomes
    let pr_norm = pr / cap;                           // normalized dead space after placement

    // Base: prefer small post_residual, with a non-linear (quadratic) penalty
    // that grows super-linearly as dead space increases.
    let mut score = pr + 30.0 * pr_norm * pr_norm;

    // Reward tight fits: coupling of fill ratio with stream progress.
    // Early in the stream keep bins flexible; later, chase tight fits hard.
    score -= 25.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Smooth interaction: dead space penalized more when it cannot hold the
    // lookahead item (smooth logistic-style gate instead of hard threshold).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        let gate = 1.0 / (1.0 + (-gap / 10.0).exp()); // ~0 if next item won't fit, ~1 if it will
        score += 12.0 * pr_norm * (1.0 - gate);        // penalize stranded residuals
        score -= 8.0 * gate * fit_ratio;               // reward chains of compatible fits
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin when a decent option exists).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // New-bin candidate handling: make an empty bin mildly attractive only when
    // no open bin offers a good fit; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr).max(0.0);
        score += 10.0 - 6.0 * (mean_gap / cap);        // empty bin worse when open bins are roomy
        score += 5.0 * (1.0 - progress);               // early stream: opening fresh bins is okay
    }

    // Mild pressure against bin proliferation late in the stream.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Harmonic class of post_residual: reward residuals that fall into
    // "nice" divisor classes of capacity (0, 10, 20, 25, 50) - reusable slots.
    let nice = |r: u32| r == 0 || r % 10 == 0 || r % 25 == 0 || r % 50 == 0;
    if nice(post_residual) {
        score -= 8.0;
    } else if post_residual < 10 && post_residual > 0 {
        // dead space: unusable for min item size 1..10 typical
        score += 6.0;
    }

    // Integer-division thresholds: how many more "typical" items fit?
    let fits_again = post_residual / item_size.max(1);
    score -= 3.0 * fits_again as f64;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here: slight penalty for tight packing now
            score += 2.0;
        }
        // modulo coupling: next item shares harmonic class with post_residual
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize spreading when many bins open and mean residual is high
    if mean_residual > 30.0 && post_residual as f64 > mean_residual {
        score += 4.0;
    }

    // New-bin candidate: only attractive when current item nearly fills it
    if bin_residual == bin_capacity {
        if fill_frac > 0.8 {
            score -= 20.0;
        } else if fill_frac < 0.5 {
            score += 25.0;
        } else {
            score += 5.0;
        }
    }

    // Progress-based tightening: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual that no plausible future item (min size 1..=10) can use is dead space.
    if post_residual > 0 {
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Perfect fit strongly rewarded.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64) * 12.0;
        }
    }

    // Open bins pressure: penalize spreading across many open bins,
    // but relax when this bin is the last chance (fitting_bins_count == 1).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 4.0 * (1.0 - progress * 0.5);
    if fitting_bins_count == 1 {
        score -= 20.0; // last-chance bin: strongly prefer using it
    } else {
        score += pressure;
    }

    // Deviation from mean residual: prefer bins that are already fuller than average.
    let mean_dev = mean_residual - bin_residual as f64;
    score += mean_dev * 0.3;

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or current open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if item_size as f64 > 0.7 * bin_capacity as f64 || avg_fill > 0.85 {
            score -= 30.0;
        } else {
            score += 35.0; // discourage opening new bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize wasted space nonlinearly.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: fill bin completely over two steps
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 - gap * 0.5; // good lookahead fit, penalize leftover gap
        } else {
            // next item won't fit here; small penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
    }

    // Compare post_residual to mean residual: keep residuals balanced.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate: prefer existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 5.0 + 15.0 * progress;
        // Opening a new bin is attractive only for large items with poor fits elsewhere.
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Strongly reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let wasted = (post_residual - next_item_size) as f64;
            score -= (1.0 - wasted / bin_capacity as f64) * 10.0;
        } else {
            // Next item won't fit here anyway; slight penalty for leaving large gaps
            // that nothing in the near stream can use.
            score += post_residual as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 12.0;
        // If many open bins have small residuals, opening new bins is wasteful.
        if mean_residual < 25.0 {
            score += 10.0;
        }
        // If this item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild preference for bins below mean residual (keeps balance, avoids
    // fragmenting already-small bins into unusable slivers).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Penalize leaving residuals in the awkward 1..=9 range (dead space most
    // item sizes cannot use).
    if post_residual >= 1 && post_residual <= 9 {
        score += 10.0;
    }

    // Slight reward for using bins when many are open (reduce bin count).
    if open_bins_count > 4 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (low post residual), with non-linear shaping.
    let mut score = x * (1.0 + 0.8 * (1.0 - x) * (1.0 - x));

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins moderately (leave room); later, insist on tight fits.
    let coupling = (1.0 - progress) * (x - 0.35) * (x - 0.35) * 6.0
                 - progress * (1.0 - x) * (1.0 - x) * 4.0;
    score += coupling;

    // Penalize dead space relative to mean residual (smooth quadratic interaction).
    let dead = (x * cap - mean_residual) / cap;
    score += 0.5 * dead * dead;

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let nx = next_item_size as f64 / cap;
        score -= 2.0 * nx * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 0.3 * progress;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Mild penalty for spreading across many open bins (encourages consolidation).
    score += 0.02 * open_bins_count as f64 * x;

    // New-bin candidate: neutral-ish baseline with progress-dependent threshold.
    if bin_residual == bin_capacity {
        score = 0.9 + 1.2 * (1.0 - progress) + 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
