pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving gaps that could still fit a typical next item.
    if post_residual >= 10 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 50.0).max(0.0);
    }
    // If next item cannot fit the leftover, mild penalty for tight fits.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // New bin candidate: penalize mildly unless current fits are terrible.
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Next item fits into post residual -> moderate reward, scaled by tightness
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.3;
    }

    // Next item does NOT fit into post residual -> penalize dead space creation
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize bins with residual far below mean residual (fragmented bins)
    let resid = post_residual as f64;
    if resid < mean_residual {
        score += (mean_residual - resid) * 0.25;
    } else {
        score -= (resid - mean_residual) * 0.05;
    }

    // Tight fits (small post residual) are generally good, but avoid tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 25.0;
    }

    // Early in stream: be more willing to open new bins (keep options open)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins already open or early stream
        score += 10.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 18.0; // new bin can host both current and next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    if post_residual > 0 {
        score -= 12.0 * (item_size as f64 / post_residual as f64);
    } else {
        score -= 25.0; // perfect fit
    }

    // Penalize large dead space that nothing (min size 1) can later use.
    if post_residual < 10 && post_residual > 0 {
        score -= 8.0; // near-perfect fit bonus
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when fits are poor.
        score += 30.0;
        // If the item fits badly in existing bins (large post residual),
        // opening a fresh bin becomes attractive.
        let wasted = bin_residual - item_size;
        if wasted >= 25 {
            score -= wasted as f64 * 0.6;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins: prefer consolidation.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Reward reusing bins whose residual is close to mean (keep spread small).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 3.0 / (1.0 + dev * 0.1);
    }

    // Lookahead: if next item would fit the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits (within 5), mild reward.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(5) && post_residual < next_item_size {
        score -= 3.0;
    }

    // Slight preference for filling emptier bins when few fit options exist.
    if fitting_bins_count <= 2 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), non-linearly scaled
    let mut score = norm_pr * norm_pr * cap;

    // Smooth polynomial coupling with stream progress: late in the stream,
    // waste is penalized more heavily (fewer chances to fill dead space)
    let progress_waste = norm_pr * (0.5 + 2.0 * progress * progress);
    score += progress_waste * cap * 0.5;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 8.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Dead-space penalty: post_residual too small for typical future items
    if pr > 0.0 && pr < next_item_size as f64 && next_item_size > 0 {
        score += 10.0 + 10.0 * progress;
    } else if next_item_size > 0 && pr >= next_item_size as f64 {
        // Reward bins that can still host the lookahead item
        score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mean-residual coupling: placing into a bin below mean residual
    // balances load smoothly (quadratic in deviation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 4.0 - dev * 3.0;

    // New-bin candidate handling: mildly penalize opening a new bin early,
    // but allow it late when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 12.0 - 10.0 * progress - 8.0 * fragmentation;
    }

    // Slight preference for fewer open bins (consolidation pressure)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space classes
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // capacity fraction remaining

    // Penalize small-but-unusable residuals (dead space) via smooth sigmoid bump
    if post_residual > 0 {
        let dead = (12.0 - post_f).max(0.0) / 12.0; // residuals <=12 are near-dead
        score += 30.0 * dead * dead;
    }

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class: quantize post residual into capacity eighths
    let class = (post_residual * 8 / bin_capacity) as f64;
    score -= 4.0 * class; // prefer bins whose leftover falls in a "large" class (reusable)

    // Modulo logic on residual: residuals that are multiples of common item sizes are reusable
    let reusable = (post_residual % 10 == 0) as f64 + (post_residual % 20 == 0) as f64;
    score -= 6.0 * reusable;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next fits but not perfectly: partial reward scaled by fit tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap_f;
            score -= 20.0 * tight;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 8.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter fits generally: reward small post residual relative to mean residual
    score -= (mean_residual - post_f).max(0.0) * 0.5;

    // Mild pressure against opening new bins late in stream when many bins open
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost, adjusted by open bins pressure and progress
        score = 55.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin always fits next item
        }
    }

    // Integer division threshold: residuals in [13..=25] are moderately usable
    if post_residual >= 13 && post_residual <= 25 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) <= dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item (k=2) if it fits exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0;
            if slack == 0 {
                score -= 25.0; // sets up a perfect fit for the next item
            } else if slack <= dead_zone as u32 {
                score += (slack as f64) * 3.0; // but avoid leaving dead space after that
            }
        } else {
            // The next item won't fit here regardless; slight penalty for tight bins
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 3.0;

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins) so large residuals stay available for large items.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: only attractive when current bins fit poorly
    // (large item, few fitting bins) or early in the stream.
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0) || (item_size >= 60 && fitting_bins_count <= 1);
        if poor_fit || (open_bins_count == 0) {
            score -= 20.0;
        } else {
            // Prefer existing bins otherwise; scale reluctance with open bins.
            score += 15.0 + (open_bins_count as f64) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how tightly it fits.
            let tightness = (post_residual - next_item_size) as f64;
            score -= 200.0 - tightness * 0.5;
        } else {
            // Next item does not fit: penalize dead space that the lookahead can't use.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize large post residuals relative to mean residual (wasteful bins).
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap > 0.0 {
        score += mean_gap * 0.3;
    } else {
        score -= mean_gap.abs() * 0.1;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when no open bin
    // offers a decent fit (post_residual too small to be useful).
    if bin_residual == bin_capacity {
        // Base preference for reusing existing bins.
        score += 150.0;
        // But if the item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 100.0;
        }
        // If many open bins already exist with low mean residual, discourage new bin.
        if mean_residual < 20.0 && open_bins_count > 1 {
            score += 100.0;
        }
    }

    // Late in the stream, be slightly more conservative with residual waste.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space: residuals too small for any future item (min item ~1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving post_residual that fits next item, penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when open bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0)).max(0.0);
        score = 55.0 + 20.0 * progress - 0.5 * crowded;
        // If item is large relative to capacity, opening fresh bin is safer.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
        // If next item is large too, fresh bin preserves room.
        if next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild time-horizon coupling: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates far above the mean (fragmented outliers).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 30.0 * poly * (0.5 + progress);

    // Penalize wasted dead space more as stream advances
    score += 8.0 * pr_norm * pr_norm * progress;

    // Reward tight fits (small post residual)
    score -= 12.0 * (1.0 - pr_norm).powi(3) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (nx / cap);
        } else {
            score += 6.0 * ((nx - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (mod-10 classes) ---
    let post_class = post_residual % 10;
    // Residuals that are "harmonically useful": multiples of 10 or small leftovers
    let class_bonus = match post_class {
        0 => 6.0,               // perfect harmonic class, highly reusable
        1..=3 => 2.0,           // near-harmonic, mildly reusable
        4..=6 => 0.0,           // neutral
        7..=9 => -2.0,          // dead-space prone classes
        _ => 0.0,
    };
    score -= class_bonus;

    // --- Integer-division thresholds on post_residual ---
    // Reward filling a bin to a quarter / half / three-quarter boundary exactly
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;
    let filled = bin_capacity - post_residual;
    if filled % quarter == 0 {
        score -= 4.0; // lands exactly on a capacity fraction
    }
    if post_residual < quarter {
        score += 3.0; // tiny leftover is nearly dead space
    }

    // --- Tight fit reward ---
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item also fits here: strong chaining bonus
            score -= 8.0;
            // extra bonus if next item closes the bin completely
            if next_item_size == post_residual {
                score -= 6.0;
            }
        } else {
            // next item won't fit: penalize based on the gap class
            let gap = next_item_size - post_residual;
            score += (gap % 10) as f64 * 0.4 + 1.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0; // only bin that fits: strongly prefer it over new bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when current bin's post-fit residual
        // would be a bad harmonic class or the fit is loose.
        let loose = post_residual > half;
        let bad_class = post_class >= 7;
        if loose || bad_class {
            score -= 5.0; // prefer opening a fresh bin
        } else {
            score += 15.0; // keep using existing good bins
        }
        // Late in the stream, avoid spreading across many bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 8.0;
        }
    }

    // --- Mean residual coupling ---
    // Prefer bins whose residual is below the mean (tighter bins) for big items
    if (item_size as f64) > 50.0 {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // --- Many open bins: encourage consolidation ---
    if open_bins_count > 5 {
        score += 0.5 * open_bins_count as f64 * 0.0 + (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Post-residual that can still fit the next item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // dead space relative to lookahead
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: fewer open bins -> prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (1.0 + progress);

    // Prefer bins tighter than average (compact packing)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain (post_residual == next_item_size) gets the biggest bonus.
        if gap == 0.0 {
            score -= 60.0;
        } else if gap <= 10.0 {
            score -= 40.0 - gap * 2.0;
        } else {
            // Mild reward proportional to how much of the leftover the next item absorbs.
            let absorb = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * absorb;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space creation,
        // scaled by how large the unusable gap is.
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += (dead / (next_item_size as f64)) * 20.0;
        }
        // Small leftovers (<10) are nearly useless dead space.
        if dead < 10.0 {
            score += (10.0 - dead) * 1.5;
        }
    }

    // Penalize bins whose residual is far above the mean (they are likely to stay fragmented)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild preference for compacting into few bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    // Prefer filling bins that are already fairly full (low residual relative to capacity).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness;

    // New-bin candidate: keep it neutral-to-slightly-poor so it only wins when
    // all open bins are genuinely bad fits (large dead space penalties above).
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; residual becomes dead space.
            let dead = post_residual as f64;
            score += 10.0 * (dead / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progression.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 + 30.0 * progress;
        // Cheaper to open a new bin when many bins are open with poor residuals.
        if mean_residual < 25.0 && open_bins_count > 0 {
            new_bin_cost -= 20.0;
        }
        // If item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            new_bin_cost -= 35.0;
        }
        score = new_bin_cost + (bin_capacity - post_residual) as f64 * 0.0;
    }

    // Mild global pressure: when mean residual is high, prefer reusing full-ish bins.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) - norm_pr * (0.5 + t);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * t;

    // Penalize dead space relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + t);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for too many open bins early (encourage consolidation)
    score += 0.5 * (open_bins_count as f64) * (1.0 - t);

    // New-bin candidate: prefer opening a fresh bin only when fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 + 60.0 * (1.0 - tightness) * (1.0 - t) + 40.0 * t * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable"
    // by common item classes (integer division thresholds on capacity).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Dead-space penalty: residuals below the smallest useful class are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward landing exactly on a harmonic boundary (perfect fit classes).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % quarter == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    }

    // Class penalty: post_residual in awkward mid-range (just over half) is dead-ish.
    if post_residual > half && post_residual < three_quarter {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // reward small leftover relative to next item
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot fit here; penalize proportionally
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * open_bins_count as f64;
        // but if the item is large, opening fresh is fine
        if item_size > three_quarter {
            score -= 45.0;
        }
    }

    // Prefer fuller bins as stream progresses (mild schedule).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Prefer bins tighter than the mean residual (better packing).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 200.0;
    } else if post_residual < next_item_size.max(min_item) && next_item_size > 0 {
        // gap cannot host the lookahead item: mild penalty scaled by tightness
        score += 15.0 * (1.0 - post_residual as f64 / (next_item_size as f64 + 1.0));
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 30.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_residual as f64);

    // Last-chance bonus: only one bin can fit the item, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new bins / prefer filling.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead synergy: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize residuals too small for the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: if the next item exactly fills post_residual, huge bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: bonus proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty scaled by overflow amount.
            let overflow = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * overflow;
        }
    }

    // Reward tight fits relative to current bin residual (wasted-space ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 80.0 * fit_ratio;

    // Coupling with mean residual: bins with residual below mean are "scarce space",
    // using them is good; bins far above mean can wait.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 40.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // the item is large relative to capacity or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = (item_size as f64 / 100.0) * 90.0;
        // Empty bin competes: attractive early / for big items, unattractive later.
        score += 70.0 * (1.0 - progress) - large_item_bonus;
        // Discourage opening new bins when many bins already fit the item.
        score += 25.0 * (fitting_bins_count as f64);
    }

    // Slight preference for consolidating among many open bins.
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr_norm * (1.0 + 0.8 * pr_norm * pr_norm);

    // Polynomial coupling with stream progress: dead space matters more later.
    score += 3.0 * progress * pr_norm * pr_norm;

    // Coupling with mean residual: placing into a bin whose residual is far
    // from the mean is penalized quadratically (prefer typical bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (pr - nxt) / cap;
        let match_term = (slack.abs()).min(1.0);
        score += 1.2 * match_term * match_term * (1.0 - progress);
        if pr >= nxt {
            score -= 0.6;
        }
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * (open_bins_count as f64).sqrt() * pr_norm;

    // New-bin candidate: neutral-ish score that competes only when fits are bad.
    if bin_residual == bin_capacity {
        score = 2.0 + 2.5 * progress + 0.02 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: small dead space in
    // classes {0, 5} is reusable; classes {1,2,3,4} and {6..9} are dead-ish.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,
        5 => score -= 6.0,
        1 | 2 | 3 => score += 8.0 + (4 - class) as f64,
        4 => score += 4.0,
        6 | 7 | 8 | 9 => score += 3.0,
        _ => {}
    }

    // Harmonic threshold via integer division: post_residual buckets of 10
    let bucket = pr / 10;
    if bucket >= 1 && bucket <= 3 {
        score += 5.0 * (4 - bucket) as f64; // small-but-usable leftovers mildly penalized
    } else if bucket >= 8 {
        score -= 4.0; // large residual = bin still very usable
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            // harmonic class of gap
            if gap % 10 == 0 {
                score -= 20.0;
            } else if gap % 5 == 0 {
                score -= 10.0;
            } else {
                score += (gap % 10) as f64 * 0.8;
            }
        } else {
            // next item cannot use leftover: penalize proportionally to dead fraction
            score += (pr as f64 / bin_capacity as f64) * 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        };
        score = bin_capacity as f64 - 25.0 * poor_fit - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0; // new bin can host next item too
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are worthless.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0; // hard penalty for unusable slivers
    }
    if pr == 0.0 {
        score -= 40.0; // perfect fit is always best
    }

    // Mid-range residuals (10..=20) can still host small items: mild reward.
    if pr >= 10.0 && pr <= 20.0 {
        score -= 5.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using an existing bin when bins are scarce.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless it enables a perfect
    // chain with the lookahead item (item + next fits exactly).
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0; // perfect two-item chain in fresh bin
            } else if gap < 10 {
                score -= 20.0;
            }
        }
        if next_item_size > 0 && next_item_size == item_size && item_size * 2 == bin_capacity {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score += (10.0 - gap as f64) * 1.5; // would create sliver for later
        }
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize post_residual (tight packing).

    // Aggressive 2-step lookahead: reward a post_residual that exactly
    // matches the next item size (perfect chain fit).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * lookahead_gap;
        if post_residual == next_item_size {
            score -= 25.0; // exact chain match: strongly favor
        }
        // Penalize post_residual that is too small for the next item
        // (dead space the next item cannot use).
        if post_residual < next_item_size {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual above the mean can
    // absorb waste more easily; slightly penalize using them.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Dead-space penalty: very small post_residual is good (tight fit),
    // mid-range leftovers are the worst.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which already scores high. Add a mild bias so a new bin is opened
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Late in the stream, be more conservative about opening bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Base: prefer tight fits (small post_residual) ---
    score = post_residual as f64;

    // --- Perfect fit bonus ---
    if post_residual == 0 {
        score -= 500.0;
    }

    // --- Dead-space penalty: residual too small to hold the smallest plausible item ---
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // creates unusable sliver
    }

    // --- Lookahead: strongly reward residuals that can host the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainability bonus scaled by how snugly the next item would fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack * 0.5;
        } else {
            // Penalize if placing here strands the next item into a new bin
            score += 25.0;
        }
    }

    // --- Last-chance pressure: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // --- Many open bins: consolidate, prefer filling existing bins tighter ---
    let crowding = open_bins_count as f64;
    score += (mean_residual - post_residual as f64) * 0.4 * (1.0 + crowding / 50.0);

    // --- Time horizon: early on, be selective (leave room for big items); late, just pack ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if progress < 0.4 {
        // early: penalize large items eating fresh bins? reward placing big items in tight bins
        score += fill_ratio * 20.0 * (1.0 - progress);
    } else {
        // late: urgency to close out bins, reward high fill
        score -= fill_ratio * 40.0 * progress;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin: acceptable when no open bin fits well.
        // Slightly worse than a good existing fit, slightly better than a bad one.
        score = bin_capacity as f64 * 0.55 + item_size as f64 * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin can also host next item
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        }
        if progress > 0.7 && mean_residual < item_size as f64 {
            score -= 40.0; // late stream, existing residuals are poor anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual), non-linearly scaled
    let mut score = r;

    // Smooth non-linear coupling: waste penalized more heavily as stream progresses
    score += 40.0 * norm_r * norm_r * (0.5 + progress);

    // Cubic waste term: dead space is exponentially bad late in the stream
    score += 25.0 * norm_r.powi(3) * progress;

    // Reward near-perfect fits with a smooth saturating bonus
    let tightness = 1.0 - norm_r;
    score -= 30.0 * tightness.powi(4);

    // Last-chance bin: strongly favor using it (avoid opening a new bin needlessly)
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * tightness;
    }

    // Lookahead coupling: if next item fits in post_residual, bonus (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (nx <= r) as i32 as f64;
        let slack_match = 1.0 - ((nx - r).abs() / cap).min(1.0);
        score -= 18.0 * fits_next * slack_match * (1.0 - progress);
        // Penalize leaving residual that no plausible next item uses
        score += 8.0 * norm_r * (1.0 - slack_match);
    }

    // Many open bins: mild penalty for spreading residual thin (encourage consolidation)
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_r;

    // Mean residual deviation: prefer bins whose residual stays near the fleet mean
    score += 5.0 * (r - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a fresh bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 12.0 + 60.0 * (1.0 - progress);
        // But allow opening when item is large and would leave tiny waste
        score -= 45.0 * tightness * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: prefer residuals in "usable" classes
    // (large enough to host typical items). Class penalty grows for dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional class of post_residual w.r.t. capacity
    let frac = pr / cap;
    // Integer-division thresholds: residuals divisible into common item sizes
    let class10 = post_residual % 10;
    let class20 = post_residual % 20;
    let class25 = post_residual % 25;

    // Reward residuals that are multiples of common sizes (easy future fits)
    if class10 == 0 { score -= 6.0; }
    if class20 == 0 { score -= 4.0; }
    if class25 == 0 { score -= 4.0; }
    // Penalize awkward remainders (dead-space classes)
    score += 0.35 * (class10 as f64);
    if class20 > 0 && class20 < 10 { score += 3.0; }

    // Dead space threshold: residuals below smallest item size are pure waste
    if pr < 10.0 && pr > 0.0 { score += 40.0; }
    if pr == 0.0 { score -= 25.0; } // perfect closure is excellent

    // Large leftover fraction is good (bin stays flexible)
    if frac > 0.5 { score -= 8.0 * frac; }
    else if frac < 0.2 { score += 10.0 * (0.2 - frac); }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 35.0; }
        else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            score -= 12.0 * (nxt / pr);
            // harmonic match: post_residual % next small
            let m = post_residual % next_item_size;
            score -= 5.0 * (1.0 - (m as f64) / (next_item_size as f64));
        } else {
            // next item won't fit here; leftover becomes dead space risk
            score += 8.0;
        }
    } else {
        // last item in stream: just close tightly
        score -= 10.0 * (1.0 - frac);
    }

    // Stream progression: early on, keep bins flexible (favor tighter fills later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    // Prefer denser packing when many bins are open
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - frac);

    // New-bin candidate: mildly penalize so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small, likely-unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Open-bin pressure: penalize bins when many bins are open, favoring consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64) / 100.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / 100.0);
        }
    }
    // If next item cannot fit in the gap, mild penalty for creating stranded space.
    else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make opening a new bin moderately attractive only when
    // the item is large relative to remaining space or fits nowhere tightly.
    if bin_residual == bin_capacity {
        if post_residual < 20 {
            score += 80.0; // item nearly fills a bin: great new-bin candidate
        } else {
            score += 20.0 + open_bins_count as f64 * -0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let residual_f = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if (next_f - residual_f).abs() <= 5.0 {
            // Perfect chain: this bin's leftover exactly fits the next item.
            score -= 30.0 * (1.0 - residual_f / bin_capacity as f64);
        } else if next_f < residual_f {
            // Next item fits here later; mildly reward.
            score -= 6.0 * (residual_f - next_f) / bin_capacity as f64;
        } else {
            // Next item won't fit in leftover: penalize dead space relative to next item.
            score += 0.15 * (next_f - residual_f);
        }
    }

    // Compare against mean residual across open bins.
    if residual_f > mean_residual + 20.0 {
        // Using a much-fuller-than-average bin wastes little; reward.
        score -= 4.0;
    } else if residual_f < mean_residual - 20.0 {
        // Draining an already-sparse bin leaves many small holes; penalize.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Empty bin starts with score = capacity; make it unattractive unless the item
        // is large and would leave a bad fit elsewhere.
        score = bin_capacity as f64 * 0.9 + (item_size as f64) * 0.1;
        if item_size > 70 && fitting_bins_count <= 1 {
            score -= 20.0; // large items may justify a fresh bin
        }
    }

    // Late in the stream, consolidate: fewer open bins is better.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.05;

    // Slight preference for filling bins that are already committed (more wasted if abandoned).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual preferred).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;
    score -= 30.0 * (-fit_ratio * 3.0).exp();

    // Penalize dead space that can't fit the average future item.
    let mean_item = 55.0_f64;
    if (post_residual as f64) < mean_item {
        score += 8.0 * (mean_item - post_residual as f64) / mean_item;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits well. Penalize the fresh bin mildly so tight fits beat it.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Later in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Many open bins with slack: discourage opening yet another.
        if open_bins_count > 4 {
            score += 2.0 * (open_bins_count as f64 - 4.0).sqrt();
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual is just barely too small for next item, penalize waste.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 10.0; // placing item here blocks next item from this bin
        }
    }

    // Coupling with global residual state: prefer bins below mean residual
    // (consolidate slack into fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0 * (mean_residual - bin_residual as f64).sqrt();
    } else {
        score += 1.5 * ((bin_residual as f64) - mean_residual).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        let slack = pr - next_item_size as f64;
        score += 0.05 * slack * slack / cap;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, less late when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score += 12.0 - 10.0 * frag * progress;
    } else {
        score += 0.02 * (bin_residual as f64 - mean_residual);
    }

    // Mild diversity pressure on number of open bins
    score += 0.1 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // (small, or exactly matching common item-size classes).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0; // nearly full, dead space negligible
    } else if pr % 10 == 0 {
        score -= 12.0; // residual in a decadal class: likely reusable
    } else if pr % 5 == 0 {
        score -= 5.0;  // half-decadal class: moderately reusable
    } else {
        score += (pr % 5) as f64 * 2.5; // penalize odd dead space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 20.0;
        } else if next_item_size > pr {
            // next item cannot use this residual: residual is dead weight
            score += (pr as f64) * 0.15;
        }
    }

    // Integer-division thresholds: prefer leaving residuals that divide capacity
    // into useful chunks (capacity fractions).
    if pr > 0 && bin_capacity % pr == 0 {
        score -= 8.0; // residual is a divisor of capacity: harmonic
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open
        }
        // open more eagerly late in the stream? keep mild pressure
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Tightness bonus: bins that are already nearly full get priority.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 15.0;

    // Stream progression: early on, be pickier about wasted space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr as f64) * 0.1 * (1.0 - progress);

    // Mean residual anchoring: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // small gaps are heavily penalized
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is always desirable
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0; // moderately reusable residual
    }

    // Prefer tight fits: reward when item consumes a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are large/wasted
    // or the item would leave a bad gap everywhere else.
    if bin_residual == bin_capacity {
        // Baseline neutral score slightly above a perfect fit.
        score = 55.0 + 2.5 * open_bins_count as f64;
        // If mean residual across open bins is large (bins are roomy), opening
        // a new bin wastes capacity elsewhere -> penalize.
        score += 0.6 * mean_residual;
        // If the item would leave a tiny dead gap in this fresh bin, penalize.
        if post_residual > 0 && post_residual < 10 {
            score += 50.0 - 5.0 * post_residual as f64;
        }
        // Lookahead: if next item is small, current bins likely absorb it fine;
        // opening a new bin is less urgent.
        if next_item_size > 0 && next_item_size <= mean_residual {
            score += 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead synergy: if next item fits exactly into this bin's post-residual,
    // reward the placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0 + (5 - post_residual) as f64 * 4.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if gap <= 10.0 {
            score -= 25.0 - gap; // near-chain bonus, decaying with gap
        } else {
            score += gap * 0.3; // large leftover mismatch penalized mildly
        }
        // If next item cannot fit anywhere else, prefer keeping space for it
        if next_item_size > post_residual && gap > 10.0 {
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    // (tight bins) and penalize dumping into loose bins
    let res_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res_f - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins exist and fit well
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost; only attractive when item is huge
        // relative to typical residuals or stream is early with few bins
        score += 25.0;
        if item_size >= 60 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0; // slightly discourage new bins late in stream
    }

    // Mild preference for tighter residual bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size
    let fit_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += fit_ratio * 30.0;

    // Penalize leaving dead space that no typical item can fill
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fit bonus
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0; // awkward dead zone
    }

    // Lookahead: if the next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= post_residual + 15 {
        score += 12.0; // next item almost fits, wasted opportunity
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless existing bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0;
        // Open a new bin more readily early in the stream or when many bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if open_bins_count > 5 {
            score += 10.0;
        }
        // If item is large, new bin is attractive
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Global residual pressure: prefer bins below mean residual (fill fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Slight preference for bins with residual close to item (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer small post-residual, with a non-linear (quartic-ish) tightening
    let mut score = pr * (1.0 + 0.8 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, penalize residual space more aggressively.
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * prog_poly * (pr / cap) * (1.0 - pr / cap).powi(2) * cap * 0.1;

    // Reward near-perfect fits (small but nonzero post-residual) more mid/late stream
    if pr > 0.0 {
        score -= 6.0 * (-pr / (0.15 * cap)).exp() * (0.4 + 0.6 * prog_poly);
    }

    // Exact fit is ideal
    if pr == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * prog_poly;
    }

    // New-bin candidate: penalize mildly early, more late (prefer packing into open bins),
    // but allow it when mean residual of open bins is small (poor fits everywhere).
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 8.0 + 14.0 * prog_poly - 10.0 * mean_fill * mean_fill;
    }

    // Lookahead: if next item fits exactly into resulting residual, reward this placement
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 12.0;
    } else if next_item_size > 0 && (next_item_size as f64) < pr {
        // soft reward proportional to how well the next item uses the leftover
        let use_frac = next_item_size as f64 / pr;
        score -= 5.0 * use_frac * use_frac * prog_poly;
    }

    // Many open bins: slight preference to consolidate into fuller bins
    if open_bins_count > 1 {
        score += 0.5 * (open_bins_count as f64).ln() * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes are more reusable than "dead" residues.
    let post = post_residual as u32;
    if post > 0 {
        // Reward residuals that are harmonic (divisible by small sizes 10..50)
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post % d == 0 {
                harmonic_bonus += 8.0;
            }
        }
        score -= harmonic_bonus;

        // Penalize awkward small dead space: 1..=9 unusable slivers
        if post < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly
        score -= 60.0;
    }

    // Modulo-class coupling between post_residual and next_item_size:
    // if the next item can exactly consume the post residual, big reward.
    if next_item_size > 0 {
        if post >= next_item_size {
            if post % next_item_size == 0 {
                score -= 20.0;
            }
            // next item fits leaving a harmonic remainder
            let rem = post - next_item_size;
            if rem < 10 && rem > 0 {
                score += 10.0; // would create a sliver
            }
        } else {
            // post residual too small for next item: dead space risk
            score += (next_item_size - post) as f64 * 0.3;
        }
    }

    // Integer-division threshold on residual fraction of capacity
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post <= quarter {
        score += 5.0; // bin nearly full, low priority unless perfect fit already rewarded
    } else if post >= half {
        score -= 3.0; // roomy bin, prefer using it
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post_residual == capacity - item_size
        // add a mild opening cost, reduced late in the stream or when many bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 12.0 + 10.0 * (1.0 - progress) + 2.0 * open_pressure;
    }

    // Slight preference for bins tighter than the mean residual (better fit)
    if mean_residual > 0.0 {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it cannot hold a typical future item (assume min item ~1,
    // but tiny gaps relative to capacity are wasteful).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 500.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        // moderately awkward gap: penalize proportionally more than raw residual
        score += 2.0 * (30.0 - pr);
    }

    // If lookahead item fits in the post residual, big reward for chaining.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 150.0;
        // extra reward for near-perfect chaining
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 100.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // lookahead won't fit: the residual becomes dead space for the lookahead
        score += 0.5 * (next_item_size as f64 - pr).abs();
    }

    // Open-bins pressure: prefer consolidating into existing bins over opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening a new bin, scaled by how many bins already exist
        score += 80.0 + 12.0 * open_bins_count as f64;
        // if only one fitting bin exists, strongly discourage abandoning it
        if fitting_bins_count == 1 {
            score += 300.0;
        }
        // early in stream, new bins are cheaper (fewer alternatives)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    } else {
        // reward using a fitting bin, especially if it's the last chance
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
        // reward tight fits (small post residual already in base, amplify)
        score -= 0.3 * (bin_residual - item_size) as f64;
        // reward bins below mean residual (i.e., this bin is tighter than average)
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), normalized against capacity.
    score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose residual after
    // placement can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain fit (post_residual == next_item_size) is gold.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how close next item is to filling leftover.
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow: penalize dead space creation.
            score += 15.0 + 0.25 * (next_item_size as f64);
        }
    } else {
        // Last item: pure tightness.
        score -= 10.0;
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving less than average is good (compact bins), more is wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current fit is awful.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only for very tight fits or when
        // no open bin fits well (fitting_bins_count small).
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 10.0 * openness;
        if item_size >= 50 {
            // Large items pair well with fresh bins (room for the follower).
            score -= 20.0;
        }
        if post_residual as f64 > mean_residual + 20.0 {
            score += 10.0;
        }
    }

    // Slight stream-progression pressure: later in stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residuals.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Perfect / near-perfect fits get a strong discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize post-residuals that are awkwardly small but nonzero (dead space
    // too small for the minimum item size of 1..100 range: anything < 10 is
    // nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space for the known future item.
            score += 0.15 * post_residual as f64;
        }
        // If next item would fit exactly in the post-residual, big bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: minimize wasted space aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Penalty grows with number of open bins (bin proliferation).
        score += 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build capacity for future).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If next item is large and current fit is loose, new bin is more attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 12.0;
        }
    } else {
        // Existing bin: slight preference when it's below mean residual
        // (consolidate into emptier bins keeps tighter bins for tight fits).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild global pressure: as stream progresses, discourage wasteful placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: residual waste matters more as stream progresses
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5 + progress * progress;
    score *= progress_coupling;

    // Reward near-exact fills via smooth exponential decay of residual
    score -= 12.0 * (-pr / 8.0).exp();

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).powi(2));
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Penalize opening new bins when many bins fit, reward when scarce
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (fitting_bins_count as f64);
        score -= 5.0 * (-mean_residual / cap).exp();
    }

    // Mild pressure against many open bins with large residuals
    score += 0.05 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity fraction band does post_residual fall in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Class 0: post_residual in (0, eighth] -> nearly dead space, heavy penalty
    if post > 0 && post <= eighth {
        score += 18.0;
    }
    // Class 1: (eighth, quarter] -> poor usability
    else if post <= quarter {
        score += 7.0;
    }
    // Class 2: (quarter, half) -> moderate
    else if post < bin_capacity / 2 {
        score += 2.0;
    }
    // Class 3: exact harmonic residues are gold (0, cap/2, cap/4, 3cap/4)
    if post == 0 {
        score -= 25.0;
    } else if post == bin_capacity / 2 {
        score -= 12.0;
    } else if post == quarter || post == 3 * quarter {
        score -= 6.0;
    }

    // Modulo coupling: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 && post > 0 {
        let nxt = next_item_size;
        if nxt <= post {
            // lookahead fits: reward if it fills harmonically (multiple or near-exact)
            let rem = post % nxt;
            if rem == 0 {
                score -= 10.0;
            } else if rem <= eighth {
                score -= 5.0;
            } else {
                score += 2.0;
            }
            // if next item would exactly fill bin after this placement
            if nxt == post {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residue: penalize wasting a big bin on small item
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline score = capacity; prefer it only when no good fit exists.
    // Penalize new bin slightly when existing bins fit well.
    if bin_residual == bin_capacity {
        score = cap - 5.0;
        if fitting_bins_count >= 1 {
            score += 6.0;
        }
        // late in stream, opening bins is cheaper than fragmenting
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score -= 4.0;
        }
    }

    // Prefer fuller bins: tighter fit relative to mean residual
    if mean_residual > 0.0 {
        let tightness = (post as f64) / mean_residual;
        if tightness < 0.5 {
            score -= 3.0;
        } else if tightness > 1.5 {
            score += 3.0;
        }
    }

    // Many open bins: encourage consolidation into emptier bins
    if open_bins_count > 6 {
        score += (post as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (1..=12) are heavily penalized since few items (>=10 originally,
    // small here) can ever use them.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    } else if post_residual > 12 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins below mean residual (filling emptier bins consolidates).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for the next item -> dead space risk.
        score += 12.0;
    }

    // New-bin candidate: only attractive when no open bin offers a tight fit
    // (i.e., all fits would leave large dead space). Penalize mildly otherwise.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 1 {
            score -= 70.0; // opening a bin is fine if nothing else fits well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: next item exactly fills the post-residual -> excellent chaining.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 220.0;
        } else if next_item_size < post_residual {
            // Next item fits, but tighter is better: reward closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the post-residual: penalize dead space proportionally.
            score += 0.5 * (post_residual as f64) * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins whose residual is already below the mean (consolidating tight bins).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { (next_item_size as f64 / bin_capacity as f64).min(1.0) } else { 0.5 };
        // Base penalty so open bins win unless they leave big waste.
        score += 60.0;
        // Early in the stream, opening bins is cheaper; late, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If the next item is large, a fresh bin is more valuable.
        score -= 30.0 * pressure;
        // Many open bins -> discourage opening more.
        score += 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // future item can reuse this bin's leftover
        } else {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 1.5 * open_bins_count as f64;
        // Early in the stream new bins are cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight pull toward bins whose residual is near the mean (keeps residuals uniform).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fill is nearly as good
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate slack less.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = 2.0 + 6.0 * p2 + 8.0 * p3;
    score += coupling * norm_pr * norm_pr * cap;

    // Reward near-exact fills with a smooth quartic bump.
    let fill = 1.0 - norm_pr;
    score -= 30.0 * fill * fill * fill * fill;

    // Lookahead: penalize if next item fits smoothly in post_residual (good chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack * slack);
    } else if next_item_size > post_residual {
        score += 4.0 * progress;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when bin is far below mean residual (keeps bins balanced).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = cap * (1.5 + progress) - 20.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins partitioned by residual magnitude classes.
    // Class 0: perfect fit (residual 0) -> strongest reward.
    // Class 1: tiny dead space (1..=5) -> still great.
    // Class 2: medium (6..=15).
    // Class 3: large (16..=30).
    // Class 4: wasteful (>30).
    let post_class = if post_residual == 0 {
        0u32
    } else if post_residual <= 5 {
        1
    } else if post_residual <= 15 {
        2
    } else if post_residual <= 30 {
        3
    } else {
        4
    };
    score -= match post_class {
        0 => 60.0,
        1 => 40.0,
        2 => 18.0,
        3 => 5.0,
        _ => 0.0,
    };

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // small item sizes (10, 20, 25, 50) are reusable -> reward them.
    if post_residual > 0
        && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0)
    {
        score -= 12.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect reuse of leftover space: big reward.
        let slack = post_residual - next_item_size;
        score -= 25.0 + (slack as f64).min(20.0) * 0.3;
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // Next item would have fit before this placement but not after: penalize.
        score += 15.0;
    }

    // Last-chance bin: this is the only bin that can fit the item -> strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: prefer tighter fits (post_residual already does this),
        // add slight penalty to spread competition.
        score += 2.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it unattractive
    // unless the item fits poorly everywhere. Base penalty grows with how many bins
    // are already open (bin consolidation pressure).
    if bin_residual == bin_capacity {
        let consolidation = (open_bins_count as f64) * 3.0;
        // If the item is large relative to capacity, new bin is more acceptable.
        let size_relief = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += 70.0 + consolidation - size_relief;
    }

    // Fractional capacity coupling: reward placements that push the bin toward
    // harmonic fill fractions (50%, 75%, 90%+).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill >= 0.9 {
        score -= 20.0;
    } else if fill >= 0.75 {
        score -= 10.0;
    } else if fill >= 0.5 {
        score -= 4.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is "tight" and should be used now (reward); if far above mean, it's roomy
    // and can wait (mild penalty), keeping roomy bins for future large items.
    let diff = mean_residual - post_residual as f64;
    score += (diff * 0.25).clamp(-10.0, 10.0);

    // Stream progression: late in the stream, close bins aggressively (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_class as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the next item
    // (or the smallest plausible item) are wasted space -> heavy penalty.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 2.0;
    }

    // Perfect or near-perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual tightly matches the item (good fit quality).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Lookahead: if placing here leaves room exactly for the next item, favor it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // (applied to the empty-bin candidate, residual == capacity).
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        // If the stream is nearly done, opening fresh bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 12.0;
    } else {
        // Mild reward for filling existing bins when open-bin count is high.
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins with below-mean residual (more full bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack (<= 10) is still very good.
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit in this residual: penalize proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits relative to current residual (small post_residual is good).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * frac * frac;

    // Penalize bins far above mean residual (they waste space) mildly.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when it enables a perfect lookahead fit
    // (post_residual == bin_capacity - item_size is full residual; compare with next item).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 40.0;
        } else {
            // Neutral-to-slightly-negative baseline; early stream favors consolidation.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 12.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: reward tight fits nonlinearly.
    let fit_tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * fit_tightness * fit_tightness;

    // Penalize residuals that become "dead space" (small and hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward leaving a residual that exactly or nearly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot go here; penalize blocking good residual space.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more willing to spread items (keep bins flexible);
    // late in the stream, consolidate aggressively to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: if many bins are open relative to mean residual, penalize
    // adding to bins with large leftover space (encourage filling low-residual bins).
    if open_bins_count > 0 {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * rel;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (this call's bin_residual == bin_capacity) or when
    // open bins are mostly full and the item is large.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; make it competitive but not free.
        score = (bin_capacity - item_size) as f64 + 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin leaves room for the next item too.
            score -= 3.0;
        }
        // If several bins already fit, discourage opening a new one.
        if fitting_bins_count >= 2 {
            score += 18.0;
        }
        // Late in the stream, prefer closing existing bins over opening new ones.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pn = pr / bin_capacity as f64;
    let t = progress;
    let coupling = pn * pn * (1.0 - t) * (1.0 - t) + pn * t * t;
    score += 20.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - t) * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * t;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (0.5 + t);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * t;

    // Encourage leaving residuals near mean (balance)
    score += 0.3 * (pr - mean_residual).abs() * t;

    // New-bin candidate: prefer only when residuals are badly fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).min(1.0);
        score = 60.0 + 40.0 * (1.0 - frag) - 30.0 * t * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);

    // Harmonic class of the post residual: modulo classes on small divisors.
    // Residuals divisible by 10/20/25 are "harmonic" — likely to be filled by
    // future items exactly, so reward them; awkward classes get penalized.
    let h = post_residual as i64;
    let mut harmonic_reward = 0.0;
    if post_residual == 0 {
        harmonic_reward += 30.0; // perfect closure
    } else {
        if h % 10 == 0 { harmonic_reward += 6.0; }
        if h % 20 == 0 { harmonic_reward += 3.0; }
        if h % 25 == 0 { harmonic_reward += 3.0; }
        if h % 50 == 0 { harmonic_reward += 2.0; }
        // awkward primes / odd classes
        if h % 2 == 1 { harmonic_reward -= 1.0; }
        if h % 3 == 1 { harmonic_reward -= 1.5; }
    }

    score -= harmonic_reward;

    // Strongly favor near-perfect fits (post residual tiny)
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Penalize leaving dead space that no typical item can use:
    // post_residual in (bin_capacity*0.5, bin_capacity) is very wasteful only
    // if it exceeds the max plausible item; use capacity fraction thresholds.
    let half = bin_capacity / 2;
    if post_residual > half && post_residual < bin_capacity {
        score += 4.0 * ((post_residual - half) as f64 / half as f64);
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // harmonic check on the chain: post - next leaves a good class
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 { score -= 5.0; }
            if r2 == 0 { score -= 10.0; }
        } else {
            // next item cannot follow here; slight penalty for blocking
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin offers a decent fit (item is large relative to mean residual)
    // or the stream is early and we want many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // opening a new bin wastes the mean residual of all others
        let waste = mean_residual * (open_bins_count as f64).sqrt();
        score = 60.0 + waste * 0.8 - item_frac * 30.0 - progress * 10.0;
        // if the item would leave a harmonic residual in a fresh bin, soften
        if item_size % 10 == 0 { score -= 8.0; }
        if item_size == bin_capacity { score -= 50.0; }
    }

    // Mild preference for bins already tighter than average
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward leaving a gap exactly matching the next item (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty proportional to open bins pressure.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // If few fitting bins, new bin is less penalized.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        score -= 30.0;
    }

    // Prefer bins with residuals below the mean (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, slightly prefer tighter fits to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fits (tight packing).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if fit_ratio < 0.05 {
        score -= 60.0;
    } else if fit_ratio < 0.12 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 55.0; // perfect chain: item + next item exactly fills bin
        } else if gap <= 5.0 {
            score -= 35.0;
        } else if gap <= 15.0 {
            score -= 15.0;
        }
        // Penalize leaving a residual that neither fits next item nor is small.
        if post_residual < next_item_size && post_residual > 0 && fit_ratio > 0.15 {
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more when good fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 25.0 + 8.0 * pressure.min(6.0);
        // But if next item is large and no bin will chain well, allow new bin.
        if next_item_size >= 60 && fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild early-stream bias toward keeping bins open (flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual by capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 2.5 * (1.0 - tightness) * (1.0 - tightness);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving dead space that no plausible future item can use.
    // Items are >= 1, but typical useful chunks: if post_residual is small but nonzero,
    // it's likely dead. Penalize post_residual in a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 18.0 - 0.15 * leftover_after_next as f64;
        if leftover_after_next == 0 {
            score -= 25.0; // chained perfect fit
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use the leftover: leftover likely dead
        score += 6.0 + 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Encourage filling bins when many bins are open (bin consolidation pressure)
    score -= 0.8 * (post_residual as f64 / bin_capacity as f64) * open_bins_count as f64;

    // Global mean residual coupling: placing in a bin below mean residual is good
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more willing to open new bins (keep options);
    // late in stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: high, but decreases with progress
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        // If no open bin fits well (post_residual of this empty bin is capacity - item_size)
        let empty_post = bin_capacity - item_size;
        if empty_post == 0 {
            new_bin_cost -= 60.0; // item fills a fresh bin perfectly
        }
        // If many bins open and item is large, opening fresh bin is attractive
        if item_size > bin_capacity / 2 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Slight penalty for very large leftovers relative to typical small items
    if post_residual > 60 && post_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize wasted space, with non-linear polynomial shaping
    let mut score = x * (2.0 + 4.0 * x * (1.0 - x));

    // Smooth coupling: small post residuals are more valuable late in the stream
    let tightness = 1.0 - x;
    score -= 6.0 * tightness * tightness * progress;

    // Reward filling bins tightly when few bins can fit the item (last-chance bonus)
    if fitting_bins_count == 1 {
        score -= 3.0 * tightness;
    }

    // Penalize bins with residuals far below the mean residual (fragmentation)
    let dev = (mean_residual - pr) / cap;
    score += 1.5 * dev * dev;

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill_after_next = (pr - nx) / cap;
            score -= 2.0 * (1.0 - fill_after_next);
        } else {
            // post residual too small for next item: penalize unusable sliver
            score += 1.0 * (1.0 - x) * (nx / cap);
        }
    }

    // Slight preference for consolidating into fewer bins when many open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate: make empty bin mildly attractive only when item is large
    // or no good fit exists; otherwise prefer filling open bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score = 1.2 - 0.8 * large_item * large_item + 0.5 * progress;
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class: tiny unusable residues (harmonic class r in 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo-10 harmonic class of the leftover: residues that are "nice"
    // multiples/divisors of common item sizes are more reusable
    score += (post_residual % 10) as f64 * 0.5;
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // next item exactly fills the leftover -> strong bonus
        if next_item_size == post_residual {
            score -= 40.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Tight placement reward: bigger item fraction = better space usage
    score -= (item_size as f64 / cap) * 10.0;

    // Brand-new empty bin candidate: pay an opening premium, discounted
    // for large items that would fragment open bins anyway
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 25.0 - ((item_size as f64 - 0.5 * cap).max(0.0));
        // mid-stream, large items justify fresh bins more
        if item_size > 60 && step_index > 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0; // penalize creating a dead gap
    } else if post_residual == 0 {
        score -= 150.0; // perfect fit is ideal
    } else {
        // Usable gap: reward tight-but-usable fits
        score -= 0.5 * (post_residual as f64).ln();
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    if bin_residual != bin_capacity {
        score += 3.0 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (consolidate fullness).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect match — item + next item exactly fills the bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // next item still fits here; penalize leftover gap after both items
            let two_step_left = (post_residual - next_item_size) as f64;
            score += 0.35 * two_step_left;
            // reward moderately for keeping next item placeable
            score -= 25.0;
        } else {
            // next item won't fit: dead space penalty grows as post_residual shrinks
            score += 12.0 + 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer packing into bins that are already relatively full (small residual)
    score += 0.8 * (mean_residual - post_residual as f64);

    // Slight preference for filling existing bins over opening new ones
    // as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    // Penalize new-bin candidate mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Non-linear penalty for tiny unusable remnants
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit flavor: reward tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small unusable dead space (post residual too small to matter later).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 14.0 - 0.08 * slack_after_next as f64;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Next item won't fit here anyway; slight bonus for dumping large item here.
        score -= 3.0;
    }

    // Last chance bin: avoid opening a new bin if this is the only one that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Time horizon: early in stream, prefer keeping residuals large (flexibility);
    // late in stream, prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;
    score -= progress * 4.0 * (bin_residual - post_residual) as f64 / item_size.max(1) as f64;

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > 20.0 {
        let consolidation = ((post_residual as f64) - mean_residual).abs();
        score -= 0.06 * mean_residual - 0.04 * consolidation;
    }

    // New-bin candidate: only attractive when nothing fits well or item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) < mean_residual * 0.5;
        if poor_fit_elsewhere {
            score -= 6.0 + 0.05 * item_size as f64;
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear tightening: later in the stream, residual space matters more (compact early, avoid waste late)
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score *= 1.0 + 0.8 * urgency;

    // Reward near-perfect fits with a strong non-linear discount
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(6);

    // Lookahead: bonus if the next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - urgency);
        } else {
            // penalize leaving a residual too small for the next item (dead space)
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste * (0.5 + urgency);
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 20.0;
    }

    // Penalize scarce fitting options less if this bin is the only one (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are quite full
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 30.0 + 25.0 * mean_fullness - 10.0 * urgency;
    } else {
        // favor bins with residuals below the mean (consolidate emptier bins)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0 * (1.0 - urgency);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // capacity-fraction buckets. Small residuals are "harmonically useful"
    // (they pair with small items); large residuals waste capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Integer-division class: residual divided into capacity/8 buckets.
    let class = (post_residual / (bin_capacity / 8).max(1)) as f64;
    score += class * 2.0;

    // Strongly penalize residuals that are too small to ever fit a typical
    // item (below ~1/10 capacity) -> dead space.
    if frac > 0.0 && frac < 0.10 {
        score += 40.0 * (0.10 - frac);
    }

    // Reward near-perfect fits (tiny residual).
    if post_residual <= 3 {
        score -= 25.0;
    } else if frac <= 0.05 {
        score -= 12.0;
    }

    // Harmonic pairing: does next_item_size fit exactly-ish into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Reward when next item leaves an even smaller residual (chained fit).
            let next_post = pr - nxt;
            score -= 8.0 * (1.0 - next_post / cap);
            // Perfect chaining: next item exactly fills the bin.
            if next_post <= 3.0 {
                score -= 15.0;
            }
            // Modulo harmony: post_residual divisible-ish by next size.
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: mild penalty scaled by gap.
            score += 3.0 * ((nxt - pr) / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): baseline score = full capacity.
    // Make it attractive only when open bins are very full on average.
    if bin_residual == bin_capacity {
        score = cap * 0.85;
        if mean_residual < 12.0 && open_bins_count > 0 {
            score -= 10.0; // open bins nearly exhausted -> open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // big next item coming, keep big space free
        }
        if step_index as f64 / (total_items as f64).max(1.0) > 0.9 {
            score += 15.0; // late in stream, avoid opening bins
        }
    }

    // Tightness coupling: prefer bins whose residual is closest to the item
    // (best-fit flavor) via a non-linear term.
    let tight = 1.0 - (item_size as f64 / bin_residual as f64);
    score += 10.0 * tight * tight;

    // Mean-residual coupling: when open bins are generally roomy, discourage
    // spreading items thin.
    if mean_residual > 40.0 && bin_residual < mean_residual {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's too small for the smallest plausible future item (1..100 range),
    // but calibrated against the known item floor of the stream via next_item_size lookahead.
    let dead_threshold = 10.0; // gaps below smallest historical item size are near-useless
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in the residual, this bin wastes future capacity; penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Open bins pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual leaves
    // other bins with large residuals; mild reward for using high-residual bins.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so as stream progresses.
        score += 30.0 + progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
