        } else if next_item_size < post_residual {
            // next item fits: better if small leftover after chain
            let chain_left = post_residual - next_item_size;
            score -= 25.0 - chain_left as f64 * 0.6;
        } else {
            // next item does NOT fit: penalize large post_residual (dead space)
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
