        score += 10.0;
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
        // but if no open bin can fit, allow opening (fitting_bins_count counts open bins)
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // allow new bin when item would leave awkward tiny residual in any open bin
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Slight penalty for leaving unusable slivers
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling: post_residual squared scaled by progress
    // (late in the stream, dead space is penalized harder)
    score += norm_pr * norm_pr * cap * (0.25 + 1.5 * progress);

    // Cubic interaction: strongly avoid tiny unusable residuals,
    // especially near the end of the stream
    score += norm_pr.powi(3) * cap * progress;

    // Smooth reward for near-perfect fits (post_residual close to 0)
    let perfect = (-norm_pr * 4.0).exp();
    score -= perfect * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= cap as f64 * 0.5 * (0.5 + progress);
    }

    // New-bin candidate: attractive early, penalized later;
    // penalize opening a new bin when it would waste lots of space
    score += is_new * cap * (1.2 - 1.6 * progress) * (0.5 + 0.5 * norm_pr);

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            let fit_quality = 1.0 - (slack / cap).abs();
            score -= nxt * fit_quality * (0.2 + 0.5 * progress);
        } else {
            score += (-slack) * (0.3 + 0.4 * progress);
        }
    }

    // Mild pressure to consolidate: many open bins with high mean residual
    score += (open_bins_count as f64).sqrt() * mean_residual * 0.02 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals that fall into "small" harmonic
    // classes (near 0) are excellent placements -> subtract a bonus.
    let frac = post_residual as f64 / bin_capacity as f64;
    // class index via integer division thresholds on post_residual
    let class = post_residual / (bin_capacity / 8); // 8 harmonic classes: 0..7
    let class_bonus: f64 = match class {
        0 => 14.0, // post_residual < 12.5 : nearly perfect fit
        1 => 9.0,  // < 25
        2 => 5.0,  // < 37.5
        3 => 2.5,
        4 => 1.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Modulo coupling: residuals divisible into small chunks are reusable.
    let m12 = post_residual % 12;
    if m12 == 0 {
        score -= 3.0;
    } else if m12 <= 2 {
        score -= 1.5;
    } else if m12 >= 10 {
        score += 1.0; // awkward remainder
    }
    let m5 = post_residual % 5;
    if m5 == 0 {
        score -= 1.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this leftover: mild penalty proportional
            // to how much dead space would be stranded
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins
        // (prefer filling existing bins when they are reasonably tight).
        let mut new_bin_cost = 10.0 + 0.6 * open_bins_count as f64;
        // If no existing bin fits well (post_residual large relative to
        // item), opening a fresh bin is fine: reduce the cost.
        if post_residual > bin_capacity / 2 {
            new_bin_cost -= 4.0;
        }
        // Early in the stream, opening bins is cheaper (build a portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= 4.0 * (1.0 - progress);
        score += new_bin_cost;
    }

    // Coupling with mean residual: placing into a bin whose residual is
    // far below the mean (i.e., a tight bin) is desirable.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.08 * dev;

    // Penalize leaving residual in the "worst" harmonic band
    // (just above half capacity) which is hard to fill later.
    if post_residual > bin_capacity / 2 && post_residual <= (bin_capacity * 5) / 8 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that can fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // gap too small for next item: penalize proportionally to how close we were
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Favor bins with below-average residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early stream: be more conservative about filling bins (keep flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * fit_ratio;
    }
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = next_item_size as f64 / post_residual as f64;
        score -= 30.0 * lookahead_fit * lookahead_fit;
        if next_item_size == post_residual {
            score -= 60.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving a residual too small for the next item (dead space risk).
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste.min(30.0);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is huge or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_everywhere = fitting_bins_count == 0
            || (item_size as f64 / bin_capacity as f64) > 0.9;
        if tight_everywhere {
            score -= 50.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post-residual is small relative to item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 6.0;

    // Penalize large dead space that no realistic item can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // perfect-ish fit bonus
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_gain = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 18.0 * chain_gain;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: slight penalty proportional to leftover.
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global state coupling: when many bins are open with slack, discourage spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        let spread_penalty = (mean_residual - post_residual as f64).abs() * 0.15 * (open_bins_count as f64).sqrt();
        score += spread_penalty;
    }

    // Time horizon: early in the stream, be more willing to open bins (explore);
    // late in the stream, consolidate aggressively.
    let new_bin_call = bin_residual == bin_capacity;
    if new_bin_call {
        let exploration = (1.0 - progress).powf(2.0);
        // New bin attractive only if no open bin offers a decent fit.
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.55;
        let base = 30.0 + post_residual as f64 * 0.5;
        if poor_fit_elsewhere {
            score = base - 20.0 * exploration;
        } else {
            score = base + 22.0 * (1.0 - exploration) + 8.0 * (fitting_bins_count as f64);
        }
    }

    // Mild preference for bins with residual close to mean (balanced usage).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post-residual, mildly super-linear so tighter fits are favored.
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth non-linear coupling of residual with stream progress:
    // later in the stream, residual waste is penalized more aggressively.
    let progress_coupling = (post / cap).powi(2) * (0.5 + 1.5 * progress) * cap * 0.35;
    score += progress_coupling;

    // Reward near-perfect fills (post_residual close to 0) with a smooth bump.
    let tightness = (-post / (0.15 * cap)).exp();
    score -= 6.0 * tightness * (0.6 + 0.4 * progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 3.0 * snug;
        } else {
            // Next item won't fit: penalize leaving residual that strands the next item.
            score += 1.5 * (1.0 - post / cap);
        }
    } else {
        // Last item: strongly favor minimizing final residual.
        score += 2.0 * post;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and later in the stream (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - progress);
        // If item is large relative to capacity, new bin is less bad.
        score -= 4.0 * (item / cap);
        // If mean residual across open bins is small, opening a bin is more justified.
        score -= (mean_residual / cap).min(1.0) * 3.0;
    }

    // Mild penalty when many bins are open and residual is wasted (dead space).
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Mean-residual deviation: prefer bins whose residual deviates smoothly
    // from the fleet mean (keeps residuals homogeneous, better future packing).
    let dev = (post - mean_residual).abs() / cap;
    score += 1.2 * dev * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable" sizes
    // (small residuals are dead space; residuals divisible by common item sizes are reusable).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, excellent
    } else {
        // divisibility bonuses: residual reusable by common small items
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 5 == 0 { score -= 2.0; }
        // dead-space penalty: residuals too small for the smallest plausible item
        if pr < 10 {
            score += 30.0 + (10 - pr) as f64 * 2.0;
        } else if pr < 20 {
            score += 10.0;
        }
        // harmonic class via integer division thresholds
        let class = pr / 15; // 0..6 coarse classes
        score += class as f64 * 1.5;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual > item_size as f64 * 1.2 {
            score += 20.0; // plenty of usable space elsewhere; don't open new bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere, must open
        }
    } else {
        // reward tight fits in existing bins
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
        // favor fuller bins as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (bin_capacity - bin_residual) as f64 * 0.1 * progress;
    }

    // mild preference to consolidate when many bins are open
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are worthless; residuals below the typical item scale are heavily penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable gap -> dead space
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Reward filling most of the bin (tight fit).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if post_residual - next_item_size < 10 {
            score -= 12.0; // chaining two items into near-perfect fit
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // next item won't reuse this bin
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with below-mean residual (tighter bins get priority).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a bin is penalized mildly; but if the item is large and
        // residuals are fragmented, opening a fresh bin is reasonable.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 10.0;
        } else {
            score += 12.0 + 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward leaving exactly the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is highly desirable.
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize residuals too small for the next item (dead space risk).
        if (post_residual as i64) < (next_item_size as i64) {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize tiny unusable residuals relative to the item-size floor.
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild bias toward consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * open_bins_count as f64 / 10.0;

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to fill ratio after placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize large unusable dead space (post residual too small for typical future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin is fine actually; small residual is good
    }
    // Correct: small post_residual is desirable; instead penalize mid-range dead space.
    if post_residual >= 10 && post_residual <= 25 {
        score += 8.0 * (1.0 - fill);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here; bin will close anyway
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage closing bins (prefer small residual) rather than spreading.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln() * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Global mean residual coupling: if this bin's residual is below mean, it's a good tighter bin.
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Time horizon: early in stream, be more willing to open fresh bins (new-bin candidate
    // gets a modest edge late; early we explore). Penalize new-bin candidate when many bins open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress); // early: new bins slightly discouraged (explore existing)
        score -= 4.0 * progress;         // late: fresh bins favored to keep bins clean
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / capacity;

    // Base: tight fits are good (low post residual => low score)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate larger residuals (keep flexibility).
    // Late in the stream: strongly penalize leftover dead space.
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * poly;

    // Cubic shaping: small residuals get extra reward, mid residuals penalized smoothly.
    let cubic = norm_pr * norm_pr * norm_pr - norm_pr;
    score += 25.0 * cubic * (0.5 + progress);

    // Lookahead: reward bins whose post residual matches the next item size.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 15.0 * (1.0 - gap / capacity) * (1.0 - progress);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 * progress * ((next_item_size as f64) - pr) / capacity;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // Slight bias toward consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Mean residual coupling: placing into a bin below mean residual tightens the fleet.
    score += 3.0 * (pr - mean_residual) / capacity * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline that is penalized unless it beats tight fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a
    // "useful" residue class (divisible by common small sizes) are valuable.
    let pr = post_residual;
    if pr > 0 {
        // Reward post-residuals that can host typical future items exactly.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Penalize dead-space classes: tiny unusable slivers.
        if pr < 5 {
            score += 12.0;
        } else if pr < 10 {
            score += 5.0;
        }
        // Integer-division threshold: leftover >= 20 is reusable; leftover
        // in (0,20) risks becoming waste unless it is a perfect fit class.
        if pr >= 20 && pr % 20 == 0 {
            score -= 4.0;
        }
    } else {
        // Perfect closure of a bin is excellent.
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into this bin's
    // post-residual, strongly favor this placement.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 18.0;
        } else if slack % 10 == 0 {
            score -= 9.0;
        } else {
            score -= 2.0 + (slack as f64).ln().max(0.0);
        }
    } else if next_item_size > pr {
        // Next item won't fit here; mild penalty for stranding capacity.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if post_residual < 10 && post_residual > 0 {
            score += 6.0; // but a near-full fit leaving slivers is bad
        }
    }

    // Capacity fraction logic: reward filling a large fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (high mean residual spread) or few bins can host the item.
        let pressure = (fitting_bins_count as f64).recip();
        let waste_urgency = if mean_residual > 60.0 { 0.0 } else { 10.0 };
        score = 45.0 + pressure * 20.0 + waste_urgency
            - (post_residual as f64) * 0.1
            - fill_frac * 5.0;
        // Late in the stream, prefer closing existing bins rather than
        // spawning new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If next item is large and this fresh bin would host it perfectly,
        // opening can be reasonable.
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Mild global pressure: with many open bins, prefer compacting into
    // existing ones rather than spreading.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // A gap is "dead" if it's too small for the smallest plausible item (1..100 range),
    // but especially gaps < ~10 are useless; gaps in (0, 20) are risky.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // pure dead space, almost nothing can fill it
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if item_size > 0 && bin_residual == item_size {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0; // bin remains usable for the next item
        } else {
            score += 12.0; // next item can't use this bin: gap likely wasted
        }
    }

    // Tightness coupling: prefer bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (post_residual very small already penalized above).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // But still avoid creating dead space: extra penalty if gap is tiny.
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones; with few open bins, new bins are cheaper.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of already-open bins.
        score += 15.0 + 4.0 * ob;
        // Early in the stream, opening bins is fine; late in the stream, avoid it.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
        // If a decent fit exists elsewhere, don't open a new bin.
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 50.0; // (post_residual==0 impossible for empty bin; keeps new-bin unattractive)
        }
        // A new bin is attractive only if remaining space after placement is large
        // and no bin fits well (fitting bins give better scores via rewards).
        score += 0.10 * mean_residual;
    } else {
        // Slight reward for using existing bins, scaled by open-bin pressure.
        score -= 3.0 + 1.5 * ob;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits into the post residual, reward it;
    // otherwise penalize leaving a residual that wastes the next item's fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also be packed here: chain reward, scaled by tightness.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 - chain_waste * 1.5;
        } else {
            // Dead space relative to the lookahead item.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 2.0;
            // Small residual that nothing (min size 1..100 unknown) can use is worse.
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it loses to decent fits,
        // but wins over bins that would leave large unusable residuals.
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin can host the next item too: mild discount.
            score -= 40.0;
        }
        // Late in the stream, consolidating into open bins matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Coupling with mean residual: prefer bins whose post residual is close to
    // the mean (balanced packing), penalize outliers creating fragmented space.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.5;

    // Prefer fuller bins overall (relative fill reward).
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Slight penalty when many bins are open: encourage closing bins out.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Reward using a bin whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score -= (bin_capacity as f64 - gap) * 0.25;

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving awkward large-ish residue.
            score += (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).abs() * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is attractive when item is
    // large relative to typical residuals and many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        let openness = mean_residual / bin_capacity as f64;
        // Penalize new bin when existing bins fit well (small gap), reward it
        // when residuals are fragmented and item is large.
        score += 20.0 + 15.0 * (1.0 - progress) - 25.0 * openness - 10.0 * big_item * crowding;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin can also host next item
        }
    }

    // Mild penalty for wasting space relative to global mean residual
    // (prefer bins below-average residual for big items).
    score += (mean_residual - post_residual as f64) * 0.1;

    // Time-horizon modulation: late in stream, tighten up (avoid sprawl).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: penalize residual non-linearly, weighted by stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * last_chance * (1.0 - norm_pr);

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            let fit_quality = 1.0 - gap / cap;
            score -= 12.0 * fit_quality * fit_quality * (1.0 - progress);
        } else {
            score += 5.0 * (-gap / cap);
        }
    }

    // Slight preference for consolidating into existing bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 3.0 * ((bin_residual as f64 - mean_residual.abs()).abs() / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Reward post_residuals that are reusable sizes (harmonic classes):
    // residuals like 0, 10..=40 in multiples of 5 are more likely to fit future items.
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual <= 40 && r10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual <= 50 {
        score -= 6.0;
    } else if post_residual < 10 {
        score += 15.0; // tiny dead space, unusable
    } else if post_residual > 50 {
        score += 8.0; // large leftover suggests poor packing choice
    }

    // Penalize awkward residues mod 25 (dead zones between typical item sizes).
    if r25 == 24 || r25 == 23 {
        score += 4.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large or the fit is exact.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Penalize opening a new bin unless the item is big (leaves little waste relative to capacity).
        if item_size < 50 {
            score += 18.0;
        }
        if post_residual == 0 {
            score -= 40.0;
        }
        // Fewer open bins => opening new bins is cheaper.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (below the smallest useful gap) are heavily penalized.
    let min_useful_gap = 10.0f64.min(bin_capacity as f64);
    if post_residual > 0 && (post_residual as f64) < min_useful_gap {
        score += (min_useful_gap - post_residual as f64) * 12.0;
    }
    // Even usable-but-tight gaps get a nonlinear dead-space penalty.
    if post_residual > 0 {
        score += ((post_residual as f64) / bin_capacity as f64).powi(3) * 40.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin is attractive only if no open bin
    // fits well (post_residual here equals capacity, i.e. a fresh bin).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 45.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If many bins are open, prefer reusing.
        score += open_bins_count as f64 * 1.5;
    }

    // Lookahead coupling: if the residual left behind exactly accommodates the
    // next item, this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize leaving a residual the next item cannot use at all.
    if next_item_size > post_residual && post_residual > 0 && bin_residual != bin_capacity {
        score += 10.0;
    }

    // Slight nudge toward bins with residuals below the mean (consolidating fuller bins).
    score += ((mean_residual - bin_residual as f64) / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual small).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item exactly fills the post_residual, this is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let waste_after_pair = post_residual - next_item_size;
            score -= 30.0 - waste_after_pair as f64 * 0.8;
        } else {
            // Next item cannot use this residual: penalize leaving a gap it can't fill.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average when fitting bins are plentiful.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let rel = post_residual as f64 - mean_residual;
    score += rel * (0.4 + 0.4 * (1.0 - progress));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, be pickier about dead space.
        score += (post_residual as f64) * 0.15 * (fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate: keep it competitive only when open bins are badly fragmented
    // (high mean residual with few fitting bins suggests poor alternatives).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            ((mean_residual / bin_capacity as f64) - 0.5).clamp(0.0, 1.0)
        };
        score = 25.0 - desperation * 55.0;
    }

    score
}
